insert into research_todos select * from jsonb_populate_recordset(null::research_todos, '[{"id":"ec95f086-3c42-5356-926f-121cbb13e385","topic":"Select specific Kalman/EKF/UKF lecture videos","note":"Resolved: MATLAB ''Understanding Kalman Filters'' series and Shane Ross Part 1 verified via oEmbed and added.","track_id":"SF","task_id":null,"status":"done","created_at":"2026-10-25T12:00:00.000Z"},{"id":"e10a713c-8ca5-56b0-beea-6e4e52578a95","topic":"Select Articulated Robotics episodes for URDF → Gazebo → ros2_control","note":"Resolved: four Articulated Robotics episodes verified and linked to SIM-02 and AG-07.","track_id":"SIM","task_id":null,"status":"done","created_at":"2026-10-25T12:00:00.000Z"},{"id":"a0af23ac-0c86-50e2-a7ac-72115f08cb3c","topic":"Select a verified Nav2 configuration walkthrough video","note":"Resolved: Robotics Back-End crash course and The Construct waypoint videos verified. An official Nav2/ROSCon talk is still worth adding.","track_id":"NV","task_id":null,"status":"done","created_at":"2026-10-25T12:00:00.000Z"},{"id":"d04cf908-5fe4-5f6e-ae68-c77c72d2b6a9","topic":"Find a verified behavior-tree introduction talk","note":"Resolved: Davide Faconti''s ROSDevCon19 talk and Petter Ögren''s 5-minute tutorial verified.","track_id":"AG","task_id":null,"status":"done","created_at":"2026-10-25T12:00:00.000Z"},{"id":"4f1a2d22-15e1-5d62-a685-5ab3d9d97c21","topic":"Find verified material on LiDAR motion distortion (deskewing)","note":"Papers or lectures covering per-point timestamps and motion compensation for PM-02 / SF-03.","track_id":"PM","task_id":null,"status":"open","created_at":"2026-10-25T12:00:00.000Z"},{"id":"b1176d3f-1e53-554a-9209-50e5bdbc4858","topic":"Locate the current Lunabotics guidebook (2026–2027 cycle)","note":"Arena dimensions, zone layout and autonomy scoring must come from the official guidebook, not from other teams'' code.","track_id":"SIM","task_id":null,"status":"open","created_at":"2026-10-25T12:00:00.000Z"},{"id":"47e10121-1ddc-5062-8f1f-8ac97bc6da94","topic":"Verify OpenCV documentation deep links manually","note":"docs.opencv.org blocked automated checks (HTTP 403). Confirm in a browser and set the verified date.","track_id":"PM","task_id":null,"status":"open","created_at":"2026-10-25T12:00:00.000Z"},{"id":"d10fab6a-52c8-5119-9158-0487b9bb022c","topic":"Research radar sensors suitable for dust (SF-05/SF-07)","note":"No verified radar reference implementation exists yet in the seeded repositories. (SF-07 radar detection is now PM-09.)","track_id":"SF","task_id":null,"status":"open","created_at":"2026-10-25T12:00:00.000Z"},{"id":"943a309b-c9ca-5e8f-9132-89416f6376b5","topic":"Find a verified SLAM lecture series","note":"Resolved: Cyrill Stachniss''s SLAM introduction and graph-SLAM lectures verified and added.","track_id":"SF","task_id":null,"status":"done","created_at":"2026-10-25T12:00:00.000Z"},{"id":"05c2f870-01a7-5222-8a13-0c7127b3f9c9","topic":"Verified videos for remaining advanced tasks","note":"PM-07, PM-08, AG-09, AG-11, AG-12 and AG-13 still have no topic-specific verified video. Verify URL + channel (oEmbed) before adding.","track_id":null,"task_id":null,"status":"open","created_at":"2026-10-25T12:00:00.000Z"},{"id":"01db8150-b268-5bfd-8676-396e213c1875","topic":"Obtain the Controls team''s motion command contract","note":"AG-07 needs their message types, limits and fault codes. Tracked under External Dependencies.","track_id":"AG","task_id":null,"status":"open","created_at":"2026-10-25T12:00:00.000Z"}]'::jsonb) on conflict (id) do nothing;
insert into tasks select * from jsonb_populate_recordset(null::tasks, '[{"id":"20c6ab88-05ca-5add-b926-411b30386c9c","key":"AG-01","title":"Autonomy Mission State Machine","track_id":"AG","subtrack_id":"0b7fff48-6f3f-5746-8a0e-1ffcf49c85e2","priority":"critical","difficulty":"intermediate","estimate_hours":40,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":"f80bd1eb-a9ba-592b-8876-1072c9c18403","milestone_id":"d6c24028-a269-560d-a818-d2e1bd987d11","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["state-machine","mission","sprint-01"],"spec":{"problem":"A Lunabotics run is a sequence — initialize, localize, pick a goal, drive to the excavation zone, have the rover dig, drive to the berm, have it deposit, repeat — that must also handle faults, cancellation and recovery. Ad-hoc scripts become unmaintainable, and it becomes unclear which software decided what.","goal":"A ROS 2 mission orchestrator that decides which action is required next — Initialize, Localize, Select Goal, Navigate to Excavation, Request Excavation, Confirm Excavation Completion, Navigate to Deposition, Request Deposition, Confirm Deposition Completion, Recovery and Safe Stop — with an explicit, unit-tested transition table, run end-to-end against mock excavation/deposition servers in simulation.","why":{"need":"This is the decision layer that makes the rover autonomous rather than remote-controlled.","contribution":"Calls NV-03 for goals, NV-02 for navigation, AG-02/AG-03 to request excavation and deposition, and reacts to SF-04 localization health and AG-07 Controls status.","failureImpact":"Unhandled transitions leave the rover waiting forever, re-requesting excavation in the wrong place, or driving with stale goals.","consumers":["AG-08 end-to-end mission demo","AG-05 replay tests","AG-06 operator visualization","AG-10 recovery state machine"]},"background":"A finite-state machine has states, events and a transition table. Each state has enter/execute/exit actions; exit actions must cancel any outstanding action goals. Keeping the table as data (not nested ifs) makes it reviewable and exhaustively testable. Behavior trees are the main alternative (see AG-10 and the Faconti talk) — this task deliberately starts with an FSM because the mission is a short, mostly linear cycle.\n\n**Boundary:** \"Request Excavation\" sends an AG-02 action goal and waits for the result Controls reports. The state machine never publishes motor, actuator or wheel commands, and Safe Stop means *requesting* a stop through the AG-07 contract — Controls performs it.","prerequisites":[{"concept":"Finite-state machines","why":"Core design pattern.","resourceIds":["884a4786-fd54-5ef7-8b11-9e8784da5ec1","f3a54f40-9976-5a0c-932d-fe743f493b4b"]},{"concept":"ROS 2 action clients","why":"Navigation, excavation and deposition are long-running, cancellable actions.","resourceIds":["d52f49f7-6681-5630-ab76-69ee37ada9ca"]},{"concept":"Nav2 NavigateToPose","why":"How to send and cancel navigation goals.","resourceIds":["a90c1792-89cb-532d-a2b3-d146f8d8141b","d0216f41-247c-5226-9a7a-f988f204e884"]},{"concept":"Behavior trees (for comparison)","why":"Know the alternative and why we start with an FSM.","resourceIds":["2d84255f-edba-5a71-ad3c-56bed1d99bdd","4f7a858c-e5fe-5281-9da7-077ae4d5228f"]}],"readFirst":["Purdue state_manager.py (≈100 lines) — the engine.","Purdue main_states.py (≈300 lines) — the transition table.","AG-07 draft contract (what Safe Stop and motion-enabled mean)."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_behavior/lunabot_behavior/state_manager.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_behavior/lunabot_behavior/state_manager.py","isFolder":false,"summary":"Generic `StateManager` node parameterized by a states Enum, initial state, events type and event message type: subscribes to events/autonomy/position, runs `periodic`, and can `stop_everything` / `stop_current_state`.","inspect":["`StateManager.__init__(states, initial_state, events, event_type)`","`process_event`","`periodic`","`stop_everything`","`stop_current_state`","`autonomy_cb`"],"relevance":"A reusable engine separating state definitions from execution — the pattern we want.","questions":["How does periodic() decide to transition?","What happens to the current state''s outputs on transition?","How is autonomy enable/disable handled, and who would own that signal on our rover?"],"adaptation":"Keep the engine/definition separation; replace direct output zeroing with cancelling action goals and a safe-stop request to the AG-07 interface.","limitations":["Couples to Purdue''s message types and LED feedback.","stop_everything commands outputs directly — on our rover that belongs to Controls."],"verifiedOn":"2026-10-25"},{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_behavior/lunabot_behavior/main_states.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_behavior/lunabot_behavior/main_states.py","isFolder":false,"summary":"`MainStates` Enum: each state pairs a State object (Plunge, Raise, Deposit, Stall, Handshake, Drive, SetupMap, …) with LED colors, organized into init, first-cycle and repeating sections; `get_transition(state, event)` defines the table.","inspect":["`class MainStates(Enum)` — STOP, INIT_*, FIRST_CYCLE_*, STARTING_* entries","`get_transition(state, event: Events)`","`*_STALL` states paired with each operation"],"relevance":"A complete competition mission expressed as a transition table, including failure handling.","questions":["Which states are autonomy decisions, and which are actuator sequences we would delegate to Controls?","How does every operation route stalls?","What does the Handshake state coordinate (Purdue runs two robots)?"],"adaptation":"Keep the cycle structure but collapse actuator-level states (Plunge, Raise, Stall) into Request/Confirm states around one AG-02/AG-03 action each.","limitations":["Two-robot coordination states don''t apply to us.","Actuator sequences live in the mission layer — the opposite of our boundary.","A trailing comma on one Enum value makes it a tuple — a subtle bug class to avoid."],"verifiedOn":"2026-10-25"}],"analyze":["Draw Purdue''s state diagram from get_transition and color each state autonomy-decision vs actuator-sequence.","List every event, its source node, and whether it can arrive in any state.","Identify which states are safe to interrupt and what must be cancelled when they are."],"design":"Package `lunabot_mission`: `mission_fsm.py` (pure transition table + guards, no ROS imports), `mission_node.py` (ROS wrapper owning action clients for NavigateToPose, Excavate (AG-02) and Deposit (AG-03), a client for NV-03''s goal service, and subscriptions to /localization/health and /controls/status). States: INITIALIZE → LOCALIZE → SELECT_GOAL → NAV_TO_EXCAVATION → REQUEST_EXCAVATION → CONFIRM_EXCAVATION → NAV_TO_DEPOSITION → REQUEST_DEPOSITION → CONFIRM_DEPOSITION → SELECT_GOAL (cycle) … plus RECOVERY, SAFE_STOP, DONE. Universal transitions: LOC_LOST or CONTROLS_FAULT → SAFE_STOP; CANCEL → SAFE_STOP then IDLE. Publishes /mission/state with the last transition reason.","guidance":{"packageStructure":"lunabot_mission/\n  lunabot_mission/mission_fsm.py      # pure, unit-tested\n  lunabot_mission/mission_node.py\n  lunabot_mission/mocks.py            # mock Excavate/Deposit servers for sim\n  config/mission.yaml\n  test/test_mission_fsm.py\n  docs/state_diagram.md","files":["mission_fsm.py","mission_node.py","mocks.py","config/mission.yaml","test/test_mission_fsm.py"],"inputs":[{"name":"/localization/health","type":"diagnostic_msgs/msg/DiagnosticStatus","note":"proposed; may become a custom msg"},{"name":"/controls/status","type":"lunabot_interfaces/msg/ControlsStatus","note":"motion enabled, limits, faults — AG-07 (proposed)"},{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"},{"name":"navigate_to_pose","type":"nav2_msgs/action/NavigateToPose","note":"action client"},{"name":"excavate","type":"lunabot_interfaces/action/Excavate (AG-02)","note":"action client"},{"name":"deposit","type":"lunabot_interfaces/action/Deposit (AG-03)","note":"action client"}],"outputs":[{"name":"/mission/state","type":"std_msgs/msg/String","note":"proposed; custom msg in AG-04"},{"name":"/autonomy/safe_stop_request","type":"std_msgs/msg/Bool","note":"autonomy asks Controls to stop — AG-07 (proposed)"},{"name":"/mission/events","type":"std_msgs/msg/String","note":"transition log (proposed)"}],"parameters":[{"name":"max_cycles","default":"0 (unlimited)","description":"Stop after N cycles."},{"name":"state_timeouts_s","default":"{NAV: 120, REQUEST: 60, CONFIRM: 10}","description":"Internal bounds per state."},{"name":"localize_min_confidence","default":"from SF-04","description":"Gate leaving LOCALIZE."}],"snippets":[{"title":"Table-driven transitions","label":"illustrative","language":"python","code":"TRANSITIONS = {\n    (S.LOCALIZE, E.LOC_OK): S.SELECT_GOAL,\n    (S.SELECT_GOAL, E.GOAL_READY): S.NAV_TO_EXCAVATION,\n    (S.NAV_TO_EXCAVATION, E.ARRIVED): S.REQUEST_EXCAVATION,\n    (S.REQUEST_EXCAVATION, E.ACCEPTED): S.CONFIRM_EXCAVATION,\n    (S.CONFIRM_EXCAVATION, E.OP_SUCCESS): S.NAV_TO_DEPOSITION,\n    (S.CONFIRM_EXCAVATION, E.OP_FAILED): S.RECOVERY,\n}\nUNIVERSAL = {E.LOC_LOST: S.SAFE_STOP, E.CONTROLS_FAULT: S.SAFE_STOP, E.CANCEL: S.SAFE_STOP}\n\ndef next_state(state, event):\n    return UNIVERSAL.get(event) or TRANSITIONS.get((state, event), state)"},{"title":"Exhaustive transition test","label":"illustrative","language":"python","code":"@pytest.mark.parametrize(''state'', list(S))\ndef test_every_state_handles_safety_events(state):\n    assert next_state(state, E.LOC_LOST) is S.SAFE_STOP\n    assert next_state(state, E.CONTROLS_FAULT) is S.SAFE_STOP"},{"title":"Watch the mission","label":"verified","language":"bash","code":"ros2 topic echo /mission/state"}],"expectedBehavior":"Against mock servers in simulation the rover completes repeated cycles; LOST localization or a Controls fault from any state leads to SAFE_STOP with all goals cancelled and a safe-stop request published; RESUME continues from SELECT_GOAL.","pitfalls":["Publishing velocity or actuator commands from the state machine (boundary violation).","Forgetting to cancel outstanding action goals on exit.","Blocking calls inside callbacks freezing the executor (use async action clients).","Unreachable or dead-end states — test the table exhaustively."]},"testPlan":["Exhaustive unit test of the transition table and guards.","Simulation: ≥ 2 full cycles against mock servers.","Inject LOC_LOST, a Controls fault and CANCEL in every state.","Mock server failure and timeout cases for excavation and deposition."],"measure":[{"metric":"Successful cycles","definition":"Completed excavate→deposit cycles per simulated run."},{"metric":"Safe-stop decision latency","definition":"Fault event → safe-stop request published and goals cancelled (ms)."}],"document":["State diagram with every transition and its source event.","What the mission layer decides vs. what Controls executes."],"integrate":"AG-08 runs the full mission; AG-06 shows /mission/state; AG-02/AG-03 and the AG-07 contract are its only links to Controls."},"legacy_keys":["MS-01"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"c4795d19-bd20-5bdd-9bfd-253e4fc310ab","key":"AG-02","title":"Excavation Action Interface","track_id":"AG","subtrack_id":"b7e6ac48-c8c5-53f5-9767-258abf175bf5","priority":"high","difficulty":"intermediate","estimate_hours":28,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"84ebc8e4-7a5d-5543-ba35-2e0398f7b8f6","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["action-interface","controls-boundary"],"spec":{"problem":"Mission logic needs to ask the rover to dig and know how it went, but the digging itself — actuator positions, motor power, stall handling — belongs to Controls (and the mechanism to Mechanical). Without a clear contract, autonomy code ends up commanding actuators, or Controls has nothing stable to implement against.","goal":"The autonomy-facing ROS 2 action contract for excavation (Excavate.action), an autonomy-side client wrapper that checks whether excavation is allowed, sends the request, monitors reported execution state, handles success/failure, cancellation and timeout, and informs mission logic — plus a simulated action server that stands in for Controls until their real implementation exists.","why":{"need":"Scoring depends on excavated material, and the dig must be triggered autonomously at the right place and time.","contribution":"The single doorway AG-01 uses for excavation; the contract Controls implements on their side.","failureImpact":"Ambiguous results leave mission logic guessing; actuator details leaking into autonomy create cross-team coupling and safety ambiguity.","consumers":["AG-01 mission state machine","Controls team (implements the server)","AG-08 end-to-end demo","AG-11 excavation request strategies"]},"background":"A ROS 2 action has a goal, periodic feedback and one terminal result (succeeded / aborted / canceled). The client must always handle all three, plus server unavailability and timeouts. The **goal** should express *what* autonomy wants (e.g. a target zone id, a time budget, a maximum material estimate), never *how* actuators move — GOFIRST''s AutoDig goal (tilt position, chain power) is a useful counter-example of actuator detail leaking into the request.","prerequisites":[{"concept":"ROS 2 actions (client side)","why":"Goal/feedback/result lifecycle and cancellation.","resourceIds":["d52f49f7-6681-5630-ab76-69ee37ada9ca"]},{"concept":"Custom interfaces","why":"Defining Excavate.action in lunabot_interfaces.","resourceIds":["dd415d40-ef95-5397-8526-90d11b3f1e0a"]},{"concept":"The AG-07 contract","why":"Motion-enabled status and faults gate excavation requests.","resourceIds":["54343c49-dce4-5edc-9575-351ff3794278"]}],"readFirst":["COD Excavation.action (3 fields) and auto_excavation_server.cpp `execute`.","GOFIRST AutoDig.action — note what we should *not* put in our goal.","AG-07 draft contract."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_msgs/action/Excavation.action","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_msgs/action/Excavation.action","isFolder":false,"summary":"COD''s excavation action: an empty goal, a result with `bool success` and `string message`, and feedback `string feedback_message`.","inspect":["Goal: (empty)","Result: `success`, `message`","Feedback: `feedback_message`"],"relevance":"A minimal, hardware-agnostic contract that kept autonomy free of actuator detail.","questions":["What can mission logic NOT learn from this result (e.g. amount excavated, reason codes)?","Is free-text feedback enough for automated recovery decisions?"],"adaptation":"Start this simple, then add structured fields: a reason code enum, a phase enum for feedback, and an optional material estimate supplied by Controls.","limitations":["Free-text message only — hard to act on programmatically.","No goal parameters at all (no zone or time budget)."],"verifiedOn":"2026-10-25"},{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_nav/src/auto_excavation_server.cpp","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_nav/src/auto_excavation_server.cpp","isFolder":false,"summary":"COD''s `AutoExcavationServer` implementing that action: phases `lower_bucket`, `drive_forward`, `lift_bucket` orchestrated in `execute`, with encoder feedback and motor commands on /motor_commands.","inspect":["`execute(goal_handle)` — `abort` / `succeed` paths","`is_canceling()` checks inside each phase","`encoder_position_callback`"],"relevance":"Shows what the *server* side does — useful so our client handles its possible outcomes. On our rover this side is Controls'' to build.","questions":["Which outcomes can execute() produce, and under what conditions?","How quickly does it respond to cancel?","Which parts of this file would Controls own vs. which behavior should our mock imitate?"],"adaptation":"Our mock server imitates the timing and outcomes (succeed, abort with reason, cancel) without any motor logic.","limitations":["Mixes actuator control with the action server — exactly the code we do not write.","Publishes MotorCommands directly."],"verifiedOn":"2026-10-25"},{"repo":"GOFIRST-Robotics/Lunabotics","path":"src/rovr_interfaces/action/AutoDig.action","url":"https://github.com/GOFIRST-Robotics/Lunabotics/blob/main/src/rovr_interfaces/action/AutoDig.action","isFolder":false,"summary":"GOFIRST''s dig action: goal fields `tilt_digging_start_position` and `digger_chain_power`; empty result and feedback.","inspect":["Goal: `tilt_digging_start_position`, `digger_chain_power`","Result: (empty)","Feedback: (empty)"],"relevance":"A counter-example: the request carries actuator parameters and the result carries no outcome.","questions":["Why does putting chain power in the goal couple autonomy to the mechanism?","How would mission logic know whether the dig succeeded?"],"adaptation":"Keep actuator parameters inside Controls'' configuration; our goal expresses intent and limits only.","limitations":["No result fields — success can only be inferred from the action status."],"verifiedOn":"2026-10-25"}],"analyze":["Compare the three contracts: what does each let autonomy know and control?","List every terminal outcome our client must handle and the mission reaction to each.","Write down which fields Controls must supply that only they can measure (e.g. material estimate, stall)."],"design":"Interface `lunabot_interfaces/action/Excavate.action` — Goal: `uint8 zone_id`, `float32 time_budget_s`. Feedback: `uint8 phase` (PREPARING, EXCAVATING, RETRACTING), `float32 progress` (0–1, Controls'' estimate), `string detail`. Result: `bool success`, `uint8 reason` (OK, NOT_ALLOWED, TIMEOUT, STALL, CANCELED, FAULT), `float32 material_estimate_kg` (NaN when unknown), `string message`. Autonomy side: `ExcavationClient` (pre-checks: AG-07 motion-enabled, rover inside the excavation zone from NV-03; sends goal; enforces an outer timeout; maps results to mission events). `MockExcavationServer` for simulation with configurable outcomes and durations. The real server is Controls''.","guidance":{"packageStructure":"lunabot_interfaces/action/Excavate.action\nlunabot_mission/\n  lunabot_mission/excavation_client.py\n  lunabot_mission/mocks/excavation_server.py\n  config/excavation_interface.yaml\n  test/test_excavation_client.py\ndocs/interfaces/excavation.md   # shared with Controls","files":["Excavate.action","excavation_client.py","mocks/excavation_server.py","docs/interfaces/excavation.md"],"inputs":[{"name":"/controls/status","type":"lunabot_interfaces/msg/ControlsStatus","note":"motion enabled, limits, faults — AG-07 (proposed)"},{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"},{"name":"excavate","type":"lunabot_interfaces/action/Excavate","note":"server: Controls (mock in sim)"}],"outputs":[{"name":"/mission/events","type":"std_msgs/msg/String","note":"EXC_SUCCESS / EXC_FAILED(reason)"}],"parameters":[{"name":"client_timeout_s","default":"time_budget_s + 10","description":"Outer bound on waiting for a result."},{"name":"mock_outcome","default":"success","description":"success | stall | fault | slow (simulation only)."},{"name":"require_in_zone","default":"true","description":"Refuse to request outside the NV-03 excavation zone."}],"snippets":[{"title":"Proposed action definition","label":"illustrative","language":"text","code":"# Excavate.action — autonomy intent only; actuator parameters stay with Controls\nuint8 zone_id\nfloat32 time_budget_s\n---\nbool success\nuint8 reason        # 0 OK, 1 NOT_ALLOWED, 2 TIMEOUT, 3 STALL, 4 CANCELED, 5 FAULT\nfloat32 material_estimate_kg\nstring message\n---\nuint8 phase         # 0 PREPARING, 1 EXCAVATING, 2 RETRACTING\nfloat32 progress\nstring detail"},{"title":"Send a goal to the mock","label":"illustrative","language":"bash","code":"ros2 action send_goal /excavate lunabot_interfaces/action/Excavate \"{zone_id: 1, time_budget_s: 30.0}\" --feedback"},{"title":"Client outcome handling","label":"illustrative","language":"python","code":"result = await goal_handle.get_result_async()\nif goal_handle.status == GoalStatus.STATUS_SUCCEEDED and result.result.success:\n    emit(E.OP_SUCCESS)\nelse:\n    emit(E.OP_FAILED, reason=result.result.reason)"}],"expectedBehavior":"Mission logic gets exactly one outcome event per request; cancellation and timeouts are reported with reasons; requests outside the excavation zone or with motion disabled are refused before any goal is sent.","pitfalls":["Adding actuator positions or motor power to the goal.","Treating a missing server as success.","Not handling the canceled terminal state.","Letting the client wait forever when Controls stops responding."]},"testPlan":["Unit tests with the mock: success, stall, fault, slow (timeout), cancel.","Server-unavailable test.","Refusal tests (motion disabled, outside zone).","Full mission in simulation exercising excavation twice."],"measure":[{"metric":"Outcome coverage","definition":"Fraction of result/reason combinations exercised by tests (target: all)."},{"metric":"Cancel latency (mock)","definition":"Cancel request → canceled result (ms)."}],"document":["The agreed action contract with field meanings and units.","Which side owns which behavior."],"integrate":"AG-01 uses the client; Controls implements the real server against docs/interfaces/excavation.md; AG-08 exercises it in the full mission."},"legacy_keys":["MS-02"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"7bafdba8-75f3-5a8d-ac0a-9882a055c76e","key":"AG-03","title":"Deposition Action Interface","track_id":"AG","subtrack_id":"b7e6ac48-c8c5-53f5-9767-258abf175bf5","priority":"high","difficulty":"intermediate","estimate_hours":24,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"84ebc8e4-7a5d-5543-ba35-2e0398f7b8f6","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["action-interface","controls-boundary"],"spec":{"problem":"After excavating, the rover must reach the berm, be positioned so material lands in the target, and then dump. Positioning is an autonomy problem (navigation and alignment); dumping is Controls''. The handoff needs a precise contract and a validated pre-dump pose.","goal":"An autonomy-side deposition workflow: navigate to a staging pose (NV-03/NV-02), align and validate pose against a tolerance, send the high-level Deposit action request, handle feedback, success/failure, cancellation and timeout, and report to mission logic — with a mock deposition server for simulation.","why":{"need":"Material only counts once it is deposited in the right place.","contribution":"The DEPOSIT request/confirm steps of AG-01 and the contract Controls implements.","failureImpact":"Dumping while misaligned spills material outside the target or drives the rover into the berm.","consumers":["AG-01 mission state machine","Controls team (implements the server)","AG-08 end-to-end demo"]},"background":"Alignment is computed from the berm zone geometry: target heading = atan2 of the vector from the rover to the zone centroid (plus π if the mechanism dumps backwards). Validation compares the estimated pose to the staging pose with position and heading tolerances, using SF-04 confidence to refuse dumping on a poor estimate. The dump request itself carries intent only.","prerequisites":[{"concept":"Action clients","why":"Request lifecycle.","resourceIds":["d52f49f7-6681-5630-ab76-69ee37ada9ca"]},{"concept":"Angles and wrap-around","why":"Heading error math.","resourceIds":["493e250b-6519-5d3e-9fe3-e3d641738a71"]},{"concept":"Zones (NV-03)","why":"Berm geometry in the map frame.","resourceIds":["a9d3d523-0225-5ccc-865c-0984777af6c1"]}],"readFirst":["COD Depositing.action and auto_depositing_server.cpp.","Purdue align_to_berm.py (alignment math).","GOFIRST AutoOffload.action (counter-example)."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_msgs/action/Depositing.action","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_msgs/action/Depositing.action","isFolder":false,"summary":"COD''s deposit action: empty goal; result `bool success`, `string message`; feedback `string feedback_message`.","inspect":["Goal: (empty)","Result: `success`, `message`","Feedback: `feedback_message`"],"relevance":"Minimal hardware-agnostic handoff for dumping.","questions":["How does mission logic know *why* a deposit failed?","What pre-conditions does the server assume?"],"adaptation":"Mirror AG-02''s structured result (reason codes) for consistency.","limitations":["Free-text results only."],"verifiedOn":"2026-10-25"},{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_nav/src/auto_depositing_server.cpp","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_nav/src/auto_depositing_server.cpp","isFolder":false,"summary":"`AutoDepositingServer`: `drive_forward`, `lift_bucket`, `lower_bucket` phases orchestrated in `execute`, with encoder position feedback.","inspect":["`execute(goal_handle)`","`drive_forward(goal_handle)` — note it moves the rover inside the server","`encoder_position_callback`"],"relevance":"Shows that COD''s server assumes the rover is already aligned — alignment is our job before the request.","questions":["What alignment is assumed before execute starts?","Which motions here are positioning (autonomy) vs. dumping (Controls)?"],"adaptation":"We do all positioning before the request; the server (Controls) performs only the dump sequence.","limitations":["Server drives the rover, blurring the boundary."],"verifiedOn":"2026-10-25"},{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_behavior/lunabot_behavior/states/align_to_berm.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_behavior/lunabot_behavior/states/align_to_berm.py","isFolder":false,"summary":"`AlignToBerm` (extends AlignToAngle): computes the angle from the robot to the berm zone centroid with `arctan2`, optionally adds π for backwards approach, and delegates to the angle controller.","inspect":["`AlignToBerm.__init__(backwards=False)`","`AlignToBerm.periodic` — centroid via `zone_to_poly(berm_zone).centroid`, `arctan2`, modulo 2π"],"relevance":"Concise autonomy-level alignment math from zone geometry.","questions":["Why might backing into the berm be preferable?","What happens if robot_pose is None?"],"adaptation":"Use the same target-heading computation; execute the rotation with Nav2 (spin or a final-orientation goal) rather than a custom angle controller.","limitations":["Heading only; no lateral offset correction."],"verifiedOn":"2026-10-25"}],"analyze":["Split COD''s deposit sequence into positioning vs. dumping.","Define position and heading tolerances with the Mechanical/Controls teams'' mechanism constraints.","List the outcomes the client must handle."],"design":"Interface `Deposit.action` (Goal: `uint8 berm_id`, `float32 time_budget_s`; Result: `bool success`, `uint8 reason`, `string message`; Feedback: `uint8 phase`, `float32 progress`). Autonomy workflow `DepositionCoordinator`: NAVIGATE (NavigateToPose to the NV-03 staging pose with final orientation) → VALIDATE (pose error within tolerance and SF-04 status OK; re-align up to N times) → REQUEST (Deposit goal) → CONFIRM (map result to mission event). Mock server for simulation.","guidance":{"packageStructure":"lunabot_interfaces/action/Deposit.action\nlunabot_mission/\n  lunabot_mission/deposition_coordinator.py\n  lunabot_mission/mocks/deposition_server.py\n  config/deposition.yaml\n  test/test_alignment.py\ndocs/interfaces/deposition.md","files":["Deposit.action","deposition_coordinator.py","mocks/deposition_server.py","test/test_alignment.py"],"inputs":[{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"},{"name":"/localization/health","type":"diagnostic_msgs/msg/DiagnosticStatus","note":"proposed; may become a custom msg"},{"name":"/controls/status","type":"lunabot_interfaces/msg/ControlsStatus","note":"motion enabled, limits, faults — AG-07 (proposed)"},{"name":"navigate_to_pose","type":"nav2_msgs/action/NavigateToPose","note":"action client"}],"outputs":[{"name":"deposit","type":"lunabot_interfaces/action/Deposit","note":"client; server is Controls (mock in sim)"},{"name":"/mission/events","type":"std_msgs/msg/String"}],"parameters":[{"name":"align_tolerance_deg","default":"agreed with Mechanical","description":"Heading tolerance."},{"name":"position_tolerance_m","default":"agreed with Mechanical","description":"Staging-pose tolerance."},{"name":"max_realign_attempts","default":"3","description":"Before failing."},{"name":"approach_backwards","default":"mechanism dependent","description":"From Mechanical."}],"snippets":[{"title":"Target heading and error","label":"illustrative","language":"python","code":"target = math.atan2(cy - y, cx - x) + (math.pi if backwards else 0.0)\nerr = (target - yaw + math.pi) % (2 * math.pi) - math.pi\naligned = abs(err) <= math.radians(cfg.align_tolerance_deg)"},{"title":"Request a deposit from the mock","label":"illustrative","language":"bash","code":"ros2 action send_goal /deposit lunabot_interfaces/action/Deposit \"{berm_id: 0, time_budget_s: 20.0}\" --feedback"}],"expectedBehavior":"The rover reaches the staging pose, validates alignment, requests the deposit and reports the outcome; no request is sent while misaligned or with degraded localization.","pitfalls":["Angle wrap-around bugs.","Requesting the dump before validation.","Embedding dump actuator parameters in the goal.","Ignoring SF-04 confidence when validating pose."]},"testPlan":["Unit tests for heading math and wrap-around.","Simulation from ≥ 3 start poses.","Degraded-localization refusal test.","Mock failure, timeout and cancel."],"measure":[{"metric":"Alignment error at request","definition":"Heading (deg) and position (m) error when the deposit is requested."},{"metric":"Deposition outcome","definition":"Success/failure/abort counts across runs."}],"document":["Interface contract.","Tolerance rationale with Mechanical''s input."],"integrate":"AG-01 calls the coordinator after NAV_TO_DEPOSITION; Controls implements the server; AG-08 demonstrates it."},"legacy_keys":["MS-03"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"5d60e9c6-9e3a-5f3c-8935-3ce633fb9855","key":"AG-04","title":"ROS 2 Autonomy Architecture","track_id":"AG","subtrack_id":"18ed355a-9e25-5f20-b424-b2143c158152","priority":"critical","difficulty":"intermediate","estimate_hours":36,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":"f80bd1eb-a9ba-592b-8876-1072c9c18403","milestone_id":"d6c24028-a269-560d-a818-d2e1bd987d11","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["architecture","sprint-01","foundation"],"spec":{"problem":"Seven tracks will write nodes in parallel. Without agreed package structure, topic contracts, TF conventions, shared messages and launch conventions, integration becomes a rewrite.","goal":"Workspace architecture documentation and a functional bringup for the autonomy stack: package organization, topic and message contracts, TF conventions, QoS policies, shared configuration and launch orchestration, plus the simulation/real-robot interface abstraction (autonomy talks to Controls only through the AG-07 contract).","why":{"need":"Integration is the hardest part of a robotics project; contracts make it tractable.","contribution":"Every track builds against these interfaces.","failureImpact":"Mismatched topics/frames/QoS cause silent failures that waste days during integration.","consumers":["All four subteams","AG-05","AG-06","AG-07","AG-13"]},"background":"A ROS 2 workspace is a set of packages built by colcon. Interfaces (msg/srv/action) live in a dedicated package so others depend on them without pulling code. Launch files compose nodes and parameters; `use_sim_time` makes nodes follow /clock.","prerequisites":[{"concept":"ROS 2 packages and colcon","why":"Workspace layout.","resourceIds":["97c4c73b-1a4b-53bc-a551-0959ed18a3b7","3fcc2d34-a99e-59ef-a696-1c08ee193afa"]},{"concept":"Launch files and parameters","why":"Bringup composition.","resourceIds":["f25dec27-c4cf-5762-a7b9-9643f1443b1f","cf0fa0ac-5e1b-53f8-bd3c-fd51e1995dc7"]},{"concept":"Custom interfaces","why":"Shared messages.","resourceIds":["dd415d40-ef95-5397-8526-90d11b3f1e0a"]},{"concept":"QoS","why":"Sensor vs reliable policies.","resourceIds":["30983abb-fbb0-5e0a-a475-5c9d5b7820c4"]}],"readFirst":["Utah ONBOARDING.md (workspace and workflow sections).","Purdue lunabot_bringup/launch folder.","COD launch_manager.launch.py."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_bringup/launch","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/tree/master/lunabot_bringup/launch","isFolder":true,"summary":"Bringup launch files: bag.launch, computer.launch, example.launch, mini_record(.small).launch, record(.small).launch, robot.launch, sim.launch, test.launch.","inspect":["sim.launch vs robot.launch differences","record.launch topic lists","XML launch format with `$(eval …)` arguments"],"relevance":"Shows separation of sim, robot, operator computer and recording bringups.","questions":["What is shared between sim.launch and robot.launch?","How are namespaces used for two robots?","Why XML launch rather than Python here?"],"adaptation":"Mirror the sim/robot/operator split with Python launch files and shared includes.","limitations":["Multi-robot namespacing not needed for us."],"verifiedOn":"2026-10-25"},{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_bringup/launch/launch_manager.launch.py","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_bringup/launch/launch_manager.launch.py","isFolder":false,"summary":"Launches a single `launch_manager_node.py` from lunabot_bringup — a node that manages launching other components at runtime.","inspect":["`generate_launch_description()`","Node(package=''lunabot_bringup'', executable=''launch_manager_node.py'')"],"relevance":"An approach to runtime-managed bringup (e.g. start/stop subsystems from a GUI).","questions":["What would a launch manager node need to do safely?","Is runtime launching preferable to lifecycle nodes for us?"],"adaptation":"Consider lifecycle-managed nodes instead of a custom launch manager.","limitations":["The manager logic lives in a different file not reviewed here."],"verifiedOn":"2026-10-25"}],"analyze":["List every package the stack needs and its owner track.","Draft the topic table (name, type, QoS, producer, consumers).","Draft the TF tree and owners."],"design":"Workspace `lunabot_ws/src`: `lunabot_interfaces` (autonomy msgs/srvs/actions), `lunabot_bringup` (sim.launch.py, robot.launch.py, operator.launch.py), `lunabot_description` (simulation-facing), per-subteam packages, and `lunabot_controls_interface` holding the AG-07 adapter plus a mock Controls node so every launch file runs without hardware. robot.launch.py swaps the mock for Controls'' real nodes; no autonomy package imports Controls code. Conventions: snake_case topics under subsystem namespaces (/perception/…, /localization/…, /mission/…, /safety/…); SensorDataQoS for high-rate sensors, reliable + transient-local for state/health; all tunables as parameters in config/*.yaml; `use_sim_time` passed from bringup.","guidance":{"packageStructure":"lunabot_ws/src/\n  lunabot_interfaces/          (autonomy msg, srv, action)\n  lunabot_bringup/             (sim / robot / operator launch, config)\n  lunabot_description/         (simulation-facing URDF)\n  lunabot_localization/  🕸️    lunabot_perception/  📸\n  lunabot_planning/      🗺️    lunabot_navigation/  🗺️\n  lunabot_mission/       🧠    lunabot_controls_interface/  🧠 (AG-07 adapter + mock)\n  lunabot_sim/           🕹️\n  docs/architecture.md","files":["docs/architecture.md","docs/topics.md","lunabot_bringup/launch/sim.launch.py","lunabot_interfaces/package.xml"],"inputs":[],"outputs":[{"name":"docs/topics.md","type":"file","note":"topic contract table"}],"parameters":[{"name":"use_sim_time","default":"true in sim.launch.py","description":"Propagated to all nodes."},{"name":"namespace","default":"''''","description":"Single robot."}],"snippets":[{"title":"Create the interfaces package","label":"verified","language":"bash","code":"ros2 pkg create --build-type ament_cmake lunabot_interfaces"},{"title":"Build and source","label":"verified","language":"bash","code":"colcon build --symlink-install\nsource install/setup.bash"},{"title":"Inspect the running graph","label":"verified","language":"bash","code":"ros2 node list\nros2 topic list -t\nrqt_graph"}],"expectedBehavior":"`ros2 launch lunabot_bringup sim.launch.py` starts arena, rover, TF and stub nodes from a clean clone with documented commands.","pitfalls":["Interfaces scattered across packages.","Hard-coded topic names in nodes (use remapping/parameters).","QoS mismatch between sensor publishers and subscribers."]},"testPlan":["Clean-clone build in CI (ties to AG-13).","Launch sim bringup headless and check expected nodes/topics exist.","TF tree check via view_frames."],"measure":[{"metric":"Startup time","definition":"Launch to all expected nodes active (s)."},{"metric":"Contract coverage","definition":"Topics in use that are documented / total."}],"document":["Architecture overview.","Topic and TF contract tables.","Bringup instructions."],"integrate":"Every subteam builds against these contracts; AG-05 and AG-13 build on the bringup; AG-07 owns the Controls boundary."},"legacy_keys":["IT-01"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"7a4f5bbb-c23d-5204-b744-a7bc2d348122","key":"AG-05","title":"ROS Bag Replay and Testing","track_id":"AG","subtrack_id":"526a2766-2d19-54ce-9366-f8a68d898801","priority":"high","difficulty":"intermediate","estimate_hours":32,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"84ebc8e4-7a5d-5543-ba35-2e0398f7b8f6","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["rosbag","regression","testing"],"spec":{"problem":"Changes in one subsystem silently break another. Without recorded scenarios and repeatable comparisons, regressions are discovered on competition day.","goal":"Replay infrastructure and recorded test scenarios: standard topic recording, reusable replay scripts, benchmark scenarios, comparison metrics, automated selected runs, stored results and documented reproducibility.","why":{"need":"Validate integrated performance repeatedly as code changes.","contribution":"Gives every track objective before/after comparisons.","failureImpact":"Unknown regressions; claims of improvement without evidence.","consumers":["All four subteams","AG-08","AG-13","SIM-07"]},"background":"rosbag2 records topics to a storage backend (sqlite3/mcap). Replaying with `--clock` drives sim time so nodes behave as live. Comparison scripts extract metrics (e.g. ATE) from output bags.","prerequisites":[{"concept":"ros2 bag","why":"Record/play.","resourceIds":["73298a07-2ed6-5224-99d5-c009df68ca5e","6f784f87-cfa7-5ead-a50c-c10257e214bd"]},{"concept":"Simulation time","why":"Replays drive /clock.","resourceIds":["f25dec27-c4cf-5762-a7b9-9643f1443b1f"]},{"concept":"Metrics","why":"ATE/RPE and others.","resourceIds":["788a889e-c6bf-5d2f-af0e-d66aee74b4be"]}],"readFirst":["Purdue bag.launch.","Utah ONBOARDING.md testing sections."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_bringup/launch/bag.launch","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_bringup/launch/bag.launch","isFolder":false,"summary":"XML launch (≈160 lines) for bag playback: robot_num/namespace and sim arguments, then nodes needed to process replayed data.","inspect":["`<arg name=\"robot_num\">` / `<let name=\"ns\">`","`<arg name=\"sim\">` and `real` evaluation","nodes started alongside playback"],"relevance":"Shows which processing nodes a team re-runs against recorded data.","questions":["Which nodes are re-run vs replayed from the bag?","How is sim time handled?"],"adaptation":"Create replay launch files per subsystem under test that disable the original producer and run the node under test.","limitations":["ROS 2 XML launch with team-specific nodes."],"verifiedOn":"2026-10-25"},{"repo":"utahrobotics/utah-lunabotics-2027","path":"ONBOARDING.md","url":"https://github.com/utahrobotics/utah-lunabotics-2027/blob/main/ONBOARDING.md","isFolder":false,"summary":"Utah''s onboarding guide (≈900 lines): prerequisites, setup, workflow and first-PR guidance in one document.","inspect":["Table of contents","Testing / workflow sections"],"relevance":"Model for how to document reproducible environment and test procedures.","questions":["How do they ensure everyone''s environment matches?","What testing expectations do they set for PRs?"],"adaptation":"Adopt a similar single-source-of-truth testing guide for our replay infrastructure.","limitations":["Platform choices differ (they use more than ROS)."],"verifiedOn":"2026-10-25"}],"analyze":["Define the standard topic set per scenario.","List which nodes each regression test re-runs.","Decide storage format (mcap vs sqlite3)."],"design":"Package `lunabot_testing`: `record_standard.sh` (topic set), `replay.launch.py` (bag + node-under-test, use_sim_time), `metrics/` (ATE, planning time, costmap rate), `scenarios.yaml` (bag → expected metrics bounds), `run_regression.py` producing JSON/CSV results; results stored under `results/<date>/` and summarized in the app''s Experiments page.","guidance":{"packageStructure":"lunabot_testing/\n  scripts/record_standard.sh\n  launch/replay.launch.py\n  lunabot_testing/metrics/*.py\n  scenarios.yaml\n  scripts/run_regression.py","files":["record_standard.sh","replay.launch.py","scenarios.yaml","run_regression.py"],"inputs":[{"name":"/clock","type":"rosgraph_msgs/msg/Clock","note":"simulation time"}],"outputs":[{"name":"results/*.json","type":"file"}],"parameters":[{"name":"rate","default":"1.0","description":"Playback rate."},{"name":"storage","default":"mcap","description":"Bag format (decide)."}],"snippets":[{"title":"Record standard topics","label":"verified","language":"bash","code":"ros2 bag record -o scenario_flat_01 /tf /tf_static /clock /imu/data /wheel/odometry /lidar/points /ground_truth/odom"},{"title":"Replay with clock","label":"verified","language":"bash","code":"ros2 bag play scenario_flat_01 --clock"},{"title":"Run regression","label":"illustrative","language":"bash","code":"python3 scripts/run_regression.py --scenarios scenarios.yaml --out results/"}],"expectedBehavior":"Same bag + same code → same metrics within tolerance; a deliberate regression is flagged.","pitfalls":["Replaying /tf from the bag while the node under test also publishes it.","Forgetting --clock / use_sim_time.","Non-deterministic node behavior (unseeded randomness)."]},"testPlan":["Replay determinism: run twice, compare metrics.","Inject a known regression; confirm detection.","Run the suite in CI on a small scenario."],"measure":[{"metric":"Determinism spread","definition":"Metric difference between identical runs."},{"metric":"Suite runtime","definition":"Total minutes to run selected scenarios."}],"document":["How to record, replay and add scenarios.","Result format."],"integrate":"AG-13 CI runs a subset; SIM-07 automates scenario runs; AG-08 extends to end-to-end missions."},"legacy_keys":["IT-02"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"5d9ab24b-f42c-511a-a0f2-b14783e48c9d","key":"AG-06","title":"Autonomy Operator Visualization","track_id":"AG","subtrack_id":"1241dac3-b66d-5cb2-80a7-9a87c9c1bea6","priority":"medium","difficulty":"intermediate","estimate_hours":32,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"84ebc8e4-7a5d-5543-ba35-2e0398f7b8f6","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["dashboard","telemetry","teleop"],"spec":{"problem":"During testing and competition, the team needs to see what the autonomy stack believes — pose, localization confidence, perception status, planned route, mission state, faults and subsystem health — without digging through terminals.","goal":"An autonomy telemetry view (simulated or live ROS data) showing estimated position, localization confidence, perception status, planned route, mission state, faults and subsystem health. Operator actions are limited to autonomy mission requests (start / pause / cancel). Teleoperation, motor controls and the physical emergency stop belong to Controls and are not implemented here.","why":{"need":"Humans must be able to understand what autonomy is doing and why.","contribution":"Visibility into SF-04 health, PM-01 costmaps, NV-02 routes, AG-01 mission state and AG-07 Controls-interface status.","failureImpact":"Problems go unnoticed until the rover misbehaves; debugging integration takes far longer.","consumers":["Autonomy members during simulation testing","Leads during integration runs"]},"background":"Options: Foxglove (configurable panels, fastest path), rosbridge + a custom web UI, a Qt/Python GUI (COD), or a game-engine UI (Utah Godot). COD''s GUI mixes autonomy telemetry with teleop and E-stop publishers — our view keeps only the autonomy half; Controls owns teleop and the physical E-stop.","prerequisites":[{"concept":"ROS topics and QoS","why":"Subscribing remotely.","resourceIds":["30983abb-fbb0-5e0a-a475-5c9d5b7820c4"]},{"concept":"Visualization tools","why":"Foxglove or custom.","resourceIds":["bea6e129-1b71-593b-8559-62ca7fa8d3a9","7af45569-72a9-5c63-ac04-bd780b7a3922"]},{"concept":"Mission and health topics","why":"What AG-01 and SF-04 publish.","resourceIds":["54c635df-9476-5698-8046-9492aeb99971"]}],"readFirst":["COD lunabot_gui/src/ros_interface.py (which topics a team GUI consumes).","Utah godot/new-lunabase folder structure.","Foxglove docs overview."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_gui/src/ros_interface.py","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_gui/src/ros_interface.py","isFolder":false,"summary":"`RobotInterface` class isolating all ROS communication for COD''s GUI: subscriptions to /odometry/filtered, /control_state, /joint_states, a camera stream, bandwidth and /rosout; action clients for auto_excavation_action and auto_depositing_action; and publishers for /emergency_stop, /mode_switch and /cmd_vel.","inspect":["`class RobotInterface` and `__init__(mode_param)`","`_create_subscriptions()` — the telemetry topic list","`ActionClient(..., Excavation, ''auto_excavation_action'')` / `Depositing`","publishers `/emergency_stop`, `/mode_switch`, `/cmd_vel`"],"relevance":"Shows exactly which telemetry a Lunabotics team found useful, and a clean ROS-layer/UI-layer split.","questions":["Which subscriptions are autonomy telemetry, and which belong to Controls (power, joint states, E-stop)?","Which publishers would violate our boundary (cmd_vel, emergency_stop)?","How does it keep ROS callbacks from blocking the UI?"],"adaptation":"Copy the layering and the autonomy subscriptions; drop the teleop, E-stop and mode-switch publishers — those are Controls-owned. Mission requests go to AG-01, not directly to the excavation action.","limitations":["Mixes autonomy and Controls concerns in one class.","Desktop GUI; not accessible from other devices."],"verifiedOn":"2026-10-25"},{"repo":"utahrobotics/utah-lunabotics-2027","path":"godot/new-lunabase","url":"https://github.com/utahrobotics/utah-lunabotics-2027/tree/main/godot/new-lunabase","isFolder":true,"summary":"Godot-based operator base: Assets, GUI, MainController, StateManager, Systems folders, a GDExtension, and project files.","inspect":["GUI/","StateManager/","lunabase.gdextension"],"relevance":"An ambitious, game-engine operator UI — useful to see what a full-featured base station includes.","questions":["How does it receive robot data (it''s not ROS-native)?","What views does it prioritize?"],"adaptation":"Borrow information-architecture ideas; implementation likely too heavy for us.","limitations":["Requires Godot and a custom extension."],"verifiedOn":"2026-10-25"}],"analyze":["Inventory what each reference displays.","Pick the minimum viable panel set for testing.","Choose technology with justification."],"design":"Phase 1: Foxglove layout (`dashboards/autonomy.json`) with a 3D panel (TF, traversability costmap, planned path, detections), localization-confidence and mission-state panels, a fault list and AG-07 Controls-interface status. Phase 2 (optional): a small rosbridge web UI whose only actions are AG-01 mission start / pause / cancel, with confirmation. No velocity, actuator or E-stop publishers.","guidance":{"packageStructure":"lunabot_operator/\n  dashboards/autonomy.json\n  launch/operator.launch.py\n  web/ (optional, mission requests only)","files":["dashboards/autonomy.json","launch/operator.launch.py"],"inputs":[{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"},{"name":"/localization/health","type":"diagnostic_msgs/msg/DiagnosticStatus","note":"proposed; may become a custom msg"},{"name":"/mission/state","type":"std_msgs/msg/String","note":"proposed; custom msg in AG-04"},{"name":"/controls/status","type":"lunabot_interfaces/msg/ControlsStatus","note":"motion enabled, limits, faults — AG-07 (proposed)"},{"name":"/perception/traversability","type":"nav_msgs/msg/OccupancyGrid","note":"proposed"},{"name":"/plan","type":"nav_msgs/msg/Path"},{"name":"/perception/obstacles","type":"TBD (PM-08)"}],"outputs":[{"name":"/mission/request","type":"lunabot_interfaces/srv/MissionRequest (proposed)","note":"start / pause / cancel only"}],"parameters":[{"name":"bridge","default":"foxglove_bridge | rosbridge","description":"Connection method."}],"snippets":[{"title":"Start a bridge for Foxglove","label":"adapt","language":"bash","code":"ros2 launch foxglove_bridge foxglove_bridge_launch.xml","note":"Package name/launch file per foxglove_bridge docs; verify for your distro."}],"expectedBehavior":"Pose, confidence, route, mission state and faults update live during simulated runs; mission requests are confirmed and logged; nothing in the view can drive motors.","pitfalls":["Adding teleop or E-stop controls (Controls-owned).","High-bandwidth topics (raw clouds) over Wi-Fi.","Showing ground truth next to estimates without labeling which is which."]},"testPlan":["Run against an AG-05 bag replay.","Run against live simulation through a full AG-08 mission.","Verify the view publishes nothing except mission requests (ros2 node info).","Bandwidth measurement over Wi-Fi."],"measure":[{"metric":"Telemetry latency","definition":"Topic stamp → displayed (ms, estimated)."},{"metric":"Bandwidth","definition":"kB/s used by the dashboard."}],"document":["Panel guide.","What the view deliberately does not do (teleop, E-stop) and who owns those."],"integrate":"Used during AG-05 and AG-08 runs and integration testing with Controls."},"legacy_keys":["IT-03"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"e5839c37-c400-51c0-b926-2e44b2993145","key":"AG-07","title":"Autonomy-to-Controls Interface Specification","track_id":"AG","subtrack_id":"b7e6ac48-c8c5-53f5-9767-258abf175bf5","priority":"critical","difficulty":"intermediate","estimate_hours":28,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":"f80bd1eb-a9ba-592b-8876-1072c9c18403","milestone_id":"d6c24028-a269-560d-a818-d2e1bd987d11","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["controls-boundary","interface","sprint-01"],"spec":{"problem":"Autonomy decides how the rover should move; Controls makes the motors do it. Today there is no written contract between the two: no agreed topic, message type, units, rate limits, timestamps, staleness rules, fault reporting or safe-stop semantics. Without one, autonomy code drifts into motor control, or integration day reveals incompatible assumptions.","goal":"A versioned interface specification (docs + lunabot_interfaces messages) covering the motion command interface, velocity limits supplied by Controls, command timestamps and validity windows, feedback messages, fault reporting, motion enable/disable status and safe-stop requests — plus a mock Controls node that implements the Controls side for simulation and tests, and contract tests both teams can run.","why":{"need":"Every autonomy output that moves the rover crosses this boundary.","contribution":"Lets NV-02, AG-01, AG-02 and AG-03 develop against a stable contract now, and lets Controls implement their side independently.","failureImpact":"Unit mismatches, stale commands executed late, faults that autonomy never hears about, and unclear ownership of safety behavior.","consumers":["NV-02 Nav2 (publishes motion requests)","AG-01 mission logic (safe stop, status)","AG-02 / AG-03 action interfaces","SF-01 (wheel odometry feedback)","Controls team (implements the real side)"]},"background":"**Ownership:** Controls retains motor execution, firmware, physical safety (including the hardware E-stop) and control-loop tuning. Autonomy owns the *requests* and how it reacts to feedback.\n\nGood command contracts carry a timestamp and a validity window so the receiver can reject stale commands, and they report back the limits actually enforced. ros2_control and twist_mux illustrate the same separation: high-level software publishes velocity intents; a lower layer decides what the hardware can do. COD''s `MotorCommands` (duty cycles per motor) is the kind of message autonomy should **not** produce — it is a Controls-internal concern.","prerequisites":[{"concept":"ROS 2 messages and QoS","why":"Designing message types and choosing reliable vs best-effort.","resourceIds":["dd415d40-ef95-5397-8526-90d11b3f1e0a","30983abb-fbb0-5e0a-a475-5c9d5b7820c4"]},{"concept":"Hardware abstraction layers","why":"Why high-level software never commands motors directly.","resourceIds":["54343c49-dce4-5edc-9575-351ff3794278","c7bfc3a9-2e35-554f-a3d1-28f612361a6f"]},{"concept":"Command multiplexing and timeouts","why":"How priority and staleness are usually handled.","resourceIds":["5cbab412-d11d-5c62-9a84-6221ca149c71"]}],"readFirst":["COD MotorCommands.msg and ControlState.msg — what Controls-level messages look like.","COD controller_teleop.cpp emergency_stop_callback — how a team handled E-stop state in software.","twist_mux README (timeouts, priorities)."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_msgs/msg/MotorCommands.msg","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_msgs/msg/MotorCommands.msg","isFolder":false,"summary":"Duty-cycle commands for every motor: `left_wheel`, `right_wheel`, `left_actuator`, `right_actuator`, `vibration`, each in [-1.0, 1.0].","inspect":["Fields `left_wheel`, `right_wheel`, `left_actuator`, `right_actuator`, `vibration`","Comment: values in range [-1.0, 1.0]"],"relevance":"Shows the Controls-internal level our contract must stay above.","questions":["Why would autonomy publishing duty cycles couple us to motor drivers and gearing?","Which of these fields have any autonomy meaning?"],"adaptation":"Our contract carries body velocity intents (m/s, rad/s) with timestamps; Controls maps them to motors.","limitations":["No timestamp or validity — a stale message is indistinguishable from a fresh one."],"verifiedOn":"2026-10-25"},{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_msgs/msg/ControlState.msg","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_msgs/msg/ControlState.msg","isFolder":false,"summary":"Control state: `mode` (MODE_MANUAL / MODE_AUTO), booleans `hardware_enabled`, `pointlio_enabled`, `mapping_enabled`, `nav2_enabled`, `is_excavating`, `is_depositing`, `is_navigating`, `emergency_stop`, and a `status_message`.","inspect":["Constants `MODE_MANUAL`, `MODE_AUTO`","`hardware_enabled`, `emergency_stop`","`is_excavating`, `is_depositing`, `is_navigating`"],"relevance":"A good starting point for the feedback autonomy needs from Controls (mode, enable, E-stop, activity).","questions":["Which fields would autonomy react to, and how?","What is missing: enforced limits, fault codes, timestamps?"],"adaptation":"Our ControlsStatus adds a header, enforced velocity limits, a fault code list and an explicit motion_enabled flag.","limitations":["Mixes autonomy flags (pointlio_enabled, nav2_enabled) into a Controls message.","No header/timestamp."],"verifiedOn":"2026-10-25"},{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_teleop/src/controller_teleop.cpp","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_teleop/src/controller_teleop.cpp","isFolder":false,"summary":"`ControllerTeleop` node: joystick and velocity inputs, GUI emergency-stop and manual/autonomous mode switch, publishing MotorCommands and state.","inspect":["`emergency_stop_callback` — sets robot_disabled_ and publishes zero MotorCommands; re-enables when the message is false","`mode_switch_callback`","`velocity_callback`","`publish_state`"],"relevance":"Shows how one team handled E-stop and autonomy/manual handoff in software — behavior our contract must make explicit.","questions":["Which behaviors here would Controls own on our rover?","The E-stop re-enables as soon as the signal is false — what must our contract say about recovery after a safe stop?","Is there a staleness timeout on velocity input?"],"adaptation":"We do not build this node. We specify what autonomy observes (motion_enabled, estop_active, mode) and that recovery after a stop requires Controls to re-enable motion.","limitations":["Teleop, E-stop and arbitration in one node.","E-stop not latched in software."],"verifiedOn":"2026-10-25"}],"analyze":["List every piece of information autonomy needs from Controls, and every request autonomy sends, with units and rates.","Decide what happens when autonomy stops publishing (Controls should stop after a timeout — write the expected value).","Write the safe-stop request semantics: who may request, who decides, how motion is re-enabled."],"design":"`lunabot_interfaces` messages (version 0.1): **MotionRequest** on `/autonomy/cmd_vel` — geometry_msgs/TwistStamped (header.stamp required, frame base_link) plus a `valid_for_s` field in a wrapper or a parameter; Controls rejects requests older than the validity window. **ControlsStatus** on `/controls/status` (10 Hz, reliable, transient-local): header, `mode` (MANUAL/AUTO), `motion_enabled`, `estop_active`, `max_linear_mps`, `max_angular_radps`, `faults[]` (code + message), `last_command_age_s`. **SafeStopRequest**: std_srvs/Trigger service `/controls/request_safe_stop` (or a latched topic) — a request; Controls decides and reports via status. Wheel odometry feedback: `/wheel/odometry` (nav_msgs/Odometry) published by Controls on hardware, by the simulated drivetrain in sim. `lunabot_controls_interface` package: `autonomy_adapter.py` (clamps requests to advertised limits, stamps them, stops publishing when autonomy is paused) and `mock_controls.py` (implements the Controls side for simulation: honors validity windows, advertises limits, can inject faults).","guidance":{"packageStructure":"lunabot_interfaces/msg/ControlsStatus.msg\nlunabot_interfaces/msg/ControlsFault.msg\nlunabot_controls_interface/\n  lunabot_controls_interface/autonomy_adapter.py\n  lunabot_controls_interface/mock_controls.py\n  test/test_contract.py            # runnable by both teams\ndocs/interfaces/controls.md        # the specification (versioned)","files":["docs/interfaces/controls.md","ControlsStatus.msg","autonomy_adapter.py","mock_controls.py","test/test_contract.py"],"inputs":[{"name":"/controls/status","type":"lunabot_interfaces/msg/ControlsStatus","note":"motion enabled, limits, faults — AG-07 (proposed)"},{"name":"/wheel/odometry","type":"nav_msgs/msg/Odometry","note":"proposed"},{"name":"/navigation/cmd_vel","type":"geometry_msgs/msg/Twist","note":"Nav2 controller output (remapped)"}],"outputs":[{"name":"/autonomy/cmd_vel","type":"geometry_msgs/msg/TwistStamped","note":"autonomy motion request — AG-07 contract (proposed)"},{"name":"/autonomy/safe_stop_request","type":"std_msgs/msg/Bool","note":"autonomy asks Controls to stop — AG-07 (proposed)"}],"parameters":[{"name":"command_validity_s","default":"0.25 (proposed, agree with Controls)","description":"Controls rejects requests older than this."},{"name":"publish_rate_hz","default":"20","description":"Autonomy request rate."},{"name":"use_mock_controls","default":"true in sim","description":"Launch-time switch from AG-04."}],"snippets":[{"title":"Proposed ControlsStatus.msg","label":"illustrative","language":"text","code":"std_msgs/Header header\nuint8 MODE_MANUAL=0\nuint8 MODE_AUTO=1\nuint8 mode\nbool motion_enabled\nbool estop_active          # reported by Controls; autonomy never sets it\nfloat32 max_linear_mps\nfloat32 max_angular_radps\nfloat32 last_command_age_s\nControlsFault[] faults"},{"title":"Adapter: clamp and stamp","label":"illustrative","language":"python","code":"def on_nav_cmd(self, twist):\n    if not self.status or not self.status.motion_enabled:\n        return  # do not request motion Controls has disabled\n    out = TwistStamped()\n    out.header.stamp = self.get_clock().now().to_msg()\n    out.header.frame_id = ''base_link''\n    out.twist.linear.x = clamp(twist.linear.x, -self.status.max_linear_mps, self.status.max_linear_mps)\n    out.twist.angular.z = clamp(twist.angular.z, -self.status.max_angular_radps, self.status.max_angular_radps)\n    self.pub.publish(out)"},{"title":"Watch both sides of the boundary","label":"verified","language":"bash","code":"ros2 topic hz /autonomy/cmd_vel\nros2 topic echo /controls/status"}],"expectedBehavior":"In simulation, Nav2''s output flows through the adapter to the mock Controls node; stale requests are ignored; disabling motion in the mock stops motion requests; faults appear in AG-06 and trigger AG-01 SAFE_STOP.","pitfalls":["Specifying motor-level fields (duty cycles, currents) — Controls-internal.","Commands without timestamps.","Autonomy ''clearing'' an E-stop — only Controls re-enables motion.","Undocumented units or frames."]},"testPlan":["Contract tests: stale command ignored, limits clamped, motion-disabled respected, fault surfaced.","Navigation goal in simulation through adapter + mock.","Fault injection: mock fault → AG-01 SAFE_STOP within a bounded time."],"measure":[{"metric":"Command latency to mock","definition":"Nav2 output stamp → mock receipt (ms)."},{"metric":"Stale-command rejection","definition":"Fraction of artificially delayed commands correctly ignored (target: all)."}],"document":["The versioned interface specification with an ownership table.","Open questions for Controls and their resolution."],"integrate":"NV-02, AG-01, AG-02 and AG-03 depend on this contract; Controls implements their side from docs/interfaces/controls.md; AG-08 runs the full mission through the mock."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"495d9c18-8a65-5cdc-ac45-b603c7e63687","key":"AG-08","title":"End-to-End Autonomous Mission Demo","track_id":"AG","subtrack_id":"1241dac3-b66d-5cb2-80a7-9a87c9c1bea6","priority":"critical","difficulty":"advanced","estimate_hours":48,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"84ebc8e4-7a5d-5543-ba35-2e0398f7b8f6","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["integration","milestone","simulation"],"spec":{"problem":"Subsystems that pass their own tests can still fail together: frames disagree, topics are misnamed, timing breaks, faults are never handled. Until the whole stack runs a mission in simulation, nobody knows whether the autonomy system works.","goal":"A repeatable end-to-end virtual mission: from a clean bringup in simulation, using estimated localization (no ground truth in the loop), perception costmaps, Nav2 navigation and mission logic with mock excavation/deposition and mock Controls, the rover completes at least one full excavate→deposit cycle without human input — with metrics, a recording, and demonstrated failure handling. Its passing run is the evidence for the Mission Readiness end-to-end indicator.","why":{"need":"This is the clearest signal that the autonomy team''s software actually works as a system.","contribution":"Integrates SIM-01/02, SF-01, PM-01, NV-02/03, AG-01/02/03/07 and validates AG-04 contracts.","failureImpact":"Integration surprises appear at competition instead of in simulation.","consumers":["Team leadership","Mission Readiness dashboard","AG-05 regression suite","SIM-07 automated regression"]},"background":"End-to-end tests start from bringup, run unattended, and record everything needed to reproduce and diagnose them. Pass criteria are written **before** running. The ADR ''What constitutes a valid mission demonstration?'' defines the bar used by the readiness indicator.","prerequisites":[{"concept":"Bringup and contracts (AG-04)","why":"How the stack is launched.","resourceIds":["f25dec27-c4cf-5762-a7b9-9643f1443b1f"]},{"concept":"Bag recording and replay (AG-05)","why":"Recording evidence.","resourceIds":["73298a07-2ed6-5224-99d5-c009df68ca5e"]},{"concept":"Mission logic (AG-01)","why":"What the run exercises.","resourceIds":["884a4786-fd54-5ef7-8b11-9e8784da5ec1"]}],"readFirst":["ADR: What constitutes a valid mission demonstration?","AG-04 topic contract table.","AG-07 interface specification."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_bringup/launch","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/tree/master/lunabot_bringup/launch","isFolder":true,"summary":"Bringup launch files: bag.launch, computer.launch, example.launch, mini_record(.small).launch, record(.small).launch, robot.launch, sim.launch, test.launch.","inspect":["sim.launch — full simulated stack","record.launch — standard recorded topics","test.launch — minimal planner harness"],"relevance":"A team''s split between full-stack sim bringup and recording — the two halves of an end-to-end run.","questions":["What does sim.launch start that robot.launch does not?","Which topics does record.launch capture?"],"adaptation":"Mirror sim bringup + recording; add a mission runner that starts AG-01 and collects metrics.","limitations":["Two-robot namespacing not needed for us."],"verifiedOn":"2026-10-25"}],"analyze":["List every subsystem the run depends on and the contract it must satisfy.","Define pass/fail criteria and the metrics recorded.","List the faults the demo will inject and the expected mission reaction."],"design":"`lunabot_testing/e2e/`: `run_mission.py` launches sim bringup (SIM-01 scenario + seed), the autonomy stack with mock Controls (AG-07) and mock excavation/deposition (AG-02/03), starts AG-01, records a bag (AG-05 topic set), and evaluates pass criteria from the bag: cycles completed, collisions, time, localization error against simulator ground truth (evaluation only), recoveries. Fault variants: localization dropout (SF-04), blocked path (NV-06), mock excavation failure.","guidance":{"packageStructure":"lunabot_testing/e2e/\n  run_mission.py\n  criteria.yaml          # written before running\n  evaluate.py\n  scenarios/*.yaml\n  results/<date>/","files":["run_mission.py","criteria.yaml","evaluate.py"],"inputs":[{"name":"/mission/state","type":"std_msgs/msg/String","note":"proposed; custom msg in AG-04"},{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"},{"name":"/ground_truth/odom","type":"nav_msgs/msg/Odometry","note":"evaluation only"},{"name":"/localization/health","type":"diagnostic_msgs/msg/DiagnosticStatus","note":"proposed; may become a custom msg"}],"outputs":[{"name":"results/<date>/report.json","type":"file"},{"name":"results/<date>/mission.mcap","type":"rosbag2"}],"parameters":[{"name":"scenario","default":"rocks","description":"SIM-01 scenario."},{"name":"seed","default":"0","description":"Deterministic placement."},{"name":"fault","default":"none | loc_dropout | blocked_path | exc_failure","description":"Variant."}],"snippets":[{"title":"Run the demo","label":"illustrative","language":"bash","code":"ros2 launch lunabot_bringup sim.launch.py scenario:=rocks seed:=42 use_mock_controls:=true\npython3 lunabot_testing/e2e/run_mission.py --criteria criteria.yaml --out results/"}],"expectedBehavior":"The rover completes the cycle(s) unattended; fault variants end in documented recoveries or SAFE_STOP, never in undefined behavior.","pitfalls":["Using ground truth in the control loop (it is for evaluation only).","Changing pass criteria after seeing results.","Undocumented manual steps between launch and mission start."]},"testPlan":["Nominal run × 3 seeds.","Each fault variant once per seed.","Clean-clone reproduction by a second member."],"measure":[{"metric":"Mission completion rate","definition":"Runs meeting the pre-defined criteria / runs."},{"metric":"Successful cycles","definition":"Excavate→deposit cycles per run."},{"metric":"Mission runtime","definition":"Start to DONE/SAFE_STOP (min)."},{"metric":"Recovery count","definition":"Recoveries per run."}],"document":["Criteria, results and a reproduction guide.","Known failure modes and owners."],"integrate":"Evidence for the readiness indicator; regression baseline for AG-05 and SIM-07."},"legacy_keys":["IT-06"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"ad5ad035-2683-5642-9a09-3ec5b942a38e","key":"SF-01","title":"Rover Pose Estimation and Sensor Fusion","track_id":"SF","subtrack_id":"e39eb280-b0b3-5e67-bee3-562e2f2c614d","priority":"critical","difficulty":"intermediate","estimate_hours":40,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":"f80bd1eb-a9ba-592b-8876-1072c9c18403","milestone_id":"d6c24028-a269-560d-a818-d2e1bd987d11","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["localization","robot_localization","sprint-01"],"spec":{"problem":"Wheel odometry alone drifts quickly on loose regolith because wheels slip, and the IMU alone drifts because integrated noise grows without bound. Every downstream subsystem needs a single, continuous, confidence-annotated pose estimate.","goal":"A ROS 2 localization setup (robot_localization EKF/UKF) that fuses simulated wheel odometry and IMU, publishes /odometry/filtered with meaningful covariance and the odom → base_link transform, adds LiDAR-inertial odometry (SF-03) as an input when it is available, and a reproducible benchmark that visualizes trajectories and quantifies drift against ground truth.","why":{"need":"The rover must know where it is to drive to the excavation zone, back to the berm, and avoid obstacles — all without a human.","contribution":"Provides the odom-frame pose and velocity that Nav2, the costmap, mission zone checks and the operator dashboard consume.","failureImpact":"Pose drift makes the planner steer into hazards, the mission logic think it reached a zone it hasn''t, and the costmap smear obstacles across the map.","consumers":["NV-02 Nav2 integration","PM-01 traversability costmap","NV-03 zone selection","SF-04 localization health","AG-06 operator dashboard"]},"background":"A Kalman filter alternates a *prediction* (propagate the state with a motion model and grow uncertainty) with a *correction* (blend in a measurement weighted by relative uncertainty). The EKF linearizes nonlinear models with Jacobians; the UKF propagates sigma points instead. robot_localization implements both as `ekf_node` / `ukf_node` with a 15-state model (pose, orientation, linear/angular velocity, linear acceleration). Each sensor input has a boolean config vector choosing which of those 15 variables it measures. REP-105 defines the frame semantics: the odom frame is continuous but drifts, map is globally consistent but may jump.","prerequisites":[{"concept":"ROS 2 publishers, subscribers and launch files","why":"You will wire sensor topics into a filter node and launch it.","resourceIds":["54c635df-9476-5698-8046-9492aeb99971","f25dec27-c4cf-5762-a7b9-9643f1443b1f"]},{"concept":"Coordinate frames (REP-105) and TF","why":"The filter''s odom/base_link/world_frame parameters must match the TF tree exactly.","resourceIds":["a9d3d523-0225-5ccc-865c-0984777af6c1","48d88130-ebb2-50e8-a73f-0c1df1ba777b"]},{"concept":"Kalman filter predict/correct and covariance","why":"Tuning process and measurement noise is the core of this task.","resourceIds":["932d1d63-c973-5c69-9d97-a272932a9392","28ba189d-b72b-5610-be2c-70d7db674321"]},{"concept":"robot_localization sensor configuration","why":"Each sensor''s 15-element config vector selects the fused variables.","resourceIds":["24908517-b857-5893-88e8-9bff94c9bcfb"]}],"readFirst":["REP-105 sections on odom and map frames.","robot_localization docs: ''Configuring robot_localization'' and the sensor config parameter pages.","COD ukf_params.yaml (below) end-to-end, comment by comment."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_config/params/robot_localization/ukf_params.yaml","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_config/params/robot_localization/ukf_params.yaml","isFolder":false,"summary":"COD''s robot_localization UKF configuration: 30 Hz, two_d_mode enabled, odom as world_frame, fusing a single odometry input (/lio_odom from LiDAR-inertial odometry) with x, y, yaw, vx, vy and yaw rate.","inspect":["`odom0: /lio_odom` and `odom0_config`","`two_d_mode: true`","`odom0_pose_rejection_threshold` / `odom0_twist_rejection_threshold`","`process_noise_covariance` and `initial_estimate_covariance` (15×15)"],"relevance":"A working, competition-tested parameter file. Shows how 2D mode and rejection thresholds are set for a Lunabotics rover.","questions":["Why is world_frame set to odom rather than map here?","Which of the 15 state variables does odom0 fuse, and why are z, roll and pitch disabled?","COD fuses only one odometry source in this file — what would you add for wheel odometry + IMU, and what would you set *_differential to?","What happens to the estimate when a measurement exceeds the rejection threshold?"],"adaptation":"Start from this structure but configure two inputs (odom0 = wheel odometry for velocities, imu0 = IMU for yaw rate / orientation). Keep two_d_mode. Re-derive covariances for our sensors rather than copying values.","limitations":["Tuned for COD''s sensors and LIO output, not raw wheel odometry.","Only one sensor input is fused in this file, so it does not demonstrate multi-sensor weighting."],"verifiedOn":"2026-10-25"},{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_bringup/launch/fastlio_launch.py","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_bringup/launch/fastlio_launch.py","isFolder":false,"summary":"Launch description that starts a Livox reorientation utility (lunabot_util/livox_reorient) and FAST-LIO (fast_lio/fastlio_mapping) — the source of the /lio_odom input above.","inspect":["`launch_setup(context, *args, **kwargs)`","`generate_launch_description()`","the `fast_lio` / `fastlio_mapping` Node action"],"relevance":"Shows how an upstream odometry producer is composed with the filter in a bringup.","questions":["Which parameters are passed to FAST-LIO and where do they come from?","How would you make the filter launch only after the odometry source is publishing?"],"adaptation":"Use the same OpaqueFunction pattern if our launch needs runtime argument evaluation.","limitations":["Depends on Livox hardware drivers we may not use."],"verifiedOn":"2026-10-25"},{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_slam/scripts/map_base_node.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_slam/scripts/map_base_node.py","isFolder":false,"summary":"Small rclpy node (class `MapBase`) that, on each odometry message, looks up the map → base_link transform via tf2 and republishes it as a PoseStamped on `position`.","inspect":["`MapBase.__init__` (namespaced frame names, Buffer/TransformListener)","`MapBase.__odom_callback` (lookup_transform + do_transform_pose_stamped)"],"relevance":"A minimal example of consuming the fused TF tree to give other nodes a simple map-frame pose.","questions":["Why does it look up the transform at `rclpy.time.Time()` (latest) instead of the odometry stamp?","What does it do if the transform is unavailable?"],"adaptation":"Useful pattern for a ''pose for mission logic'' adapter; prefer looking up at the message stamp with a timeout.","limitations":["Uses latest transform, which can mismatch the message timestamp.","Errors are logged every message without throttling."],"verifiedOn":"2026-10-25"}],"analyze":["Draw COD''s TF chain implied by the UKF parameters (map/odom/base_link) and identify which node publishes each edge.","List every input topic the filter subscribes to and the exact variables fused from each.","Explain how two_d_mode changes the state and why it''s appropriate (or not) for an arena with slopes.","Identify which covariance values most affect how much the filter trusts each input."],"design":"Create package `lunabot_localization` containing only configuration and launch (no custom filter code). The launch starts `robot_localization/ekf_node` with `config/ekf.yaml`, `use_sim_time` from an argument. Wheel odometry contributes vx and yaw rate (differential/velocity), the IMU contributes yaw rate and optionally yaw. The filter publishes odom → base_link; the wheel odometry source must NOT also publish that transform. A `scripts/compare_trajectories.py` tool exports TUM-format trajectories from a bag for evo.","guidance":{"packageStructure":"lunabot_localization/\n  config/ekf.yaml\n  config/ekf_wheel_only.yaml\n  launch/localization.launch.py\n  scripts/export_tum.py\n  test/test_covariance_valid.py\n  README.md","files":["config/ekf.yaml","config/ekf_wheel_only.yaml","launch/localization.launch.py","scripts/export_tum.py","README.md"],"inputs":[{"name":"/wheel/odometry","type":"nav_msgs/msg/Odometry","note":"proposed"},{"name":"/imu/data","type":"sensor_msgs/msg/Imu","note":"proposed"},{"name":"/clock","type":"rosgraph_msgs/msg/Clock","note":"simulation time"}],"outputs":[{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"},{"name":"/tf (odom → base_link)","type":"tf2_msgs/msg/TFMessage"}],"parameters":[{"name":"frequency","default":"30.0","description":"Filter output rate (Hz)."},{"name":"two_d_mode","default":"true","description":"Ignore z, roll, pitch; revisit if arena slopes matter."},{"name":"odom0_config","default":"vx, vyaw","description":"Fuse wheel velocities, not wheel pose."},{"name":"imu0_config","default":"vyaw (+ yaw if magnetometer-free orientation is trustworthy)","description":"IMU yaw rate is usually the most valuable signal."},{"name":"imu0_remove_gravitational_acceleration","default":"true","description":"Only if fusing linear acceleration."}],"snippets":[{"title":"Create the package","label":"verified","language":"bash","code":"ros2 pkg create --build-type ament_python lunabot_localization --dependencies rclpy nav_msgs sensor_msgs"},{"title":"Starting EKF configuration","label":"adapt","language":"yaml","code":"ekf_filter_node:\n  ros__parameters:\n    frequency: 30.0\n    two_d_mode: true\n    publish_tf: true\n    odom_frame: odom\n    base_link_frame: base_link\n    world_frame: odom\n    odom0: /wheel/odometry\n    #            x      y      z      roll   pitch  yaw\n    odom0_config: [false, false, false, false, false, false,\n    #            vx     vy     vz     vroll  vpitch vyaw\n                   true,  false, false, false, false, true,\n    #            ax     ay     az\n                   false, false, false]\n    imu0: /imu/data\n    imu0_config: [false, false, false, false, false, false,\n                  false, false, false, false, false, true,\n                  false, false, false]","note":"Covariances in the incoming messages matter as much as this file — make sure the wheel odometry and IMU publishers fill them."},{"title":"Check output rate and frames","label":"verified","language":"bash","code":"ros2 topic hz /odometry/filtered\nros2 run tf2_ros tf2_echo odom base_link"},{"title":"Compare against ground truth with evo","label":"adapt","language":"bash","code":"evo_ape tum groundtruth.tum fused.tum --align --plot\nevo_ape tum groundtruth.tum wheel_only.tum --align --plot","note":"Requires exporting both trajectories in TUM format first."}],"expectedBehavior":"With no slip, fused and wheel-only tracks are similar. When slip is injected, the fused heading stays close to ground truth because the IMU yaw rate does not slip, while wheel-only heading diverges.","pitfalls":["Two nodes publishing odom → base_link (e.g. diff-drive controller and EKF) — TF will flicker. Disable one.","Zero covariance in incoming messages makes the filter over-trust a sensor.","IMU frame not in TF, or IMU mounted rotated without a correct static transform.","Mixing wall-clock and sim time (forgetting use_sim_time)."]},"testPlan":["Static test: rover stationary for 60 s — fused pose drift and covariance growth are recorded.","Square path (4 × 2 m) and figure-eight in simulation with ground truth.","Same paths with 20% simulated slip on one wheel side.","Launch-from-clean-workspace test: `colcon build` + launch with only documented commands.","Automated check that every /odometry/filtered message has a positive-definite pose covariance diagonal."],"measure":[{"metric":"ATE (RMSE)","definition":"Absolute trajectory error after SE(2) alignment, from evo_ape.","target":"Fused ATE lower than wheel-only ATE in the slip scenario","rationale":"Internal goal: fusion must demonstrably help where wheels slip."},{"metric":"Final drift","definition":"Euclidean distance between final estimated and true position at end of run."},{"metric":"Update frequency","definition":"Measured publish rate of /odometry/filtered (ros2 topic hz)."},{"metric":"CPU utilization","definition":"Mean CPU % of the filter process during playback."}],"document":["Frame diagram and which node owns each transform.","Why each fused variable was chosen.","Benchmark table with commands to reproduce it."],"integrate":"Navigation (NV-02) consumes /odometry/filtered and odom → base_link; Perception (PM-01) needs the TF to place point clouds; SF-04 monitors this output''s covariance and rate."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"f05ffa4c-b505-5dda-a737-b97c3901fca2","key":"SF-02","title":"Sensor Extrinsic Calibration","track_id":"SF","subtrack_id":"bbf1e663-a8cb-5f04-88a8-7b8086aef885","priority":"high","difficulty":"intermediate","estimate_hours":28,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"da95fb4b-23c3-5194-a5d5-b29cf88ae336","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["calibration","tf"],"spec":{"problem":"Every sensor measures in its own frame. If the transform from base_link to the LiDAR, IMU or camera is wrong by a few degrees, obstacles appear in the wrong place and fused estimates disagree with each other.","goal":"A documented frame tree (base_link, lidar_link, imu_link, camera_link, radar_link as applicable), a calibration utility that estimates/validates sensor extrinsics, and ROS-compatible static transforms generated from its output, with tests.","why":{"need":"Perception and localization combine data from several sensors; they only agree if each sensor''s pose on the rover is known.","contribution":"Feeds static transforms to TF used by SF-01, SF-03, PM-01, PM-02 and PM-03.","failureImpact":"A rotated LiDAR makes flat ground look like a slope (false lethal cells) and makes LIO diverge; a wrong camera transform makes AprilTag pose estimates wrong.","consumers":["SF-01","SF-03","PM-01","PM-02","PM-03","SIM-02"]},"background":"A rigid transform is a rotation plus translation, written as a 4×4 homogeneous matrix T. Composition is matrix multiplication; inversion is R^T and −R^T t. Quaternions represent rotation compactly without gimbal lock (ROS uses x, y, z, w order). Hand-eye calibration solves AX = XB: if sensor A and sensor B each estimate their own motion, the fixed transform X between them can be recovered from paired relative motions.","prerequisites":[{"concept":"Homogeneous transformations","why":"Compose, invert and apply 4×4 transforms.","resourceIds":["493e250b-6519-5d3e-9fe3-e3d641738a71","b0f6e245-ddd5-52cc-a7cf-7b15535d06d8"]},{"concept":"Quaternion rotation","why":"ROS stores orientation as quaternions; conversions are a common bug source.","resourceIds":["b0f6e245-ddd5-52cc-a7cf-7b15535d06d8"]},{"concept":"Static transform publishing","why":"Calibration output is published as static TF.","resourceIds":["8f79d4a7-a5e6-5cd5-a745-b4b086754e8c"]},{"concept":"Coordinate conventions","why":"x-forward, y-left, z-up, SI units.","resourceIds":["724c3d71-073d-51fc-bce2-0f05570e1df6"]}],"readFirst":["REP-103 coordinate conventions.","tf2 static broadcaster tutorial.","Utah extrinsic_calibration.py top-to-bottom (≈430 lines)."],"references":[{"repo":"utahrobotics/utah-lunabotics-2027","path":"misc/calibration/extrinsic_calibration.py","url":"https://github.com/utahrobotics/utah-lunabotics-2027/blob/main/misc/calibration/extrinsic_calibration.py","isFolder":false,"summary":"Standalone Python calibration script: a `Pose` dataclass with matrix conversion/composition, a hand-eye solver, pose interpolation to align timestamps, and extraction of pose series from a recorded dataset.","inspect":["`class Pose` — `to_matrix`, `from_matrix`, `inverse`, `compose`, `relative_to`","`skew(v)`","`calibrate_hand_eye(poses_A, poses_B)`","`interpolate_pose` and `interpolate_poses_to_timestamps`","`extract_poses(dataset, entity_path)` and `main()`"],"relevance":"A complete, readable hand-eye extrinsic calibration pipeline written by a current Lunabotics team.","questions":["What two pose streams does it pair, and why must they be time-aligned before solving?","How does `calibrate_hand_eye` separate the rotation and translation solve?","What motion must the rover perform for the problem to be well-conditioned?","What input dataset format does `extract_poses` expect, and what would we need to provide instead?"],"adaptation":"Reuse the Pose math and the hand-eye approach, but read our ROS 2 bag topics and emit a YAML/launch snippet of static transforms.","limitations":["Reads Utah''s recording format (entity paths), not ROS bags.","Hand-eye needs rich rotational motion; straight-line driving is degenerate."],"verifiedOn":"2026-10-25"}],"analyze":["Write the equation the solver minimizes in your own words.","Identify where quaternion ↔ matrix conversion happens and which ordering (wxyz vs xyzw) is used.","List the assumptions about time synchronization between the two pose sources."],"design":"Package `lunabot_calibration` (ament_python) with a pure-Python `transforms.py` (no ROS imports, unit-testable), a `validate_tf.py` node that checks expected frames exist and are within tolerance of the measured CAD values, and a `hand_eye.py` CLI that reads two odometry topics from a bag and outputs `calibration/extrinsics.yaml`. A launch file publishes static transforms from that YAML.","guidance":{"packageStructure":"lunabot_calibration/\n  lunabot_calibration/transforms.py\n  lunabot_calibration/hand_eye.py\n  lunabot_calibration/validate_tf.py\n  config/extrinsics.yaml\n  launch/static_tf.launch.py\n  test/test_transforms.py\n  docs/frames.md","files":["transforms.py","hand_eye.py","validate_tf.py","config/extrinsics.yaml","launch/static_tf.launch.py","test/test_transforms.py"],"inputs":[{"name":"/tf","type":"tf2_msgs/msg/TFMessage"},{"name":"/tf_static","type":"tf2_msgs/msg/TFMessage"},{"name":"/lidar/odometry","type":"nav_msgs/msg/Odometry","note":"sensor-frame motion A (proposed)"},{"name":"/wheel/odometry","type":"nav_msgs/msg/Odometry","note":"proposed"}],"outputs":[{"name":"/tf_static","type":"tf2_msgs/msg/TFMessage"},{"name":"config/extrinsics.yaml","type":"file"}],"parameters":[{"name":"expected_frames","default":"[base_link, lidar_link, imu_link, camera_link]","description":"Frames validate_tf must find."},{"name":"tolerance_m / tolerance_deg","default":"0.02 / 2.0","description":"Allowed difference from CAD nominal (internal goal)."}],"snippets":[{"title":"Publish a static transform from the CLI","label":"verified","language":"bash","code":"ros2 run tf2_ros static_transform_publisher --x 0.30 --y 0.0 --z 0.45 --roll 0 --pitch 0 --yaw 0 --frame-id base_link --child-frame-id lidar_link","note":"Humble+ named-argument syntax."},{"title":"Inspect the TF tree","label":"verified","language":"bash","code":"ros2 run tf2_tools view_frames"},{"title":"Round-trip property test","label":"illustrative","language":"python","code":"def test_inverse_roundtrip():\n    T = make_transform(xyz=(0.3, 0.1, 0.4), rpy=(0.1, -0.2, 1.0))\n    np.testing.assert_allclose(T @ invert(T), np.eye(4), atol=1e-9)"}],"expectedBehavior":"view_frames shows a single tree rooted at map/odom with all sensor frames as children of base_link. validate_tf passes with CAD values and fails loudly when a transform is perturbed.","pitfalls":["Quaternion ordering (ROS: x, y, z, w; many libraries: w first).","Degrees vs radians in YAML.","Publishing a sensor frame twice (URDF and a separate static publisher).","Calibrating with too little rotation."]},"testPlan":["Unit tests for transform math (round-trip, composition associativity, known rotations).","Synthetic test: generate motion with a known X, add noise, verify recovery.","validate_tf against SIM-02 URDF frames.","Repeatability across three recordings."],"measure":[{"metric":"Recovery error (synthetic)","definition":"Translation (m) and rotation (deg) error between recovered and true X in synthetic data."},{"metric":"Repeatability","definition":"Std. dev. of estimated extrinsics across recordings."}],"document":["Frame diagram (base_link and all sensors).","Calibration procedure with motion requirements.","Example output YAML and how to apply it."],"integrate":"SIM-02 URDF uses the same frame names; SF-01/SF-03/PM tasks consume the transforms."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"e3919c33-0c0b-50fb-a063-8680deadc484","key":"SF-03","title":"LiDAR–IMU Odometry","track_id":"SF","subtrack_id":"8cf7e1df-7490-5c0e-be88-9e0d1e6aadc5","priority":"high","difficulty":"advanced","estimate_hours":48,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"da95fb4b-23c3-5194-a5d5-b29cf88ae336","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["lio","point-lio","benchmark"],"spec":{"problem":"Wheel odometry is unreliable on regolith and visual odometry struggles with low-texture lunar terrain and harsh lighting. LiDAR-inertial odometry uses geometry plus IMU and can remain accurate when wheels slip.","goal":"A runnable LiDAR-inertial odometry prototype (adapting Point-LIO or FAST-LIO) on simulated LiDAR + IMU, with a benchmark of drift and latency compared against wheel-only and SF-01 fused baselines.","why":{"need":"Accurate odometry under slip is what makes repeated excavation/deposition cycles possible without the pose drifting off.","contribution":"Provides a high-quality odometry input that SF-01''s filter can fuse (as COD does with /lio_odom).","failureImpact":"If LIO diverges silently it can be worse than no LIO — the filter will trust a wrong pose. Health monitoring (SF-04) must catch this.","consumers":["SF-01","SF-04","PM-01"]},"background":"LIO propagates the state at IMU rate between LiDAR scans and corrects with scan registration against a local map. Because a spinning LiDAR collects points over ~100 ms while moving, points must be *de-skewed* (motion compensated) using the IMU-propagated trajectory. FAST-LIO uses an iterated error-state Kalman filter; Point-LIO updates per point.","prerequisites":[{"concept":"Point clouds and PointCloud2","why":"Understand fields, timestamps per point and frames.","resourceIds":["03399223-0ba3-5288-8423-163bf1e33889"]},{"concept":"IMU propagation","why":"Integrating angular velocity and acceleration, gravity and bias.","resourceIds":["28ba189d-b72b-5610-be2c-70d7db674321"]},{"concept":"Kalman filter fundamentals","why":"LIO is a (error-state) Kalman filter.","resourceIds":["932d1d63-c973-5c69-9d97-a272932a9392"]},{"concept":"Motion compensation","why":"Why per-point timestamps matter.","resourceIds":["269a1cd5-4832-54b5-ab4e-d848408a2738"]}],"readFirst":["FAST-LIO paper sections on forward propagation and backward propagation.","point_lio README in the COD repo.","IMU_Processing.cpp in full (≈115 lines)."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"third_party_packages/point_lio","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/tree/master/third_party_packages/point_lio","isFolder":true,"summary":"COD''s vendored copy of Point-LIO: CMakeLists, config/, launch/, msg/, rviz_cfg/, src/ and README.","inspect":["config/ (sensor-specific YAML)","launch/","README.md"],"relevance":"A Lunabotics team already integrated Point-LIO into a ROS 2 workspace — the closest path to a working prototype.","questions":["Which config file matches the closest LiDAR to ours, and what extrinsic parameters does it require?","What topics does the launch file expect for LiDAR and IMU?","What modifications did COD make versus upstream hku-mars/Point-LIO?"],"adaptation":"Vendor or depend on Point-LIO the same way, creating a config for our simulated LiDAR (point timestamps, scan lines) and IMU.","limitations":["Sensor configs are hardware-specific.","Simulated LiDARs may lack per-point timestamps required for de-skewing."],"verifiedOn":"2026-10-25"},{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"third_party_packages/point_lio/src/IMU_Processing.cpp","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/third_party_packages/point_lio/src/IMU_Processing.cpp","isFolder":false,"summary":"IMU processing for Point-LIO: `ImuProcess` initialization, gravity/rotation initialization from the first IMU samples and per-measurement processing.","inspect":["`ImuProcess::Reset()`","`ImuProcess::Set_init(...)`","`ImuProcess::IMU_init(const MeasureGroup&, int&)`","`ImuProcess::Process(const MeasureGroup&, PointCloudXYZI::Ptr)`"],"relevance":"Shows how gravity direction and initial orientation are estimated — a frequent source of LIO divergence when the rover starts on a slope.","questions":["How many IMU samples does IMU_init average, and what does it assume about motion during that time?","What would happen if the rover moves during initialization?"],"adaptation":"Ensure our bringup holds the rover still for initialization; expose the init sample count as a parameter if needed.","limitations":["Assumes stationary start for gravity alignment."],"verifiedOn":"2026-10-25"}],"analyze":["Trace the data flow from LiDAR/IMU callbacks to the published odometry.","Identify the extrinsic LiDAR↔IMU parameters and how they relate to SF-02.","Determine what the simulated LiDAR must provide (per-point time, ring) for Point-LIO to work."],"design":"Package `lunabot_lio` wraps Point-LIO (or FAST-LIO) with our config and a launch that remaps to proposed topics (/lidar/points, /imu/data → /lio/odometry). A small `lio_monitor.py` publishes processing latency and a diverged flag consumed by SF-04.","guidance":{"packageStructure":"lunabot_lio/\n  config/sim_lidar.yaml\n  launch/lio.launch.py\n  scripts/lio_monitor.py\n  rviz/lio.rviz\n  README.md","files":["config/sim_lidar.yaml","launch/lio.launch.py","scripts/lio_monitor.py","README.md"],"inputs":[{"name":"/lidar/points","type":"sensor_msgs/msg/PointCloud2","note":"proposed"},{"name":"/imu/data","type":"sensor_msgs/msg/Imu","note":"proposed"},{"name":"/tf_static","type":"tf2_msgs/msg/TFMessage"}],"outputs":[{"name":"/lio/odometry","type":"nav_msgs/msg/Odometry","note":"proposed"},{"name":"/lio/map","type":"sensor_msgs/msg/PointCloud2","note":"proposed"}],"parameters":[{"name":"extrinsic_T / extrinsic_R","default":"from SF-02","description":"LiDAR → IMU extrinsics."},{"name":"point filter / downsample size","default":"per config","description":"Trade accuracy for CPU."}],"snippets":[{"title":"Record a benchmark bag","label":"verified","language":"bash","code":"ros2 bag record /lidar/points /imu/data /tf /tf_static /ground_truth/odom -o lio_run_01"},{"title":"Measure latency from the monitor","label":"illustrative","language":"bash","code":"ros2 topic echo /lio/latency_ms"}],"expectedBehavior":"Odometry tracks ground truth through slip scenarios where wheel odometry fails; latency stays bounded during playback at 1× speed.","pitfalls":["Missing per-point timestamps → no de-skew → smeared maps.","Wrong LiDAR↔IMU extrinsic sign → divergence when turning.","Starting while moving corrupts gravity init.","Degenerate geometry (flat featureless floor) — expect drift; document it."]},"testPlan":["Three recorded sim runs (straight, loop, slip).","Same bags replayed through each estimator.","Fast-rotation run to stress IMU propagation.","Featureless-floor run to document degeneracy."],"measure":[{"metric":"ATE / RPE","definition":"evo_ape / evo_rpe on aligned trajectories."},{"metric":"Processing latency","definition":"Time from scan header stamp to odometry publish (ms), p50/p95."},{"metric":"CPU utilization","definition":"Process CPU % during playback."}],"document":["How to build and run.","Sensor requirements for simulation and hardware.","Benchmark results and known failure modes."],"integrate":"SF-01 can fuse /lio/odometry; SF-04 monitors its health; PM-01 benefits from a less-drifting odom frame."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"2581b052-1712-55fc-8b1e-50ada3c5a0f4","key":"SF-04","title":"Localization Confidence & Sensor Dropout","track_id":"SF","subtrack_id":"afccb056-82c0-5caf-b7cf-407c8ea1f56c","priority":"high","difficulty":"intermediate","estimate_hours":24,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"da95fb4b-23c3-5194-a5d5-b29cf88ae336","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["safety","health","diagnostics"],"spec":{"problem":"Localization can fail silently: a sensor driver stops publishing, LIO diverges, or covariance explodes. If mission logic keeps driving on a stale or wrong pose, the rover can leave the arena or hit obstacles.","goal":"A ROS 2 node that checks pose freshness, monitors covariance and per-sensor update age, detects sensor failure, publishes OK / DEGRADED / LOST, and drives autonomy-level degraded-operation decisions (slow, pause, request safe stop) — recovering only after valid measurements resume for a hold period.","why":{"need":"Autonomy is only safe if the rover knows when it doesn''t know where it is.","contribution":"Gives mission logic (AG-01) an explicit signal to slow, pause, or request a safe stop through the Controls interface contract (AG-07).","failureImpact":"Without it, a dropped IMU or LiDAR leads to confident but wrong motion.","consumers":["AG-01 mission state machine","AG-07 Controls interface (safe-stop request)","AG-06 operator visualization","NV-06 navigation recovery","AG-10 recovery state machine"]},"background":"Health monitoring is a small state machine over observable signals: time since last message per input, output rate, covariance trace or determinant, and innovation/rejection counts. Hysteresis (separate enter/exit thresholds and hold times) prevents flapping between states.","prerequisites":[{"concept":"Timers and message timestamps in rclpy","why":"Measuring message age correctly under sim time.","resourceIds":["2ba395f6-9e79-5444-a0a8-a4b0a749cf90","cf0fa0ac-5e1b-53f8-bd3c-fd51e1995dc7"]},{"concept":"Covariance interpretation","why":"What growing covariance means.","resourceIds":["28ba189d-b72b-5610-be2c-70d7db674321"]},{"concept":"Finite-state machines with hysteresis","why":"OK/DEGRADED/LOST with hold times.","resourceIds":["884a4786-fd54-5ef7-8b11-9e8784da5ec1"]},{"concept":"ROS diagnostics","why":"Standard way to publish component health.","resourceIds":["c6e44073-7ccb-5ef7-8747-5a3bccac116b"]}],"readFirst":["Purdue fallback_pointcloud_node.py (≈40 lines).","Purdue state_manager.py `stop_everything` and `periodic`."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_perception/scripts/fallback_pointcloud_node.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_perception/scripts/fallback_pointcloud_node.py","isFolder":false,"summary":"`FallbackPointCloudNode` forwards a primary PointCloud2 stream; if no primary message arrives within a `timeout` parameter (default 5.0 s), it switches to forwarding a secondary stream until the primary returns.","inspect":["`FallbackPointCloudNode.__init__` — `timeout` parameter and `create_timer`","`timeout_cb`","`primary_cb` — `self.timeout.reset()`","`secondary_cb`"],"relevance":"The simplest correct pattern for timeout-based failover using a resettable timer.","questions":["What happens the instant the primary resumes — is there any hold period?","The node registers as `apriltag_combine_node` — what problems can a copy-pasted node name cause?","How would you report which source is active to other nodes?"],"adaptation":"Use the resettable-timer pattern per input, add hysteresis and publish the active state explicitly.","limitations":["No hysteresis: switches back immediately.","Doesn''t publish its state.","Node name appears copy-pasted from another node."],"verifiedOn":"2026-10-25"},{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_behavior/lunabot_behavior/state_manager.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_behavior/lunabot_behavior/state_manager.py","isFolder":false,"summary":"`StateManager` node driving an Enum-based state machine: event and autonomy callbacks, a periodic loop and a `stop_everything` routine.","inspect":["`StateManager.event_cb`","`StateManager.process_event`","`StateManager.stop_everything`","`StateManager.periodic`"],"relevance":"Shows how an external event (e.g. a localization fault) can be injected into mission logic via an events topic.","questions":["How are events delivered to the state manager, and what message type is used?","What does stop_everything actually command?"],"adaptation":"Publish a localization fault event that AG-01 maps to a safe-stop transition.","limitations":["Event set is specific to Purdue''s mission."],"verifiedOn":"2026-10-25"}],"analyze":["Enumerate every way localization can fail in our stack (per input).","For each, choose the observable signal and threshold.","Decide which responses belong in this node vs mission logic."],"design":"`localization_health` node in `lunabot_localization`. Subscribes to each fused input and /odometry/filtered; timers per input track age. State machine: OK → DEGRADED (one input stale or covariance above warn) → LOST (output stale, or covariance above critical, or all position sources stale). Exits require the condition to clear for `recovery_hold_s`. Publishes diagnostic_msgs/DiagnosticStatus on /localization/health and a latched-style (transient local QoS) state.","guidance":{"packageStructure":"lunabot_localization/\n  lunabot_localization/health_node.py\n  lunabot_localization/health_logic.py   # pure, unit-tested\n  config/health.yaml\n  test/test_health_logic.py","files":["health_node.py","health_logic.py","config/health.yaml","test/test_health_logic.py"],"inputs":[{"name":"/wheel/odometry","type":"nav_msgs/msg/Odometry","note":"proposed"},{"name":"/imu/data","type":"sensor_msgs/msg/Imu","note":"proposed"},{"name":"/lio/odometry","type":"nav_msgs/msg/Odometry"},{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"}],"outputs":[{"name":"/localization/health","type":"diagnostic_msgs/msg/DiagnosticStatus","note":"proposed; may become a custom msg"},{"name":"/diagnostics","type":"diagnostic_msgs/msg/DiagnosticArray"}],"parameters":[{"name":"input_timeouts_s","default":"{imu: 0.2, wheel: 0.2, lio: 0.5}","description":"Per-input staleness thresholds."},{"name":"cov_warn / cov_critical","default":"tuned in sim","description":"Position covariance trace thresholds."},{"name":"recovery_hold_s","default":"2.0","description":"Time inputs must be healthy before leaving DEGRADED/LOST."}],"snippets":[{"title":"Pure transition function (testable without ROS)","label":"illustrative","language":"python","code":"def next_state(state, ages, cov_trace, now, cfg):\n    stale = [k for k, a in ages.items() if a > cfg.timeouts[k]]\n    if ages[''output''] > cfg.timeouts[''output''] or cov_trace > cfg.cov_critical:\n        return ''LOST''\n    if stale or cov_trace > cfg.cov_warn:\n        return ''DEGRADED''\n    return ''OK'' if state.healthy_for(now) >= cfg.recovery_hold_s else state.name"},{"title":"Simulate a sensor dropout","label":"adapt","language":"bash","code":"# Pause the IMU bridge for 3 s during playback\nros2 lifecycle set /imu_driver deactivate && sleep 3 && ros2 lifecycle set /imu_driver activate","note":"Only works if the driver is a lifecycle node; otherwise filter the topic in a relay."}],"expectedBehavior":"Killing the IMU flips status to DEGRADED within the configured timeout; killing all pose sources produces LOST; restoring inputs returns to OK only after the hold period.","pitfalls":["Comparing ROS time to wall time (use the node clock).","Flapping without hysteresis.","Using default (volatile) QoS so late joiners miss the current state."]},"testPlan":["Unit tests for every transition and hysteresis.","Dropout test: IMU off 3 s, LiDAR off 3 s, all off.","Covariance blow-up test: inject large-noise measurements.","Flapping test: inputs toggling near threshold."],"measure":[{"metric":"Detection latency","definition":"Time from last valid message to status change (ms)."},{"metric":"False alarms","definition":"Status changes during nominal 10-minute run."}],"document":["State diagram with thresholds.","Which response each state triggers and who owns it."],"integrate":"AG-01 maps LOST → SAFE_STOP and DEGRADED → slow/pause; the safe-stop request crosses to Controls only via the AG-07 contract; AG-06 displays status."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"9a90482b-015a-5d7a-89b9-149227bf65a7","key":"PM-01","title":"Terrain-Aware Traversability Costmap","track_id":"PM","subtrack_id":"7f4ceae5-1d7f-55ce-846b-46474652b8f7","priority":"critical","difficulty":"intermediate","estimate_hours":40,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":"f80bd1eb-a9ba-592b-8876-1072c9c18403","milestone_id":"d6c24028-a269-560d-a818-d2e1bd987d11","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["costmap","nav2","sprint-01"],"spec":{"problem":"The arena contains rocks, craters and slopes. A planner needs a 2D grid that says, for each cell, whether the rover can drive there safely, considering slope, roughness, rover size and unknown space.","goal":"A ROS 2 node that turns PointCloud2 input into an elevation grid, estimates slope and roughness, marks unsafe cells, inflates by rover footprint and publishes a Nav2-compatible OccupancyGrid distinguishing free, lethal and unknown — visualized in RViz and tested on flat, rocky, sloped and unknown scenarios.","why":{"need":"Without a terrain-aware map the rover cannot avoid craters and rocks it was never told about.","contribution":"Provides the cost layer used by NV-01 planners and the Nav2 global/local costmaps in NV-02.","failureImpact":"False lethal cells block all paths (rover freezes); missed hazards let the planner route into craters.","consumers":["NV-01","NV-02","NV-04","AG-06"]},"background":"Project points into an x-y grid and aggregate height per cell (mean, max, or a robust statistic). Slope comes from the height gradient between neighboring cells (Δz/Δxy); roughness from local height variance or the residual of a plane fit. Inflation spreads cost outward by the rover''s inscribed/circumscribed radius so the planner can treat the rover as a point. Nav2 OccupancyGrid uses 0–100 with −1 for unknown; the internal Costmap2D uses 0–254 with 255 unknown — mixing these scales is a classic bug.","prerequisites":[{"concept":"PointCloud2 structure and parsing","why":"You will read raw byte buffers into numpy arrays.","resourceIds":["03399223-0ba3-5288-8423-163bf1e33889","cee49ff8-8f6c-5041-bab7-2ab05fa126db"]},{"concept":"Occupancy grids","why":"Grid resolution, origin and row-major indexing.","resourceIds":["a90c1792-89cb-532d-a2b3-d146f8d8141b"]},{"concept":"Finite-difference gradients","why":"Slope from neighboring heights.","resourceIds":["ca85ca36-be1a-5017-a601-05df5375fb6e"]},{"concept":"TF and frames","why":"Clouds must be transformed into a gravity-aligned frame first.","resourceIds":["48d88130-ebb2-50e8-a73f-0c1df1ba777b"]}],"readFirst":["GOFIRST costmapGenerator.py (≈110 lines) and costmap_config.yaml.","grid_map README sections on filters (slope, roughness)."],"references":[{"repo":"GOFIRST-Robotics/Lunabotics","path":"src/alexblox/alexblox/costmapGenerator.py","url":"https://github.com/GOFIRST-Robotics/Lunabotics/blob/main/src/alexblox/alexblox/costmapGenerator.py","isFolder":false,"summary":"`CostmapGenerator` node: subscribes to a fused PointCloud2, builds an average height map with `np.add.at`, computes gradient magnitude via `np.gradient`, thresholds against `lethal_slope`, and publishes an OccupancyGrid.","inspect":["`CostmapGenerator.__init__` — parameters `costmap_resolution`, `lethal_slope`, `lethal_cost`, `unknown_cost`, topics","`CostmapGenerator.pointCloudCallback` — reshape to XYZ, height averaging, gradient, thresholding, message packaging"],"relevance":"A compact, working slope-based costmap from a Lunabotics team — an ideal baseline to understand and improve.","questions":["The code assumes 4 float32 fields per point (`reshape(-1, 4)`). What happens if the cloud has a different point_step?","Grid bounds come from the min/max of each cloud. What does that mean for map origin stability between messages?","Defaults are lethal 254 / unknown 255, but OccupancyGrid expects 0–100 / −1; the config overrides them to 100 / −1. Why is that override essential?","No inflation is applied — where should rover footprint be accounted for?","In which frame is the input cloud, and is it gravity-aligned?"],"adaptation":"Keep the vectorized numpy approach. Add: fixed map bounds and origin, explicit frame transform, roughness layer, footprint inflation, and correct value ranges. Parse PointCloud2 by field name (sensor_msgs_py.point_cloud2) instead of assuming layout.","limitations":["Assumes a fixed point layout.","Map origin moves every message.","No roughness, inflation or temporal accumulation.","Default cost values are outside OccupancyGrid''s valid range unless overridden."],"verifiedOn":"2026-10-25"},{"repo":"GOFIRST-Robotics/Lunabotics","path":"config/costmap_config.yaml","url":"https://github.com/GOFIRST-Robotics/Lunabotics/blob/main/config/costmap_config.yaml","isFolder":false,"summary":"Parameters for the generator: unknown_cost −1, lethal_cost 100, input/output topics, 0.1 m resolution, lethal_slope 0.3 (unitless gradient).","inspect":["`lethal_slope: 0.3`","`costmap_resolution: 0.1`","`unknown_cost: -1`, `lethal_cost: 100`"],"relevance":"Shows the OccupancyGrid-compatible values that make the node''s output valid.","questions":["What physical slope angle does a gradient of 0.3 correspond to?","How should resolution relate to rover wheel size and rock size?"],"adaptation":"Express slope thresholds in degrees in our config and convert internally, with rationale.","limitations":["Slope units are documented in the file as non-existent; make units explicit in ours."],"verifiedOn":"2026-10-25"}],"analyze":["Draw the pipeline from bytes to OccupancyGrid.","List every assumption about input layout and frames.","Compute the angle for lethal_slope 0.3 (≈16.7°) and compare to rover capability from mechanical team."],"design":"Package `lunabot_perception`, node `traversability_node`. Input: filtered cloud (PM-02) transformed to `odom` (gravity-aligned). Fixed-size rolling window centered on the rover (e.g. 8 × 8 m) at 0.05–0.10 m. Layers: elevation (mean), slope (gradient magnitude → degrees), roughness (std-dev of heights per cell), observed mask. Cost = max(slope cost, roughness cost); unknown where unobserved; inflation using rover radius. Publish OccupancyGrid on /perception/traversability for a Nav2 StaticLayer or a custom layer.","guidance":{"packageStructure":"lunabot_perception/\n  lunabot_perception/traversability_node.py\n  lunabot_perception/terrain_grid.py     # pure numpy, unit-tested\n  config/traversability.yaml\n  rviz/traversability.rviz\n  test/test_terrain_grid.py","files":["traversability_node.py","terrain_grid.py","config/traversability.yaml","test/test_terrain_grid.py"],"inputs":[{"name":"/perception/points_filtered","type":"sensor_msgs/msg/PointCloud2","note":"from PM-02 (proposed)"},{"name":"/tf","type":"tf2_msgs/msg/TFMessage"}],"outputs":[{"name":"/perception/traversability","type":"nav_msgs/msg/OccupancyGrid","note":"proposed"},{"name":"/perception/elevation","type":"nav_msgs/msg/OccupancyGrid","note":"debug visualization (proposed)"}],"parameters":[{"name":"resolution_m","default":"0.10","description":"Cell size."},{"name":"window_m","default":"8.0","description":"Rolling window around the rover."},{"name":"lethal_slope_deg","default":"decided with mechanical team","description":"Internal limit; not a rule."},{"name":"roughness_lethal_m","default":"tuned in sim","description":"Height std-dev threshold."},{"name":"inflation_radius_m","default":"rover circumscribed radius","description":"From SIM-02 footprint."}],"snippets":[{"title":"Read a PointCloud2 by field names","label":"adapt","language":"python","code":"from sensor_msgs_py import point_cloud2\npts = point_cloud2.read_points_numpy(msg, field_names=(''x'', ''y'', ''z''), skip_nans=True)"},{"title":"Slope from a height grid","label":"illustrative","language":"python","code":"gy, gx = np.gradient(height, resolution)\nslope_deg = np.degrees(np.arctan(np.hypot(gx, gy)))\ncost = np.where(np.isnan(height), -1, np.where(slope_deg > lethal_slope_deg, 100, 0))"},{"title":"Check the published grid","label":"verified","language":"bash","code":"ros2 topic echo /perception/traversability --field info"}],"expectedBehavior":"Flat floor → free; rocks above threshold → lethal plus inflation ring; crater rims → lethal; unseen cells → unknown (−1). Map stays aligned with the world as the rover moves.","pitfalls":["Computing slope in the sensor frame (tilted) instead of a gravity-aligned frame.","Row/column swap when filling OccupancyGrid.data.","Using 254/255 in an OccupancyGrid.","NaN propagation through np.gradient creating false lethal borders around unknown space."]},"testPlan":["Unit: flat plane → all free; tilted plane at known angle → slope within 0.5°; step → lethal edge.","Sim scenarios: flat, rock field, crater, slope, partially observed.","Rate test: costmap update rate during playback.","Alignment test: drive a loop and confirm static rocks stay in place on the map."],"measure":[{"metric":"Costmap update rate","definition":"Hz of /perception/traversability during playback."},{"metric":"Processing latency","definition":"Cloud stamp → grid publish (ms)."},{"metric":"Hazard coverage","definition":"Fraction of known sim hazards marked lethal (sim ground truth)."},{"metric":"False lethal rate","definition":"Fraction of known-flat cells marked lethal."}],"document":["Layer definitions and thresholds with rationale.","How to plug into Nav2 (layer config).","Screenshots per scenario."],"integrate":"NV-01 consumes the grid directly for benchmarking; NV-02 feeds it into Nav2 costmaps."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"5da4dde9-125f-5417-b116-5417115ab06b","key":"PM-02","title":"Point Cloud Filtering and Accumulation","track_id":"PM","subtrack_id":"2931d56b-0712-5928-9d36-69894f01ca40","priority":"high","difficulty":"intermediate","estimate_hours":24,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"da95fb4b-23c3-5194-a5d5-b29cf88ae336","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["point-cloud","benchmark"],"spec":{"problem":"Raw LiDAR clouds contain NaNs, self-hits on the rover body, dust returns and far more points than needed. Some sensors also produce small, sparse frames that individually are too thin to map terrain.","goal":"A configurable point cloud preprocessing node: invalid-point removal, crop box (self-filter), voxel downsampling and optional multi-frame accumulation — with a before/after benchmark of runtime, density and latency.","why":{"need":"Every perception and LIO consumer is faster and more robust on clean, right-sized clouds.","contribution":"Feeds PM-01 and optionally SF-03.","failureImpact":"Self-hits create phantom obstacles around the rover; unfiltered clouds overload the CPU and add latency.","consumers":["PM-01","SF-03","PM-06"]},"background":"Voxel downsampling replaces all points in each cube of side `leaf` by their centroid. Accumulating N frames increases density but smears geometry if the rover moves, unless each frame is transformed into a fixed frame (odom) using the pose at its timestamp.","prerequisites":[{"concept":"PointCloud2 and numpy parsing","why":"Efficient filtering.","resourceIds":["03399223-0ba3-5288-8423-163bf1e33889"]},{"concept":"Voxel grids","why":"Downsampling trade-offs.","resourceIds":["ea779d3b-15b9-51a7-953e-009df6ec728a"]},{"concept":"TF lookups at a timestamp","why":"Accumulating into a fixed frame.","resourceIds":["9186a3b8-09b3-5742-be51-a78728ece9fc"]}],"readFirst":["Utah README_FRAME_ACCUMULATION.md.","COD mapping_launch.py — note the point_cloud_assembler step."],"references":[{"repo":"utahrobotics/utah-lunabotics-2027","path":"unilidar_iceoryx_publisher/README_FRAME_ACCUMULATION.md","url":"https://github.com/utahrobotics/utah-lunabotics-2027/blob/main/unilidar_iceoryx_publisher/README_FRAME_ACCUMULATION.md","isFolder":false,"summary":"Design notes for Utah''s frame accumulation feature: combining several ~5k-point frames into larger clouds before publishing, analogous to Point-LIO''s `con_frame`, with compile-time `ACCUMULATE_FRAMES` / `ACCUMULATION_COUNT` constants and increased cloud capacity.","inspect":["`ACCUMULATE_FRAMES`, `ACCUMULATION_COUNT` constants","Section on increased point cloud capacity"],"relevance":"Explains why sparse LiDAR frames are accumulated and the latency trade-off.","questions":["Is accumulation done in the sensor frame or a world frame?","What latency does accumulating 5 frames add at the sensor''s frame rate?","Why are these compile-time constants rather than parameters, and should ours be runtime parameters?"],"adaptation":"Implement accumulation as a runtime parameter, transforming each frame into odom before merging.","limitations":["Specific to Unitree LiDAR + iceoryx transport.","Compile-time configuration."],"verifiedOn":"2026-10-25"},{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_bringup/launch/mapping_launch.py","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_bringup/launch/mapping_launch.py","isFolder":false,"summary":"Mapping launch composing rtabmap_sync rgbd_sync nodes, an rtabmap_util point_cloud_assembler and rtabmap_slam.","inspect":["Node using package `rtabmap_util`, executable `point_cloud_assembler`","`generate_launch_description()`"],"relevance":"An off-the-shelf assembler for accumulating clouds, already used by a team.","questions":["What parameters control how many clouds the assembler combines and in which frame?","Could we use the assembler directly instead of writing our own?"],"adaptation":"Evaluate point_cloud_assembler as the accumulation stage before writing custom code.","limitations":["Pulls in the RTAB-Map dependency stack."],"verifiedOn":"2026-10-25"}],"analyze":["Measure raw cloud size and rate from the simulated LiDAR.","Determine which rover body regions produce self-hits.","Decide whether accumulation is needed at all for our LiDAR."],"design":"Node `cloud_preprocessor` in `lunabot_perception`: NaN removal → crop box (exclude rover body) → range limits → voxel grid → optional accumulation of N frames in odom. All stages enabled/configured by parameters; publishes timing diagnostics.","guidance":{"packageStructure":"lunabot_perception/\n  lunabot_perception/cloud_preprocessor.py\n  lunabot_perception/cloud_ops.py\n  config/preprocess.yaml\n  scripts/bench_preprocess.py","files":["cloud_preprocessor.py","cloud_ops.py","config/preprocess.yaml","scripts/bench_preprocess.py"],"inputs":[{"name":"/lidar/points","type":"sensor_msgs/msg/PointCloud2","note":"proposed"},{"name":"/tf","type":"tf2_msgs/msg/TFMessage"}],"outputs":[{"name":"/perception/points_filtered","type":"sensor_msgs/msg/PointCloud2","note":"proposed"}],"parameters":[{"name":"voxel_leaf_m","default":"0.05","description":"Voxel size."},{"name":"crop_box_min/max","default":"rover body bounds","description":"Self-filter."},{"name":"accumulate_frames","default":"1","description":"1 = disabled."},{"name":"max_range_m","default":"8.0","description":"Ignore far returns."}],"snippets":[{"title":"Voxel downsample with numpy","label":"illustrative","language":"python","code":"keys = np.floor(pts / leaf).astype(np.int64)\n_, inv = np.unique(keys, axis=0, return_inverse=True)\nout = np.zeros((inv.max() + 1, 3)); np.add.at(out, inv, pts)\nout /= np.bincount(inv)[:, None]"},{"title":"Measure rate before/after","label":"verified","language":"bash","code":"ros2 topic hz /lidar/points\nros2 topic hz /perception/points_filtered\nros2 topic bw /perception/points_filtered"}],"expectedBehavior":"Output contains no NaNs or rover-body points, is 5–20× smaller, and with accumulation enabled static terrain remains sharp while driving.","pitfalls":["Accumulating in the sensor frame while moving → smearing.","Voxel leaf larger than smallest hazard of interest.","Python loops over points (use vectorized numpy)."]},"testPlan":["Unit tests for each stage on synthetic clouds.","Self-filter test: stationary rover, no points within body box.","Benchmark over a fixed bag at leaf sizes 0.02/0.05/0.10.","Accumulation N = 1/3/5 while driving."],"measure":[{"metric":"Processing latency","definition":"Per-cloud processing time (ms) p50/p95."},{"metric":"Point reduction","definition":"Output / input point count."},{"metric":"Output rate","definition":"Hz of filtered cloud."}],"document":["Stage diagram and parameters.","Benchmark table and recommended defaults."],"integrate":"PM-01 subscribes to /perception/points_filtered."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"efd58f27-b4c0-5056-a2fc-2b97eb2b54d9","key":"PM-03","title":"AprilTag Detection & Localization Support","track_id":"PM","subtrack_id":"02f6eb7f-9be4-537f-bb66-e762ee65e92b","priority":"medium","difficulty":"intermediate","estimate_hours":24,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"da95fb4b-23c3-5194-a5d5-b29cf88ae336","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["apriltag","vision","rules-check"],"spec":{"problem":"At the start of a run the rover needs to know where it is relative to the arena. Fiducial markers provide an absolute pose reference that odometry cannot.","goal":"A ROS 2 pipeline that detects AprilTags in a simulated marker scene for testing and calibration, estimates camera and rover pose, publishes it, reports pose error against ground truth, and documents whether the current rules allow artificial markers during competition before anyone plans to rely on them.","why":{"need":"An absolute fix lets the map frame be anchored to the arena so zones are in the right place.","contribution":"Provides map → odom correction / initial pose for SF-01 and NV-03.","failureImpact":"Without an absolute reference, zone boundaries are only as good as the initial placement guess.","consumers":["SF-01","NV-03","AG-01"]},"background":"AprilTag detection finds the four tag corners; with camera intrinsics and the physical tag size, solvePnP recovers the tag pose in the camera frame. Inverting and chaining with known tag placement gives the camera (and via TF, rover) pose in the arena. Error grows with distance and viewing angle.","prerequisites":[{"concept":"Camera intrinsics and CameraInfo","why":"Pose estimation needs calibrated intrinsics.","resourceIds":["a5360873-884d-5142-86a8-5960a0106b69"]},{"concept":"TF chaining and inversion","why":"tag ← camera ← base_link chain.","resourceIds":["b0f6e245-ddd5-52cc-a7cf-7b15535d06d8"]},{"concept":"AprilTag families and sizes","why":"Configure detector correctly.","resourceIds":["9d1538dd-cdf8-5db1-bab7-5327f12c4943"]}],"readFirst":["Current Lunabotics guidebook rules on fiducials/beacons (see research TODO).","GOFIRST apriltag_node.py.","Purdue apriltag_combine.py."],"references":[{"repo":"GOFIRST-Robotics/Lunabotics","path":"src/apriltag/apriltag/apriltag_node.py","url":"https://github.com/GOFIRST-Robotics/Lunabotics/blob/main/src/apriltag/apriltag/apriltag_node.py","isFolder":false,"summary":"`ApriltagNode` subscribes to `/tag_detections` (AprilTagDetectionArray), computes transforms from detections, broadcasts TF, and exposes a `resetOdom` Trigger service. Field layout is selected via an `autonomous_field_type` parameter.","inspect":["`ApriltagNode.__init__` (parameter `autonomous_field_type`, subscription, TransformBroadcaster, `resetOdom` service)","`tagDetectionSub`","`postTransform`","`broadcast_transform`","`reset_callback`"],"relevance":"End-to-end example from detections to a published transform, with per-field tag placement.","questions":["Which frame does it broadcast and relative to what parent?","How does reset_callback interact with odometry?","How are multiple simultaneous tags handled?"],"adaptation":"Use a detector node (apriltag_ros) and write a thin node that converts detections to a map-frame pose with covariance, rather than directly rewriting TF.","limitations":["Field-specific constants.","Behavior with partial/occluded tags not obvious."],"verifiedOn":"2026-10-25"},{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_perception/scripts/apriltag_combine.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_perception/scripts/apriltag_combine.py","isFolder":false,"summary":"`ApriltagCombine` node with a `detection_cb` that merges AprilTagDetectionArray messages from multiple cameras into one stream.","inspect":["`ApriltagCombine.__init__`","`ApriltagCombine.detection_cb`"],"relevance":"Pattern for multi-camera tag fusion.","questions":["Does it preserve each detection''s frame_id?","What happens when two cameras see the same tag?"],"adaptation":"If we use multiple cameras, combine detections but keep per-camera frames so TF can resolve them.","limitations":["Simple concatenation; no weighting."],"verifiedOn":"2026-10-25"}],"analyze":["Draw the frame chain used by GOFIRST from tag to robot.","Identify how pose error depends on distance in their setup.","Summarize what the current rules say about markers (from the official guidebook only)."],"design":"Use `apriltag_ros` (christianrauch) for detection on /camera/image_raw + /camera/camera_info. Node `tag_localizer` converts detections into geometry_msgs/PoseWithCovarianceStamped in map using a YAML of tag placements; covariance grows with distance/angle. Output can seed SF-01 initial pose or a map-frame filter.","guidance":{"packageStructure":"lunabot_perception/\n  lunabot_perception/tag_localizer.py\n  config/tags_sim.yaml\n  launch/apriltag.launch.py\n  scripts/tag_error_report.py","files":["tag_localizer.py","config/tags_sim.yaml","launch/apriltag.launch.py","scripts/tag_error_report.py"],"inputs":[{"name":"/camera/image_raw","type":"sensor_msgs/msg/Image","note":"proposed"},{"name":"/camera/camera_info","type":"sensor_msgs/msg/CameraInfo","note":"proposed"},{"name":"/detections","type":"apriltag_msgs/msg/AprilTagDetectionArray","note":"apriltag_ros output"}],"outputs":[{"name":"/localization/tag_pose","type":"geometry_msgs/msg/PoseWithCovarianceStamped","note":"proposed"}],"parameters":[{"name":"tag_family","default":"36h11","description":"Must match printed tags."},{"name":"tag_size_m","default":"measured","description":"Black border edge length."},{"name":"max_detection_range_m","default":"tuned","description":"Reject far detections."}],"snippets":[{"title":"Inspect detections","label":"verified","language":"bash","code":"ros2 topic echo /detections --once"},{"title":"Pose error report","label":"illustrative","language":"bash","code":"python3 scripts/tag_error_report.py --bag tag_run_01 --gt /ground_truth/odom"}],"expectedBehavior":"Pose error is small up close and grows with distance and angle; no pose is published when no tag is visible.","pitfalls":["Wrong tag size → scaled translation error.","Uncalibrated or mismatched CameraInfo.","Optical frame vs camera_link axis conventions.","Assuming markers are allowed without checking current rules."]},"testPlan":["Grid of camera positions at 1/2/3/4 m and 0/30/60° viewing angles.","No-tag frames produce no pose.","Partial occlusion test."],"measure":[{"metric":"Pose error","definition":"Translation (m) and yaw (deg) vs ground truth, by distance bin."},{"metric":"Detection rate","definition":"Fraction of frames with a valid detection when a tag is in view."}],"document":["Error characterization chart.","Rules summary with citation."],"integrate":"SF-01/NV-03 can use the pose as an initial map anchor."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"9844330b-91a8-5120-9ae7-3ef106e02e75","key":"PM-04","title":"Lunar Dataset Investigation (LuSNAR)","track_id":"PM","subtrack_id":"1e9419c0-4ce8-5e66-9a5f-cf1c9018a456","priority":"medium","difficulty":"beginner","estimate_hours":16,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"84ebc8e4-7a5d-5543-ba35-2e0398f7b8f6","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["dataset","research","good-first-task"],"spec":{"problem":"We want real or realistic lunar-surface data to evaluate perception algorithms, but we don''t yet know what LuSNAR contains or whether it fits our sensors.","goal":"A notebook that inspects at least one LuSNAR archive, identifies formats, modalities, metadata, timestamps and labels actually present, visualizes samples, proposes candidate benchmarks and documents limitations — without assuming any modality exists before inspection.","why":{"need":"Algorithms tuned only on simulation may fail on real terrain textures and lighting.","contribution":"Determines whether PM-05, PM-06 and PM-07 can use LuSNAR for evaluation.","failureImpact":"Building on wrong assumptions about the dataset wastes weeks.","consumers":["PM-05","PM-06","PM-07"]},"background":"The Hugging Face listing shows nine archives (Moon_1.zip … Moon_9.zip) plus a README. The dataset is gated: you must sign in and request access before files can be downloaded. Contents must be confirmed by inspection.","prerequisites":[{"concept":"Python, numpy and Jupyter","why":"Exploration notebook.","resourceIds":["65324b7c-03ed-5de6-8529-27060b8b2946"]},{"concept":"Image and point cloud formats","why":"Recognize what you find.","resourceIds":["03399223-0ba3-5288-8423-163bf1e33889"]}],"readFirst":["The dataset card/README on Hugging Face (after access approval).","Any license terms on the dataset page."],"references":[{"repo":"huggingface:xuboluo2001/LuSNAR","path":"/","url":"https://huggingface.co/datasets/xuboluo2001/LuSNAR/tree/main","isFolder":true,"verifiedOn":"2026-10-25","summary":"Dataset repository listing nine zip archives (Moon_1 … Moon_9) and a README. Gated: requires an authenticated Hugging Face account with granted access.","inspect":["README.md (dataset card)","One archive, e.g. Moon_1.zip"],"relevance":"Potential source of lunar-terrain imagery/geometry for evaluating perception.","questions":["What modalities are actually present (inspect, don''t assume)?","What are the coordinate frames and units?","Are there timestamps, poses, or labels? In what format?","What is the license and citation requirement?"],"adaptation":"If suitable, write a converter to a ROS 2 bag or a common format for PM evaluation.","limitations":["Access is gated.","Archive sizes may be large — check before downloading on shared machines.","Content unverified until inspected."]}],"analyze":["List every file type in one archive with counts and sizes.","Map each file type to a modality with evidence (headers, shapes).","Identify whether ground truth exists for any perception task."],"design":"A single Jupyter notebook `notebooks/lusnar_exploration.ipynb` plus `docs/lusnar_feasibility.md`. No ROS required.","guidance":{"packageStructure":"research/lusnar/\n  notebooks/lusnar_exploration.ipynb\n  docs/lusnar_feasibility.md\n  scripts/inventory.py","files":["lusnar_exploration.ipynb","lusnar_feasibility.md","inventory.py"],"inputs":[],"outputs":[{"name":"docs/lusnar_feasibility.md","type":"file"}],"parameters":[],"snippets":[{"title":"Download one archive after access approval","label":"adapt","language":"bash","code":"huggingface-cli login\nhuggingface-cli download xuboluo2001/LuSNAR Moon_1.zip --repo-type dataset --local-dir data/lusnar"},{"title":"Inventory an archive without extracting everything","label":"illustrative","language":"python","code":"import zipfile, collections\nz = zipfile.ZipFile(''data/lusnar/Moon_1.zip'')\nexts = collections.Counter(n.rsplit(''.'', 1)[-1] for n in z.namelist() if ''.'' in n)\nprint(exts.most_common())"}],"expectedBehavior":"A factual inventory and a clear go/no-go recommendation for each candidate benchmark.","pitfalls":["Assuming modalities from the dataset name.","Committing data files to git.","Ignoring license terms."]},"testPlan":["Notebook runs top-to-bottom on a fresh environment with documented requirements.","Inventory script output matches manual inspection."],"measure":[{"metric":"Coverage","definition":"Fraction of file types in the archive that are identified and documented."}],"document":["Inventory table.","Feasibility assessment per candidate benchmark.","License/citation."],"integrate":"Informs dataset choices for PM-05, PM-06, PM-07."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"e5fd0912-0a1b-5c05-9f43-7afa095f3392","key":"NV-01","title":"A* and S-Theta* Path Planning","track_id":"NV","subtrack_id":"b1a88252-1744-513a-88eb-a75388d16ad9","priority":"critical","difficulty":"advanced","estimate_hours":44,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":"f80bd1eb-a9ba-592b-8876-1072c9c18403","milestone_id":"d6c24028-a269-560d-a818-d2e1bd987d11","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["planning","benchmark","sprint-01"],"spec":{"problem":"Grid A* produces jagged 8-connected paths with many turns; on regolith, every turn costs time and causes slip. Any-angle planners like Theta* / S-Theta* produce shorter, smoother paths, but must still respect terrain cost and clearance.","goal":"Two planners — a baseline A* and an any-angle planner (adapted S-Theta* or Theta*) — that use turn penalties, terrain cost and rover clearance, visualized in RViz and compared on runtime, path length, clearance and number of turns.","why":{"need":"The rover must get from start to excavation to berm efficiently and safely, repeatedly.","contribution":"Provides global paths used by NV-02 (as a Nav2 planner plugin or offline benchmark).","failureImpact":"Poor paths waste mission time, increase slip and can graze hazards.","consumers":["NV-02","NV-04","AG-01"]},"background":"A* expands nodes in order of f = g + h with an admissible heuristic. Theta* adds a line-of-sight check: if the grandparent can see the neighbor, connect them directly, producing any-angle paths. S-Theta* adds a heading-change cost (alpha) to prefer fewer turns. Terrain cost can be added as a traversal cost multiplier; clearance by planning on an inflated map or penalizing cells near obstacles.","prerequisites":[{"concept":"Graph search: BFS, Dijkstra, A*","why":"Foundation for both planners.","resourceIds":["3c89f409-b976-5345-8cbb-3b1b80a8cfd8"]},{"concept":"Admissible heuristics","why":"Optimality vs speed.","resourceIds":["3c89f409-b976-5345-8cbb-3b1b80a8cfd8"]},{"concept":"Theta* line-of-sight","why":"Any-angle parent updates.","resourceIds":["d1946711-4ef4-5f60-988a-3f3bac5cf40a"]},{"concept":"Nav2 Costmap2D and planner plugins","why":"How the S-Theta* reference integrates.","resourceIds":["a90c1792-89cb-532d-a2b3-d146f8d8141b","821a3b83-f1e5-5200-a157-0b3fa76d4561"]}],"readFirst":["Red Blob Games A* introduction.","Theta* paper sections 1–4.","Purdue stheta_star.cpp (≈410 lines) and stheta_star_planner.cpp (≈135 lines)."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_nav/src/stheta_star.cpp","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_nav/src/stheta_star.cpp","isFolder":false,"summary":"S-Theta* implementation over a Nav2 Costmap2D: coordinate types, an alpha (heading-change) cost, line-of-sight with accumulated cost, path retracing and cost evaluation, plus goal adjustment.","inspect":["`calculateAlphaCost(Coord current, Coord grandparent, Coord goal)`","`SThetaStar::hasLineOfSight(Coord, Coord, double&)`","`SThetaStar::getTraversalCost` / `getCostmapCost` / `isBlocked`","`SThetaStar::retracePath`","`SThetaStar::calculatePathCost`","`SThetaStar::moveGoal`"],"relevance":"A Lunabotics-tested any-angle planner that already reads Nav2 costmaps — the main reference for this task.","questions":["How does calculateAlphaCost penalize deviation, and how is it weighted against distance?","How is cost accumulated along a line-of-sight segment, and which cells count as blocked?","What does moveGoal do when the goal cell is in collision?","What Options can be changed at runtime via updateOptions?"],"adaptation":"Port the algorithm (or wrap it) behind a common planner interface shared with our A*, so both are benchmarked on identical grids.","limitations":["Tightly coupled to nav2_costmap_2d types.","Parameter values tuned for Purdue''s rover and map resolution."],"verifiedOn":"2026-10-25"},{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_nav/src/stheta_star_planner.cpp","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_nav/src/stheta_star_planner.cpp","isFolder":false,"summary":"`SThetaStarPlanner`, a `nav2_core::GlobalPlanner` plugin wrapping SThetaStar: configure/activate/deactivate/cleanup lifecycle and `createPlan(start, goal)`; exported with PLUGINLIB_EXPORT_CLASS.","inspect":["`configure(...)` parameter declarations","`activate()`","`createPlan(const PoseStampedMsg &start, …)`","`PLUGINLIB_EXPORT_CLASS(SThetaStarPlanner, nav2_core::GlobalPlanner)`"],"relevance":"Exactly how to make a custom planner usable from Nav2''s planner_server.","questions":["Which parameters are declared in configure?","How does createPlan convert world poses to grid coordinates?"],"adaptation":"Use the same plugin shape if we deliver our planner to NV-02.","limitations":["C++ only; Python prototypes need a separate benchmark harness."],"verifiedOn":"2026-10-25"}],"analyze":["Write pseudocode of S-Theta*''s main loop.","Identify every tunable weight and its effect.","Compare against upstream nav2_theta_star_planner''s parameters."],"design":"Package `lunabot_planning`: a pure library (`grid_planners.py` or C++ lib) with a common interface `plan(grid, start, goal, params) → path`, implementations `AStar` and `SThetaStar`; a benchmark CLI over a set of saved grids (PGM + YAML) from PM-01/SIM-01; a ROS node publishing nav_msgs/Path for visualization. Optionally a Nav2 plugin wrapper.","guidance":{"packageStructure":"lunabot_planning/\n  lunabot_planning/grid_planners.py\n  lunabot_planning/benchmark.py\n  lunabot_planning/plan_viz_node.py\n  maps/*.pgm + *.yaml\n  test/test_planners.py","files":["grid_planners.py","benchmark.py","plan_viz_node.py","test/test_planners.py"],"inputs":[{"name":"/perception/traversability","type":"nav_msgs/msg/OccupancyGrid","note":"proposed"},{"name":"/goal_pose","type":"geometry_msgs/msg/PoseStamped"}],"outputs":[{"name":"/planning/astar_path","type":"nav_msgs/msg/Path","note":"proposed"},{"name":"/planning/stheta_path","type":"nav_msgs/msg/Path","note":"proposed"}],"parameters":[{"name":"turn_penalty","default":"tuned","description":"Cost per radian of heading change."},{"name":"terrain_weight","default":"tuned","description":"Multiplier on cell cost."},{"name":"lethal_threshold","default":"costmap lethal","description":"Cells ≥ this are blocked."},{"name":"clearance_m","default":"rover radius","description":"Minimum distance to lethal cells."}],"snippets":[{"title":"Bresenham-based line of sight (sketch)","label":"illustrative","language":"python","code":"def line_of_sight(grid, a, b):\n    for (x, y) in bresenham(a, b):\n        if grid[y, x] >= LETHAL:\n            return False\n    return True"},{"title":"Run the benchmark","label":"illustrative","language":"bash","code":"ros2 run lunabot_planning benchmark --maps maps/ --planners astar stheta --out results.csv"}],"expectedBehavior":"S-Theta* paths are shorter with fewer turns than A*, at some runtime cost; both avoid lethal cells and respect clearance.","pitfalls":["Line-of-sight that skips corner cells → paths that clip obstacles.","Heuristic inconsistent with terrain-weighted costs.","World/grid coordinate off-by-half-cell errors."]},"testPlan":["Unit tests: trivial grid, blocked goal, narrow corridor, no-path.","Property test: all path segments collision-free under footprint.","Benchmark on ≥ 10 maps from SIM-01 scenarios."],"measure":[{"metric":"Planning time","definition":"Wall-clock ms per plan (median, p95)."},{"metric":"Path length","definition":"Sum of segment lengths (m)."},{"metric":"Minimum clearance","definition":"Min distance from path to lethal cells (m)."},{"metric":"Turn count","definition":"Number of heading changes > 10°."}],"document":["Algorithm explanation with diagrams.","Benchmark results and recommendation."],"integrate":"NV-02 uses the recommended planner (plugin or upstream equivalent)."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"3f3aa0af-f122-53ba-b2d5-514fa557a5d3","key":"NV-02","title":"Nav2 Autonomous Navigation","track_id":"NV","subtrack_id":"a381e311-a93d-5e4f-bcba-6acaea011581","priority":"critical","difficulty":"advanced","estimate_hours":48,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"da95fb4b-23c3-5194-a5d5-b29cf88ae336","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["nav2","integration","behavior-tree"],"spec":{"problem":"Individually working localization, maps, planners and controllers do not make a navigating robot. Nav2 orchestrates them, but must be configured for our rover and must recover when paths become invalid or goals are unreachable.","goal":"Nav2 configured around our simulated rover''s localization (SF-01) and perception (PM-01) interfaces, demonstrating goal navigation, path replanning, obstacle avoidance, invalid-path handling and recovery behaviors — with velocity requests published to the autonomy side of the AG-07 Controls contract.","why":{"need":"This is the step where the rover first drives itself through the arena.","contribution":"Combines SF-01, PM-01 and NV-01 into the navigation capability AG-01 calls, and hands motion requests to Controls through the AG-07 interface.","failureImpact":"Without robust recovery, a single blocked path stalls the entire mission.","consumers":["AG-01","AG-02","AG-03","AG-05"]},"background":"Nav2''s bt_navigator executes a behavior tree that calls ComputePathToPose and FollowPath, wrapped in RecoveryNode and PipelineSequence. Costmaps (global/local) combine layers. Recovery behaviors (wait, back up, clear costmaps) run when planning or control fails.","prerequisites":[{"concept":"Behavior trees","why":"Reading and modifying Nav2 BT XML.","resourceIds":["2d84255f-edba-5a71-ad3c-56bed1d99bdd"]},{"concept":"Nav2 architecture and parameters","why":"Servers, plugins, costmaps.","resourceIds":["a90c1792-89cb-532d-a2b3-d146f8d8141b"]},{"concept":"Localization outputs (SF-01)","why":"Nav2 requires map/odom/base_link TF.","resourceIds":["a9d3d523-0225-5ccc-865c-0984777af6c1"]}],"readFirst":["Nav2 docs: concepts and configuration guide (from docs.nav2.org).","COD behavior tree XML.","GOFIRST nav2_isaac_sim.yaml."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_config/behavior_trees/nav_to_pose_with_consistent_replanning_and_if_path_becomes_invalid.xml","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_config/behavior_trees/nav_to_pose_with_consistent_replanning_and_if_path_becomes_invalid.xml","isFolder":false,"summary":"Nav2 BT (BTCPP_format 4) that replans only when the path becomes invalid, with RecoveryNode (6 retries), PipelineSequence, PlannerSelector/ControllerSelector, RateController, ComputePathToPose, IsPathValid, FollowPath, ReactiveFallback/ReactiveSequence, GoalUpdated and Wait nodes.","inspect":["Top-level `RecoveryNode number_of_retries=\"6\"`","`IsPathValid` + `Inverter` gating replanning","`PlannerSelector` / `ControllerSelector`","Recovery branch containing `Wait`"],"relevance":"Directly implements ''detect invalid paths → replan → recover'', the core of this task.","questions":["Under what conditions does the tree replan?","What recovery actions are present, and which useful ones (BackUp, ClearCostmap) are missing?","How does it react to a goal update mid-execution?"],"adaptation":"Start from this tree; add costmap clearing and a backup behavior appropriate for regolith; keep retries parameterized.","limitations":["Recovery set is minimal.","Tuned for COD''s planner/controller choices."],"verifiedOn":"2026-10-25"},{"repo":"GOFIRST-Robotics/Lunabotics","path":"config/nav2_isaac_sim.yaml","url":"https://github.com/GOFIRST-Robotics/Lunabotics/blob/main/config/nav2_isaac_sim.yaml","isFolder":false,"summary":"Full Nav2 parameter file (≈270 lines) for Isaac Sim, based on NVIDIA''s nova_carter navigation params: bt_navigator, controller, planner, costmaps, etc.","inspect":["`bt_navigator` section (navigators, frames, odom_topic)","controller_server and planner_server plugin selections","global/local costmap layer lists"],"relevance":"A complete starting configuration showing every server Nav2 needs.","questions":["Which planner and controller plugins are configured?","Which costmap layers are used and with what sources?","What would change for Gazebo vs Isaac Sim (use_sim_time, topics)?"],"adaptation":"Use as a checklist for our nav2_params.yaml; replace sources with our /perception/traversability and footprint from SIM-02.","limitations":["`use_sim_time: False` at top — must be true for Gazebo playback.","Derived from a wheeled indoor robot configuration."],"verifiedOn":"2026-10-25"}],"analyze":["Map every Nav2 server to the stack component it relies on.","Draw the BT and mark where failures propagate.","List the TF/topic contracts Nav2 needs and confirm each producer exists."],"design":"Package `lunabot_navigation` with `config/nav2_params.yaml`, `behavior_trees/navigate_lunar.xml` and `launch/navigation.launch.py` (includes nav2_bringup with our params). Global costmap: static/traversability layer + inflation; local costmap: rolling traversability + inflation. Planner: NV-01 recommendation (or Smac/Theta* upstream). Controller: Regulated Pure Pursuit or MPPI evaluated. Waypoint follower for scripted test missions.","guidance":{"packageStructure":"lunabot_navigation/\n  config/nav2_params.yaml\n  behavior_trees/navigate_lunar.xml\n  launch/navigation.launch.py\n  scripts/waypoint_mission.py\n  test/scenarios.md","files":["config/nav2_params.yaml","behavior_trees/navigate_lunar.xml","launch/navigation.launch.py","scripts/waypoint_mission.py"],"inputs":[{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"},{"name":"/tf","type":"tf2_msgs/msg/TFMessage"},{"name":"/perception/traversability","type":"nav_msgs/msg/OccupancyGrid","note":"proposed"},{"name":"/mission/goal_pose","type":"geometry_msgs/msg/PoseStamped","note":"proposed"}],"outputs":[{"name":"/autonomy/cmd_vel","type":"geometry_msgs/msg/TwistStamped","note":"autonomy motion request — AG-07 contract (proposed)"},{"name":"/plan","type":"nav_msgs/msg/Path"},{"name":"navigate_to_pose","type":"nav2_msgs/action/NavigateToPose","note":"action server"}],"parameters":[{"name":"use_sim_time","default":"true (sim)","description":"Must match Gazebo."},{"name":"robot_radius / footprint","default":"from SIM-02","description":"Used by costmaps."},{"name":"number_of_retries","default":"6","description":"BT recovery attempts."}],"snippets":[{"title":"Send a navigation goal from the CLI","label":"verified","language":"bash","code":"ros2 action send_goal /navigate_to_pose nav2_msgs/action/NavigateToPose \"{pose: {header: {frame_id: map}, pose: {position: {x: 3.0, y: 1.0}, orientation: {w: 1.0}}}}\" --feedback"},{"title":"Launch with our params","label":"illustrative","language":"bash","code":"ros2 launch lunabot_navigation navigation.launch.py use_sim_time:=true"}],"expectedBehavior":"The rover reaches waypoints, replans around a newly placed obstacle, runs recovery when stuck, and reports failure (not infinite retry) for unreachable goals.","pitfalls":["Controller publishing straight to a Controls-owned topic — remap its output to the autonomy request topic defined in AG-07 (/autonomy/cmd_vel).","Costmap footprint not matching the rover.","Missing map → odom transform (needs a static or localization publisher)."]},"testPlan":["Waypoint mission across the arena (3 runs).","Obstacle spawned on path mid-run → replan.","Goal inside lethal region → clean failure.","Localization degraded (SF-04) → navigation pauses."],"measure":[{"metric":"Goal success rate","definition":"Fraction of goals reached within tolerance."},{"metric":"Recovery frequency","definition":"Recovery actions per run."},{"metric":"Collision count","definition":"Contacts with obstacles in sim."}],"document":["Parameter rationale.","BT diagram.","Scenario results."],"integrate":"AG-01 calls navigate_to_pose; AG-05 records these scenarios for regression."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"92da24a3-0466-5f74-a27a-1ef9b8ebf26d","key":"NV-03","title":"Excavation & Deposition Goal Selection","track_id":"NV","subtrack_id":"013b0fd7-9099-5a14-935f-c5fed2585dcb","priority":"high","difficulty":"intermediate","estimate_hours":24,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"84ebc8e4-7a5d-5543-ba35-2e0398f7b8f6","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["mission","zones"],"spec":{"problem":"The mission needs to decide *where* to dig and *where* to deposit. Zones are defined by the arena layout; within them, some targets are cheaper to reach or more useful than others, and conditions change during the run.","goal":"A goal-selection node that defines excavation, deposition and forbidden regions, computes travel costs, estimates mission utility, selects targets, publishes goal poses and recomputes when conditions change — with reproducible scenarios.","why":{"need":"Autonomous cycles require choosing goals without a human.","contribution":"Supplies AG-01 with excavation/deposition goals and forbidden-area checks.","failureImpact":"Bad targets waste time or put the rover in forbidden areas.","consumers":["AG-01","AG-02","AG-03","AG-09"]},"background":"Zones are polygons in the map frame. Utility can combine travel cost (from the planner or a distance proxy), material availability (e.g. already-dug cells) and risk. Recompute on events: new obstacles, failed attempts, time remaining.","prerequisites":[{"concept":"Polygons and point-in-polygon","why":"Zone membership.","resourceIds":["3c89f409-b976-5345-8cbb-3b1b80a8cfd8"]},{"concept":"Map frame and arena coordinates","why":"Zones must be expressed in map.","resourceIds":["a9d3d523-0225-5ccc-865c-0984777af6c1"]},{"concept":"Cost functions","why":"Utility trade-offs.","resourceIds":["1022e3ee-39bc-58fb-bc6c-9cc93bc49cf2"]}],"readFirst":["Purdue zones.py (≈230 lines).","Official guidebook zone layout (research TODO)."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_behavior/lunabot_behavior/zones.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_behavior/lunabot_behavior/zones.py","isFolder":false,"summary":"Zone definitions and a `ZonesNode`: a `ZoneMeasurements` class holding start/excavation/berm offsets and sizes for several arena layouts (KSC and UCF variants, with inactive ones commented out), `make_zone`, shapely conversion helpers, distance helpers and RViz marker visualization.","inspect":["`class ZoneMeasurements` (active UCF layout constants and commented alternatives)","`make_zone(offset_x, offset_y, length_x, length_y)`","`zone_to_poly` / `point_to_shapely`","`get_distance_from_start` / `get_distance_from_exc` / `get_distance_from_berm`","`ZonesNode.visualize_zone` and `mainloop`"],"relevance":"Shows how a team encodes arena layouts and visualizes them; directly reusable ideas for our zone config.","questions":["How are alternative arena layouts selected — and what''s risky about switching by commenting code?","In which frame are offsets measured?","Where would target selection within a zone go?"],"adaptation":"Put layouts in YAML selected by parameter; keep shapely polygons; add a selection layer on top.","limitations":["Layouts selected by editing code.","Values reflect past arenas; must be re-verified against the current guidebook."],"verifiedOn":"2026-10-25"}],"analyze":["Which layout is active in the file and what are its dimensions?","How does Purdue use these zones in its states?","What information would improve target choice beyond distance?"],"design":"Node `goal_selector` in `lunabot_mission`: loads `config/arena_<layout>.yaml` (polygons for start, excavation, berm/deposition, forbidden); candidate targets sampled on a grid inside zones; score = w_travel·cost + w_risk·risk − w_util·utility; publishes PoseStamped goals on request (service) and on change; exposes `is_forbidden(pose)` service for safety checks.","guidance":{"packageStructure":"lunabot_mission/\n  lunabot_mission/goal_selector.py\n  lunabot_mission/zones.py\n  config/arena_sim.yaml\n  test/test_zones.py","files":["goal_selector.py","zones.py","config/arena_sim.yaml","test/test_zones.py"],"inputs":[{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"},{"name":"/perception/traversability","type":"nav_msgs/msg/OccupancyGrid","note":"proposed"}],"outputs":[{"name":"/mission/goal_pose","type":"geometry_msgs/msg/PoseStamped","note":"proposed"},{"name":"/mission/zones_markers","type":"visualization_msgs/msg/MarkerArray","note":"proposed"},{"name":"select_goal","type":"custom service (proposed)","note":"request excavation/deposit goal"}],"parameters":[{"name":"arena_layout","default":"sim","description":"YAML file selection."},{"name":"weights","default":"{travel, risk, utility}","description":"Scoring weights."},{"name":"sample_spacing_m","default":"0.5","description":"Candidate grid spacing."}],"snippets":[{"title":"Visualize zones","label":"verified","language":"bash","code":"ros2 topic echo /mission/zones_markers --once"},{"title":"Point-in-polygon with shapely","label":"illustrative","language":"python","code":"from shapely.geometry import Point, Polygon\nexc = Polygon(cfg[''excavation''])\nexc.contains(Point(x, y))"}],"expectedBehavior":"Selected goals always lie inside the correct zone, never in forbidden areas, and change when an obstacle blocks the previous choice.","pitfalls":["Zones defined in odom (drift) rather than map.","Goals placed too close to zone edges for the rover footprint.","Using layout values not verified against the current guidebook."]},"testPlan":["Unit tests for zone membership and footprint margins.","Scenario files: clear arena, blocked excavation sub-area, rover near berm.","Reproducibility: same scenario → same goals."],"measure":[{"metric":"Selection time","definition":"ms per selection."},{"metric":"Forbidden violations","definition":"Goals inside forbidden zones (must be 0)."}],"document":["Zone config format.","Scoring function with weight rationale."],"integrate":"AG-01 requests goals; AG-02/AG-03 use them; AG-09 optimizes the utility function further."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"09619c19-1fd4-570a-9b85-09d2daaf5308","key":"SIM-01","title":"Gazebo Lunabotics Arena","track_id":"SIM","subtrack_id":"9c12cc79-658a-5e34-ac0c-649e1ed2f40f","priority":"critical","difficulty":"intermediate","estimate_hours":36,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":"f80bd1eb-a9ba-592b-8876-1072c9c18403","milestone_id":"d6c24028-a269-560d-a818-d2e1bd987d11","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["gazebo","sprint-01","foundation"],"spec":{"problem":"Every autonomy task needs a place to run before hardware exists. Without a shared, reproducible arena, each person tests in a different world and results can''t be compared.","goal":"A runnable Gazebo arena with boundaries, terrain geometry, configurable rocks/obstacles, excavation and deposition zones, launch files and deterministic scenario loading — with assumptions documented against the latest verified competition rules.","why":{"need":"Simulation is where localization, perception, planning and mission logic are first proven.","contribution":"Enables testing for SF, PM, NV, MS and IT tracks; supplies ground truth.","failureImpact":"Without it, integration slips until hardware exists and bugs are found late and expensively.","consumers":["SF-01","PM-01","PM-02","NV-03","SIM-03","AG-05"]},"background":"Gazebo worlds are SDF files with physics, scene, lights and models. Systems (plugins) add physics, sensors and scene broadcasting. Scenarios can be parameterized by generating SDF from templates or spawning models at launch from a scenario YAML with a fixed seed.","prerequisites":[{"concept":"Gazebo basics and SDF worlds","why":"Build and run the world.","resourceIds":["d551ccf3-3b44-5f71-a5cb-996ecf360935","20615bd3-848f-55fb-ab76-08846fe13557"]},{"concept":"ROS 2 launch files","why":"Launch Gazebo with arguments.","resourceIds":["f25dec27-c4cf-5762-a7b9-9643f1443b1f"]},{"concept":"ros_gz bridge","why":"Expose ground truth and clock to ROS.","resourceIds":["5bc659ce-ac67-5c98-8285-9a73a5d91cce","b5e4dc6c-ed48-5a69-969f-e7b36916c458"]}],"readFirst":["Gazebo Harmonic SDF worlds tutorial.","COD lunabot_sim/worlds (high_resolution / low_resolution).","GOFIRST NASA_field.sdf.","Official guidebook arena description (research TODO)."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_sim/worlds","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/tree/master/lunabot_sim/worlds","isFolder":true,"summary":"COD''s simulation worlds, split into `high_resolution` and `low_resolution` variants.","inspect":["high_resolution/","low_resolution/"],"relevance":"Shows a fidelity/performance split worth copying so laptops can run the arena.","questions":["What differs between the two resolutions (meshes, heightmaps)?","How large are the assets and what real-time factor do they achieve?"],"adaptation":"Offer a lightweight world for CI and laptops and a detailed one for perception testing.","limitations":["Built for COD''s simulator version and assets."],"verifiedOn":"2026-10-25"},{"repo":"GOFIRST-Robotics/Lunabotics","path":"src/gazebo/gazebo_files/worlds/NASA_field.sdf","url":"https://github.com/GOFIRST-Robotics/Lunabotics/blob/main/src/gazebo/gazebo_files/worlds/NASA_field.sdf","isFolder":false,"summary":"SDF 1.8 world `NASA_field` using Ignition Gazebo system plugins (Physics, Sensors with ogre2, SceneBroadcaster, UserCommands).","inspect":["`<world name=\"NASA_field\">`","ignition-gazebo-physics-system / sensors-system / scene-broadcaster-system / user-commands-system plugins"],"relevance":"A minimal, readable world file for modern Gazebo — good starting skeleton.","questions":["Which plugins are required for sensors to work?","What would we add for heightmap terrain and zone markers?"],"adaptation":"Start from this skeleton (renaming to gz-sim plugin names for Harmonic) and add terrain, rocks and zones.","limitations":["Uses `ignition-` plugin names from older Gazebo releases.","Small file — terrain detail lives elsewhere or is absent."],"verifiedOn":"2026-10-25"}],"analyze":["Compare the two references'' structure.","List which plugins/systems each world needs for our sensors.","Write down every arena dimension we need and where it will come from (guidebook only)."],"design":"Package `lunabot_sim`: `worlds/arena_base.sdf` (boundaries, ground, lighting), `models/` (rocks, craters, zone markers), `scenarios/*.yaml` (seeded obstacle placement), `launch/arena.launch.py` (args: scenario, gui, headless, world_resolution) spawning models from the scenario, plus ros_gz_bridge for /clock and ground-truth pose.","guidance":{"packageStructure":"lunabot_sim/\n  worlds/arena_base.sdf\n  worlds/arena_lite.sdf\n  models/rock_small/, rock_large/, crater/\n  scenarios/flat.yaml, rocks.yaml, craters.yaml\n  launch/arena.launch.py\n  scripts/spawn_scenario.py\n  docs/assumptions.md","files":["worlds/arena_base.sdf","scenarios/rocks.yaml","launch/arena.launch.py","scripts/spawn_scenario.py","docs/assumptions.md"],"inputs":[],"outputs":[{"name":"/clock","type":"rosgraph_msgs/msg/Clock","note":"simulation time"},{"name":"/ground_truth/odom","type":"nav_msgs/msg/Odometry","note":"bridged (proposed)"}],"parameters":[{"name":"scenario","default":"flat","description":"Scenario YAML."},{"name":"seed","default":"0","description":"Random seed for placement."},{"name":"headless","default":"false","description":"Run without GUI (CI)."}],"snippets":[{"title":"Run Gazebo with a world","label":"verified","language":"bash","code":"gz sim -r worlds/arena_base.sdf"},{"title":"Bridge the clock","label":"verified","language":"bash","code":"ros2 run ros_gz_bridge parameter_bridge /clock@rosgraph_msgs/msg/Clock[gz.msgs.Clock"},{"title":"Launch a scenario","label":"illustrative","language":"bash","code":"ros2 launch lunabot_sim arena.launch.py scenario:=rocks seed:=42 headless:=true"}],"expectedBehavior":"Same scenario + seed → identical obstacle placement every run; real-time factor near 1.0 on a laptop with the lite world.","pitfalls":["Arena dimensions copied from other teams'' code instead of the guidebook.","Unseeded randomness.","Heavy meshes tanking real-time factor."]},"testPlan":["Launch each scenario headless in CI and check /clock advances.","Repeatability: spawn the same scenario twice and diff model poses.","Measure real-time factor for lite and full worlds."],"measure":[{"metric":"Real-time factor","definition":"Sim time / wall time during a 60 s run."},{"metric":"Scenario load time","definition":"Launch to first /clock (s)."}],"document":["How to run.","Scenario format.","Assumptions with sources."],"integrate":"Every track uses these scenarios; AG-05 records them for regression."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"c37c65ff-e04e-5bfa-954c-54142f9de733","key":"SIM-02","title":"Rover Simulation Model","track_id":"SIM","subtrack_id":"744d371a-4140-5660-ac5b-e8983baff958","priority":"high","difficulty":"intermediate","estimate_hours":36,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"da95fb4b-23c3-5194-a5d5-b29cf88ae336","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["urdf","xacro","ros2_control"],"spec":{"problem":"Simulation, TF and Nav2 all need a description of our rover: dimensions, joints, sensor mounts and actuators. Mismatched descriptions cause wrong costmap footprints and wrong sensor transforms. Mechanical owns the authoritative geometry; simulation must not invent it silently.","goal":"A spawnable, simulation-facing URDF/Xacro of our rover (body, drivetrain geometry, sensor frames, excavation joints, limits and a simulated drivetrain plugin) visualized in RViz and Gazebo. Every value is tagged as Mechanical-verified or as a labeled temporary approximation to replace when Mechanical delivers data.","why":{"need":"One source of truth for the rover''s geometry.","contribution":"Feeds robot_state_publisher (TF), Gazebo spawning, footprints for PM-01/NV-02 and frames for SF-02.","failureImpact":"Wrong geometry → wrong costmap inflation, misplaced sensor data, unrealistic dynamics.","consumers":["SF-02","PM-01","NV-02","AG-07 mock Controls","SIM-03"]},"background":"URDF describes links (visual, collision, inertial) and joints (type, axis, limits). Xacro adds properties and macros. ros2_control tags declare command/state interfaces that gz_ros2_control or real hardware implement.","prerequisites":[{"concept":"URDF and Xacro","why":"Write the model.","resourceIds":["87f943be-21c8-56cc-bd51-e29e089e9a00","bc7d5e94-c943-56cb-b79c-f9763553e78c"]},{"concept":"TF and robot_state_publisher","why":"Model → TF.","resourceIds":["48d88130-ebb2-50e8-a73f-0c1df1ba777b"]},{"concept":"ros2_control basics","why":"Control interfaces.","resourceIds":["c7bfc3a9-2e35-554f-a3d1-28f612361a6f"]}],"readFirst":["ROS 2 URDF and Xacro tutorials.","Purdue bot.xacro.urdf.","COD v2_bot.urdf.xacro."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_description/urdf/bot.xacro.urdf","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_description/urdf/bot.xacro.urdf","isFolder":false,"summary":"Purdue''s rover description (`dummy_bot`, ≈450 lines): base_link with 50 kg inertial and mesh visual, wheels, sensors, using xacro namespace.","inspect":["`<link name=\"base_link\">` inertial block","mesh references via `$(find lunabot_sim)`","wheel joints and sensor links"],"relevance":"Concrete example of a Lunabotics rover in URDF with mesh visuals.","questions":["Are inertias computed or placeholder (note identical ixx/iyy/izz)?","How are sensors attached and named?","Which joints are continuous vs fixed?"],"adaptation":"Mirror the structure but compute inertias from CAD and parameterize dimensions with xacro properties.","limitations":["Placeholder-looking inertias.","Robot name `dummy_bot` suggests a prototype."],"verifiedOn":"2026-10-25"},{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_description/urdf/v2_bot.urdf.xacro","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_description/urdf/v2_bot.urdf.xacro","isFolder":false,"summary":"COD''s `v2_bot` Xacro (≈700 lines) with `use_sim` argument switching sim/real offsets, sensor plate pitch property and materials.","inspect":["`<xacro:arg name=\"use_sim\">` and `xacro:if/unless` blocks","`sensor_plate_pitch` property","sensor and actuator links"],"relevance":"Shows one description serving both sim and hardware via arguments — what we want.","questions":["What differs between sim and real in the file?","How are excavation actuators modeled?","Where are ros2_control or Gazebo plugin tags?"],"adaptation":"Adopt the `use_sim` pattern for sim-vs-hardware differences.","limitations":["Specific to COD''s mechanical design."],"verifiedOn":"2026-10-25"}],"analyze":["Draw both robots'' link trees.","List every parameter we need from our mechanical team.","Identify how each model exposes control interfaces."],"design":"Package `lunabot_description`: `urdf/rover.urdf.xacro` with properties for all dimensions, macros for wheels and sensors, a `use_sim` arg, `<ros2_control>` block for drive wheels and excavation actuator; `launch/display.launch.py` (RViz + joint_state_publisher_gui) and `launch/spawn.launch.py` (Gazebo).","guidance":{"packageStructure":"lunabot_description/\n  urdf/rover.urdf.xacro\n  urdf/macros/wheel.xacro, sensors.xacro\n  config/ros2_control.yaml\n  launch/display.launch.py, spawn.launch.py\n  meshes/","files":["urdf/rover.urdf.xacro","config/ros2_control.yaml","launch/display.launch.py","launch/spawn.launch.py"],"inputs":[{"name":"/joint_states","type":"sensor_msgs/msg/JointState"}],"outputs":[{"name":"/tf","type":"tf2_msgs/msg/TFMessage"},{"name":"/tf_static","type":"tf2_msgs/msg/TFMessage"},{"name":"/robot_description","type":"std_msgs/msg/String"}],"parameters":[{"name":"use_sim","default":"true","description":"Sim vs hardware differences."},{"name":"wheel_radius / track_width","default":"from CAD","description":"Drivetrain geometry."}],"snippets":[{"title":"Check the URDF","label":"verified","language":"bash","code":"xacro urdf/rover.urdf.xacro > /tmp/rover.urdf && check_urdf /tmp/rover.urdf"},{"title":"Spawn into Gazebo","label":"illustrative","language":"bash","code":"ros2 run ros_gz_sim create -topic robot_description -name rover"}],"expectedBehavior":"RViz shows the full TF tree; Gazebo spawns the rover resting on its wheels; joint limits enforced.","pitfalls":["Zero or tiny inertias → physics explosions.","Visual and collision geometry swapped or mismatched.","Duplicate frames with SF-02 static publishers."]},"testPlan":["check_urdf passes.","TF tree contains expected frames once.","Drop test: rover spawns and settles without jitter.","Joint limit test via command interfaces."],"measure":[{"metric":"Physics stability","definition":"Max base_link velocity while idle after spawn (should be ~0)."}],"document":["Dimension table with sources.","Frame tree diagram."],"integrate":"SF-02 frames, PM-01 footprint, NV-02 navigation, AG-07 mock Controls interface, SIM-03 physics. Replace approximations as Mechanical delivers data."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"a23aa979-4242-51a9-afcc-47b07572c622","key":"SIM-03","title":"Terrain and Sensor Degradation Simulation","track_id":"SIM","subtrack_id":"cab1c7a4-405b-5d3b-a8b9-3227d7497422","priority":"medium","difficulty":"advanced","estimate_hours":32,"status":"available","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":"84ebc8e4-7a5d-5543-ba35-2e0398f7b8f6","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":true,"labels":["mujoco","fault-injection","stress-test"],"spec":{"problem":"An ideal simulator hides the failures that happen on regolith: slip, sinkage, dust, dropped sensor messages. Algorithms must be stress-tested against these before trusting them.","goal":"Reusable stress-test scenarios varying traction, wheel slip, sensor noise, visibility degradation, missing messages and irregular terrain, with measured impacts on navigation and localization and documented simulation limitations.","why":{"need":"Robustness can only be claimed if failures were deliberately tested.","contribution":"Supplies scenarios used by SF-01, SF-04, SF-06, PM-07 and AG-05.","failureImpact":"Algorithms that work only in clean simulation fail at competition.","consumers":["SF-01","SF-04","SF-06","NV-06","AG-05"]},"background":"Physics engines approximate soil with friction coefficients and contact parameters; none model granular regolith faithfully. Fault injection at the ROS level (dropping, delaying, adding noise to messages) is simulator-independent and often more useful.","prerequisites":[{"concept":"Physics engine contact/friction parameters","why":"Traction changes.","resourceIds":["5e5a60bd-ca1a-50f9-913d-ae9170c78345","4cbed166-f914-5a76-a384-58aaf16d4896"]},{"concept":"Sensor noise models","why":"Noise injection.","resourceIds":["4cbed166-f914-5a76-a384-58aaf16d4896"]},{"concept":"ROS message relays","why":"Message-level faults.","resourceIds":["2ba395f6-9e79-5444-a0a8-a4b0a749cf90"]}],"readFirst":["Utah artemis_arena.xml.","Utah mujoco-sim/meshes folder.","MuJoCo overview (contacts)."],"references":[{"repo":"utahrobotics/utah-lunabotics-2027","path":"mujoco-sim/artemis_arena.xml","url":"https://github.com/utahrobotics/utah-lunabotics-2027/blob/main/mujoco-sim/artemis_arena.xml","isFolder":false,"summary":"MuJoCo MJCF model `artemis_arena` with default classes for visual/collision/wheel geoms (wheel solimp 0.8), visual settings, and included lunar surface meshes.","inspect":["`<default class=\"wheel\">` with `solimp`","`<include file=\"meshes/artemis_arena/lunar_surface/…\">`","visual/headlight and fog settings"],"relevance":"A current team using MuJoCo for arena physics, with contact parameters tuned for wheels.","questions":["What does solimp control and why set it for wheels?","How is terrain represented (mesh vs heightfield)?","Could we reproduce traction variation by changing friction per region?"],"adaptation":"Evaluate MuJoCo for traction experiments alongside Gazebo; reuse mesh-handling patterns.","limitations":["MuJoCo ↔ ROS 2 integration is not provided here.","Mesh assets are large."],"verifiedOn":"2026-10-25"},{"repo":"utahrobotics/utah-lunabotics-2027","path":"mujoco-sim/meshes","url":"https://github.com/utahrobotics/utah-lunabotics-2027/tree/main/mujoco-sim/meshes","isFolder":true,"summary":"Mesh assets folder with `artemis_arena`, `core` and `ucf_arena` subfolders.","inspect":["artemis_arena/","ucf_arena/","core/"],"relevance":"Arena terrain meshes for multiple venues.","questions":["What file formats and polygon counts are used?","Could they be converted for Gazebo?"],"adaptation":"Consider reusing meshes (check license) for irregular terrain scenarios.","limitations":["License and scale must be verified before reuse."],"verifiedOn":"2026-10-25"}],"analyze":["List which faults are best injected in physics vs at the ROS layer.","Identify parameters that control traction in Gazebo and in MuJoCo.","Define how to measure impact for each fault."],"design":"Package `lunabot_faults`: a generic `fault_relay` node (drop rate, delay, noise, blackout windows, per-topic config) placed between sensors and consumers; Gazebo scenario variants with region-specific friction; a scenario matrix YAML that AG-05 can run.","guidance":{"packageStructure":"lunabot_faults/\n  lunabot_faults/fault_relay.py\n  config/faults/*.yaml\n  scenarios/stress_matrix.yaml\n  docs/limitations.md","files":["fault_relay.py","config/faults/imu_dropout.yaml","scenarios/stress_matrix.yaml","docs/limitations.md"],"inputs":[{"name":"/imu/data","type":"sensor_msgs/msg/Imu","note":"proposed"},{"name":"/lidar/points","type":"sensor_msgs/msg/PointCloud2","note":"proposed"},{"name":"/wheel/odometry","type":"nav_msgs/msg/Odometry","note":"proposed"}],"outputs":[{"name":"/faulted/<topic>","type":"same as input","note":"relay output (proposed)"}],"parameters":[{"name":"drop_probability","default":"0.0","description":"Per-message drop."},{"name":"delay_ms","default":"0","description":"Added latency."},{"name":"noise_sigma","default":"0.0","description":"Gaussian noise."},{"name":"blackouts","default":"[]","description":"Time windows with no output."}],"snippets":[{"title":"Run the relay for the IMU","label":"illustrative","language":"bash","code":"ros2 run lunabot_faults fault_relay --ros-args -p topic:=/imu/data -p out:=/faulted/imu/data -p drop_probability:=0.2"}],"expectedBehavior":"Each scenario reproducibly degrades the target subsystem; impacts are measured and compared to a clean baseline.","pitfalls":["Changing message timestamps when delaying (keep header stamps).","Non-seeded randomness.","Over-claiming realism of friction-based slip."]},"testPlan":["Each fault scenario run three times with fixed seed.","Baseline vs fault comparison for ATE and goal success."],"measure":[{"metric":"ATE increase","definition":"ATE under fault − baseline ATE."},{"metric":"Goal success under fault","definition":"Fraction of NV-02 goals reached."}],"document":["Scenario catalogue.","Limitations."],"integrate":"AG-05 runs the stress matrix in regression."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"3edf045c-1999-5599-9447-b50de03cf966","key":"SF-05","title":"Radar–LiDAR Fusion Feasibility","track_id":"SF","subtrack_id":"30da7ed0-cca5-5bfb-b6e0-ec85619581c3","priority":"medium","difficulty":"expert","estimate_hours":32,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["radar","research","advanced"],"spec":{"problem":"Lunar dust can degrade LiDAR and cameras. Radar sees through dust but is sparse and noisy. We don''t know what our proposed radar can measure, or whether fusing it would help navigation.","goal":"A feasibility study: what the proposed radar measures (range, angular resolution, field of view, update rate, velocity), a capability comparison with LiDAR, whether object-level fusion is feasible, a simulated fusion prototype built on explicitly documented sensor assumptions, and a hardware recommendation — without writing hardware drivers.","why":{"need":"Decide early whether radar is worth mass, power and integration effort.","contribution":"Informs PM-09 and the sensor ADR; gives Electrical concrete requirements if adopted.","failureImpact":"Buying a sensor that adds nothing, or ignoring one that would rescue navigation in dust.","consumers":["PM-09 radar-assisted detection","PM-07 dust robustness","ADR: Which sensors?","Electrical (sensor requirements)"]},"background":"Automotive-style mmWave radars output sparse detections (range, azimuth, sometimes elevation and Doppler velocity) at 10–20 Hz. Fusion with LiDAR is usually object-level or occupancy-level, not raw-point-level, because radar returns are sparse and multipath-prone near walls and the ground.","prerequisites":[{"concept":"Sensor modalities and their failure modes","why":"Compare LiDAR, camera and radar.","resourceIds":["03399223-0ba3-5288-8423-163bf1e33889"]},{"concept":"Bayesian occupancy fusion","why":"Combine evidence from different sensors.","resourceIds":["28ba189d-b72b-5610-be2c-70d7db674321"]},{"concept":"Coordinate frames","why":"Put detections in a common frame.","resourceIds":["88851e00-b67e-53b2-aceb-e2867451336e"]}],"readFirst":["Check simulator radar support.","Available Gazebo sensors.","Bayesian fusion background."],"references":[],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Desk study + Python prototype: `research/radar/` notebook with a documented radar model (assumptions table with sources or ''assumed''), synthetic detections generated from SIM-03 scenes, and an occupancy-grid fusion experiment comparing LiDAR-only vs LiDAR+radar under simulated dust.","guidance":{"packageStructure":"research/radar/\n  assumptions.md          # every spec cited or marked ''assumed''\n  radar_model.py          # synthetic detections from ground-truth obstacles\n  fusion_experiment.ipynb\n  recommendation.md","files":["assumptions.md","radar_model.py","fusion_experiment.ipynb","recommendation.md"],"inputs":[{"name":"/radar/detections","type":"TBD — proposed sensor_msgs/PointCloud2 with range/azimuth/doppler fields","note":"synthetic"},{"name":"/lidar/points","type":"sensor_msgs/msg/PointCloud2","note":"proposed"}],"outputs":[{"name":"research/radar/recommendation.md","type":"file"}],"parameters":[{"name":"range_resolution_m","default":"from datasheet or assumed","description":"Model input."},{"name":"azimuth_resolution_deg","default":"from datasheet or assumed","description":"Model input."},{"name":"false_alarm_rate","default":"assumed","description":"Clutter model."}],"snippets":[{"title":"Synthetic radar detection (sketch)","label":"illustrative","language":"python","code":"def detect(obstacles, pose, cfg, rng):\n    out = []\n    for ob in obstacles:\n        r, az = polar(ob, pose)\n        if r < cfg.max_range and abs(az) < cfg.fov / 2 and rng.random() < cfg.p_detect:\n            out.append((r + rng.normal(0, cfg.range_sigma), az + rng.normal(0, cfg.az_sigma)))\n    return out + clutter(cfg, rng)"}],"expectedBehavior":"A recommendation stating what radar would add, under which assumptions, and what evidence would change the decision.","pitfalls":["Quoting vendor specs without sources.","Treating synthetic dust as realistic.","Writing driver code (Electrical/Controls scope)."]},"testPlan":["Same dust scenarios with and without radar evidence.","Sensitivity sweep over assumed radar parameters."],"measure":[{"metric":"Obstacle coverage in dust","definition":"Known obstacles marked occupied / known obstacles, per configuration."}],"document":["Assumptions table.","Recommendation and decision triggers."],"integrate":"PM-09 builds on a positive recommendation; Electrical receives requirements via the external-dependency tracker.","researchNeeded":["No verified radar reference implementation in the seeded repositories.","Radar simulation support must be confirmed in the chosen simulator."]},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"566176c5-5c46-5f15-bd4a-4ada34f50988","key":"SF-06","title":"Sensor Fusion Benchmark Suite","track_id":"SF","subtrack_id":"be5e7a55-130a-53e6-881b-6374db4ad2a7","priority":"high","difficulty":"intermediate","estimate_hours":28,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["benchmark","testing","advanced"],"spec":{"problem":"Localization changes are judged by eye. Without reproducible stress tests, a tuning change that helps one scenario can silently break another.","goal":"A reproducible benchmark suite that replays fixed scenarios with controlled measurement noise, wheel slip, IMU drift, delayed observations, missing sensor data and sensor disagreement, and reports ATE/RPE, drift and estimator health for any localization configuration.","why":{"need":"Make localization progress measurable.","contribution":"Every SF change is evaluated against the same suite; slip estimation (formerly part of the Controls stall task) lives here.","failureImpact":"Regressions reach integration unnoticed.","consumers":["SF-01","SF-03","SF-04","SF-08","AG-05"]},"background":"Benchmarks need fixed inputs (bags or seeded sim runs), fault injection applied the same way every time, and metrics with definitions. evo computes ATE/RPE from TUM-format trajectories exported from bags.","prerequisites":[{"concept":"Trajectory metrics","why":"ATE vs RPE.","resourceIds":["788a889e-c6bf-5d2f-af0e-d66aee74b4be"]},{"concept":"Bag replay with sim time","why":"Deterministic inputs.","resourceIds":["73298a07-2ed6-5224-99d5-c009df68ca5e"]},{"concept":"Kalman filter behavior under noise","why":"Interpreting results.","resourceIds":["0341f934-19a2-5f77-afab-a2d085e0cf10"]}],"readFirst":["Trajectory metrics.","Recording and replay.","Reading bags in Python."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_config/params/robot_localization/ukf_params.yaml","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_config/params/robot_localization/ukf_params.yaml","isFolder":false,"summary":"COD''s UKF configuration (single /lio_odom input, two_d_mode, rejection thresholds).","inspect":["`odom0_pose_rejection_threshold` / `odom0_twist_rejection_threshold`","`process_noise_covariance`"],"relevance":"A real configuration to benchmark against ours under the same stress cases.","questions":["How would the rejection thresholds behave under delayed or disagreeing sensors?"],"adaptation":"Include a COD-style configuration as a baseline row in the suite.","limitations":["Tuned for COD''s LIO input."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"`lunabot_localization/benchmark/`: `faults.py` (relay that adds noise, scales wheel velocities for slip, adds IMU bias drift, delays or drops messages, offsets one sensor for disagreement), `scenarios.yaml` (bag + fault parameters), `run_suite.py` (replays each scenario through the configuration under test, exports TUM trajectories, runs evo, writes CSV).","guidance":{"packageStructure":"lunabot_localization/benchmark/\n  faults.py\n  scenarios.yaml\n  run_suite.py\n  report_template.md","files":["faults.py","scenarios.yaml","run_suite.py"],"inputs":[{"name":"/wheel/odometry","type":"nav_msgs/msg/Odometry","note":"proposed"},{"name":"/imu/data","type":"sensor_msgs/msg/Imu","note":"proposed"},{"name":"/ground_truth/odom","type":"nav_msgs/msg/Odometry","note":"evaluation only"}],"outputs":[{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"},{"name":"results/localization/*.csv","type":"file"}],"parameters":[{"name":"slip_ratio","default":"0.0–0.4","description":"Scale on one wheel side."},{"name":"imu_bias_drift","default":"rad/s per minute","description":"Gyro drift."},{"name":"delay_ms","default":"0–300","description":"Observation delay."},{"name":"drop_windows","default":"[]","description":"Missing-data windows."}],"snippets":[{"title":"Run the suite","label":"illustrative","language":"bash","code":"python3 benchmark/run_suite.py --config config/ekf.yaml --scenarios benchmark/scenarios.yaml --out results/localization/"},{"title":"Per-scenario ATE","label":"adapt","language":"bash","code":"evo_ape tum gt.tum est.tum --align --save_results ate.zip"}],"expectedBehavior":"Identical inputs give identical metrics; each fault type shows a measurable, explainable effect.","pitfalls":["Changing message header stamps when delaying (shift arrival, not stamp, unless testing stamp errors).","Unseeded randomness.","Using ground truth inside the estimator."]},"testPlan":["Determinism: run twice, identical metrics.","Each fault alone, then combined."],"measure":[{"metric":"ATE / RPE","definition":"evo on aligned trajectories."},{"metric":"Final drift","definition":"End-position error."},{"metric":"Health transitions","definition":"SF-04 status changes per scenario."}],"document":["Scenario catalogue.","Baseline results and how to add a scenario."],"integrate":"All SF tasks report against it; AG-05 runs a subset."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"5a0e5477-9883-58c7-877a-ac25ced72821","key":"SF-07","title":"Localization Confidence Dashboard","track_id":"SF","subtrack_id":"95e99514-0a1b-50e3-aef0-c4cae02a7367","priority":"medium","difficulty":"beginner","estimate_hours":16,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["visualization","good-first-task","advanced"],"spec":{"problem":"Localization health is buried in numbers; members can''t see at a glance whether the estimate is trustworthy or drifting.","goal":"Publish and visualize pose estimates, covariance, per-sensor freshness, localization status and drift against simulation ground truth, as a reusable panel set for AG-06 and for debugging.","why":{"need":"Fast diagnosis during simulation runs.","contribution":"Supplies AG-06''s localization panels.","failureImpact":"Localization problems are misdiagnosed as navigation bugs.","consumers":["AG-06","SF-04","AG-08"]},"background":"Covariance can be visualized as an ellipse (2D position block) and a scalar (trace). Freshness is time since last message per input. Drift needs ground truth, which exists only in simulation — label it clearly.","prerequisites":[{"concept":"Covariance ellipses","why":"Visualizing uncertainty.","resourceIds":["28ba189d-b72b-5610-be2c-70d7db674321"]},{"concept":"Foxglove / RViz panels","why":"Building the view.","resourceIds":["bea6e129-1b71-593b-8559-62ca7fa8d3a9","bda930c4-bd54-50f0-b578-b4143a8ea3f2"]}],"readFirst":["Dashboard.","Markers.","RViz visualization basics."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_gui/src/ros_interface.py","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_gui/src/ros_interface.py","isFolder":false,"summary":"COD GUI ROS layer subscribing to /odometry/filtered among other telemetry.","inspect":["`RobotInterface._create_subscriptions()`","`_odom_callback`"],"relevance":"How another team surfaced localization in an operator view.","questions":["What localization information does it show beyond pose?"],"adaptation":"Add covariance, freshness and status — not just pose.","limitations":["No uncertainty display."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"`localization_viz` node publishing a covariance ellipse Marker, a drift-vs-ground-truth topic (sim only), and per-sensor freshness as diagnostics; a Foxglove layout `dashboards/localization.json`.","guidance":{"packageStructure":"lunabot_localization/\n  lunabot_localization/localization_viz.py\n  dashboards/localization.json","files":["localization_viz.py","dashboards/localization.json"],"inputs":[{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"},{"name":"/localization/health","type":"diagnostic_msgs/msg/DiagnosticStatus","note":"proposed; may become a custom msg"},{"name":"/ground_truth/odom","type":"nav_msgs/msg/Odometry","note":"sim only"}],"outputs":[{"name":"/localization/covariance_marker","type":"visualization_msgs/msg/Marker","note":"proposed"},{"name":"/localization/drift","type":"std_msgs/msg/Float64","note":"sim only, proposed"}],"parameters":[{"name":"ellipse_sigma","default":"2.0","description":"Ellipse scale in standard deviations."}],"snippets":[{"title":"2σ ellipse from covariance","label":"illustrative","language":"python","code":"vals, vecs = np.linalg.eigh(cov[:2, :2])\naxes = 2 * np.sqrt(np.maximum(vals, 0))\nyaw = math.atan2(vecs[1, 1], vecs[0, 1])"}],"expectedBehavior":"Ellipse grows when sensors drop out and shrinks when they recover; drift is visible during slip scenarios.","pitfalls":["Showing ground truth on hardware (doesn''t exist).","Ellipse from the wrong covariance block or frame."]},"testPlan":["Dropout scenario: ellipse grows, status changes, freshness shows the stale input."],"measure":[{"metric":"Panel latency","definition":"Message stamp → displayed (ms, estimated)."}],"document":["How to read each panel."],"integrate":"AG-06 embeds the layout."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"76b564b8-3f3b-52de-83f6-b5a68a386e3b","key":"SF-08","title":"Adaptive Sensor Covariance Estimation","track_id":"SF","subtrack_id":"e39eb280-b0b3-5e67-bee3-562e2f2c614d","priority":"medium","difficulty":"advanced","estimate_hours":32,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["ekf","research","advanced"],"spec":{"problem":"Fixed covariances make the filter over-trust wheel odometry during slip and under-trust it on firm ground.","goal":"A node that adapts wheel-odometry covariance online using slip indicators (SF-06) and innovation statistics, evaluated against fixed covariance on the SF-06 suite.","why":{"need":"Better localization during slip-heavy excavation.","contribution":"Improves SF-01 where it is weakest.","failureImpact":"Filter divergence or overconfidence.","consumers":["SF-01","SF-04"]},"background":"Adaptive Kalman filtering scales measurement noise by monitored residuals (innovation) or by external indicators such as wheel/IMU velocity disagreement. The normalized innovation squared (NIS) should follow a chi-square distribution when the filter is consistent.","prerequisites":[{"concept":"Kalman innovation and NIS","why":"Consistency checks.","resourceIds":["28ba189d-b72b-5610-be2c-70d7db674321","4fa0b9fa-e675-5035-8359-91dbac3380f0"]},{"concept":"robot_localization input covariance","why":"Where the adaptation is applied.","resourceIds":["24908517-b857-5893-88e8-9bff94c9bcfb"]}],"readFirst":["Adaptive filtering chapters.","Input covariance handling.","Kalman filter intuition."],"references":[],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Relay node between /wheel/odometry and the filter that rewrites twist covariance from a slip indicator and a running innovation estimate, with bounds.","guidance":{"packageStructure":"lunabot_localization/\n  lunabot_localization/adaptive_covariance.py\n  config/adaptive_covariance.yaml","files":["adaptive_covariance.py","config/adaptive_covariance.yaml"],"inputs":[{"name":"/wheel/odometry","type":"nav_msgs/msg/Odometry","note":"proposed"},{"name":"/imu/data","type":"sensor_msgs/msg/Imu","note":"proposed"},{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"}],"outputs":[{"name":"/wheel/odometry_adapted","type":"nav_msgs/msg/Odometry","note":"proposed"}],"parameters":[{"name":"min_scale / max_scale","default":"1 / 100","description":"Covariance scaling bounds."},{"name":"slip_gain","default":"tuned","description":"Scale per unit slip ratio."}],"snippets":[{"title":"Covariance scaling","label":"illustrative","language":"python","code":"scale = np.clip(1 + cfg.slip_gain * slip_ratio, cfg.min_scale, cfg.max_scale)\nmsg.twist.covariance[0] = base_vx_var * scale"}],"expectedBehavior":"Lower ATE than fixed covariance in slip scenarios, no worse elsewhere.","pitfalls":["Feedback loop: using the filter output that already contains wheel odometry as the slip reference.","Covariance going non-positive."]},"testPlan":["SF-06 slip scenarios with identical seeds."],"measure":[{"metric":"ATE","definition":"vs fixed covariance."},{"metric":"NIS consistency","definition":"Fraction of NIS within chi-square bounds."}],"document":["Scaling law and bounds.","Results including failures."],"integrate":"Optional input stage for SF-01."},"legacy_keys":["SF-06"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"97e7e67b-a11b-5c72-8d47-7c2817b698a3","key":"PM-05","title":"Lunar Rock & Obstacle Detection","track_id":"PM","subtrack_id":"f5e86e77-ed75-51cd-b428-f68ef82eea43","priority":"medium","difficulty":"expert","estimate_hours":48,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["vision","obstacles","advanced"],"spec":{"problem":"Geometry-only costmaps can miss small rocks near LiDAR resolution and confuse shadows; we need a measured comparison of classical and learned detection.","goal":"Evaluate a classical geometry-based detector and a computer-vision baseline on simulated rock scenes (and LuSNAR if PM-04 finds labels), measure accuracy and inference time, and publish obstacle detections in the map frame.","why":{"need":"Detect hazards geometry alone misses.","contribution":"Feeds PM-08 association and the costmap.","failureImpact":"False positives block paths; false negatives damage wheels.","consumers":["PM-08","PM-01","NV-08"]},"background":"Classical: cluster points above a ground plane (RANSAC) by height/size. Learned: a small detector on camera images. Lunar lighting (hard shadows, low sun) is the main challenge for vision; report metrics only where labels exist.","prerequisites":[{"concept":"Point cloud clustering","why":"Classical baseline.","resourceIds":["03399223-0ba3-5288-8423-163bf1e33889","9aeabeef-00c2-532b-99c2-f5ef3f8952a5"]},{"concept":"Detection metrics","why":"Precision/recall/IoU.","resourceIds":["a5360873-884d-5142-86a8-5960a0106b69"]}],"readFirst":["Segmentation and clustering.","Candidate labeled data (pending PM-04).","Open3D overview."],"references":[],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"`lunabot_perception/obstacles/`: `geometric_detector.py` (ground removal + Euclidean clustering), `vision_detector.py` (baseline model inference), `evaluate.py` on labeled sim renders; ROS node publishing detections as a MarkerArray and a proposed Obstacle message.","guidance":{"packageStructure":"lunabot_perception/obstacles/\n  geometric_detector.py\n  vision_detector.py\n  evaluate.py\n  obstacle_node.py","files":["geometric_detector.py","vision_detector.py","evaluate.py","obstacle_node.py"],"inputs":[{"name":"/perception/points_filtered","type":"sensor_msgs/msg/PointCloud2"},{"name":"/camera/image_raw","type":"sensor_msgs/msg/Image","note":"proposed"},{"name":"/camera/camera_info","type":"sensor_msgs/msg/CameraInfo","note":"proposed"}],"outputs":[{"name":"/perception/obstacles","type":"lunabot_interfaces/msg/ObstacleArray (proposed)"}],"parameters":[{"name":"min_obstacle_height_m","default":"agreed with NV","description":"Smallest hazard."},{"name":"score_threshold","default":"tuned","description":"Vision detector threshold."}],"snippets":[{"title":"Ground removal with Open3D","label":"adapt","language":"python","code":"plane, inliers = pcd.segment_plane(distance_threshold=0.03, ransac_n=3, num_iterations=200)\nobstacles = pcd.select_by_index(inliers, invert=True)\nlabels = np.array(obstacles.cluster_dbscan(eps=0.1, min_points=10))"}],"expectedBehavior":"Both detectors report precision/recall per size class on labeled data, with latency on target hardware.","pitfalls":["Reporting metrics without ground-truth labels.","Evaluating only on easy lighting."]},"testPlan":["Held-out labeled scenes; runtime benchmark."],"measure":[{"metric":"Precision / recall","definition":"Per size class on labeled data only."},{"metric":"Latency","definition":"ms per frame on target compute."}],"document":["Label source.","Comparison and recommendation."],"integrate":"PM-08 associates these detections with others.","researchNeeded":["Labeled rock data availability unverified until PM-04 completes."]},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"094cc510-dcd7-5c6f-8dca-311ca9451998","key":"PM-06","title":"Terrain Slope & Roughness Estimation","track_id":"PM","subtrack_id":"a8c47dde-d15b-521a-a908-efab1645dca0","priority":"medium","difficulty":"advanced","estimate_hours":36,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["terrain","elevation","advanced"],"spec":{"problem":"PM-01''s per-frame grid forgets terrain outside the sensor view and has no uncertainty; navigation needs persistent slope and roughness.","goal":"A persistent elevation map with uncertainty, local surface gradients (slope), roughness, unsafe-terrain classification and traversability information usable by NV-04.","why":{"need":"Terrain-aware long-horizon planning.","contribution":"Inputs for NV-04 costs and the PM-01 costmap.","failureImpact":"Stale or smeared terrain from drift; slopes missed.","consumers":["NV-04","PM-01"]},"background":"Robot-centric elevation mapping fuses height measurements with variance and propagates pose uncertainty; grid_map provides layered maps and filters for slope (normals) and roughness (residuals).","prerequisites":[{"concept":"Grid maps","why":"Layered representation.","resourceIds":["ca85ca36-be1a-5017-a601-05df5375fb6e"]},{"concept":"Elevation mapping","why":"Uncertainty fusion.","resourceIds":["9de011d6-3253-58bc-bc56-8dcb8ce20cda"]}],"readFirst":["Elevation mapping.","Grid map filters.","Slope baseline."],"references":[{"repo":"GOFIRST-Robotics/Lunabotics","path":"src/alexblox/alexblox/costmapGenerator.py","url":"https://github.com/GOFIRST-Robotics/Lunabotics/blob/main/src/alexblox/alexblox/costmapGenerator.py","isFolder":false,"summary":"Gradient-magnitude slope from an averaged height grid.","inspect":["`CostmapGenerator.pointCloudCallback` — `np.gradient` and `lethal_slope` threshold"],"relevance":"The single-frame baseline this task makes persistent and uncertainty-aware.","questions":["What happens at the boundary of observed cells?"],"adaptation":"Compute slope from a fused elevation layer with variance instead of one frame.","limitations":["No persistence or roughness."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Evaluate ANYbotics elevation_mapping / grid_map for our ROS 2 distro; if unsuitable, a numpy rolling map in odom with per-cell variance. Layers: elevation, variance, slope_deg, roughness, class.","guidance":{"packageStructure":"lunabot_perception/terrain/\n  elevation_map_node.py\n  terrain_layers.py\n  config/terrain.yaml","files":["elevation_map_node.py","terrain_layers.py","config/terrain.yaml"],"inputs":[{"name":"/perception/points_filtered","type":"sensor_msgs/msg/PointCloud2"},{"name":"/tf","type":"tf2_msgs/msg/TFMessage"}],"outputs":[{"name":"/perception/elevation","type":"grid_map_msgs/msg/GridMap or nav_msgs/msg/OccupancyGrid layers","note":"proposed"}],"parameters":[{"name":"resolution_m","default":"0.05–0.10","description":"Cell size."},{"name":"max_slope_deg","default":"from Mechanical capability","description":"Unsafe threshold."},{"name":"roughness_window","default":"3×3","description":"Neighborhood."}],"snippets":[{"title":"Roughness as plane-fit residual","label":"illustrative","language":"python","code":"A = np.c_[xs, ys, np.ones_like(xs)]\ncoef, res, *_ = np.linalg.lstsq(A, zs, rcond=None)\nroughness = np.sqrt(res[0] / len(zs)) if res.size else 0.0"}],"expectedBehavior":"Terrain persists outside the current view; slope matches sim ground truth within tolerance.","pitfalls":["Library ROS 2 support may be incomplete — verify first.","Slope computed in a tilted frame."]},"testPlan":["SIM-01 loop with revisits; SIM-03 slopes."],"measure":[{"metric":"Height error","definition":"RMS vs simulator terrain."},{"metric":"Slope error","definition":"deg vs known slopes."}],"document":["Layer definitions and thresholds."],"integrate":"NV-04 consumes traversability layers."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"31122c6b-661e-5e87-8f88-aadb4ed34024","key":"PM-07","title":"Perception Robustness Under Dust","track_id":"PM","subtrack_id":"02f6eb7f-9be4-537f-bb66-e762ee65e92b","priority":"medium","difficulty":"advanced","estimate_hours":28,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["robustness","benchmark","advanced"],"spec":{"problem":"We don''t know how perception degrades with dust, low sun angle and shadows, or which sensor to trust when it does.","goal":"Simulated visibility degradation, measured camera-based performance changes, comparison with other modalities where data exists, quantified detection changes and documented fallback options.","why":{"need":"Know our limits before competition.","contribution":"Evidence for SF-05/PM-09 and fallback design.","failureImpact":"Surprises in the arena.","consumers":["SF-05","PM-09","PM-05","NV-06"]},"background":"Degradation can be simulated with image noise, contrast loss, particle overlays, LiDAR dropout and reduced range; real dust is hard to model, so state realism limits explicitly.","prerequisites":[{"concept":"Sensor simulation","why":"Noise models.","resourceIds":["4cbed166-f914-5a76-a384-58aaf16d4896"]},{"concept":"Detection metrics","why":"Fair comparison.","resourceIds":["a5360873-884d-5142-86a8-5960a0106b69"]}],"readFirst":["Sensor noise.","Image processing."],"references":[],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Degradation filters applied via the SIM-03 fault relay; a scenario matrix (degradation type × level × seed) evaluated with PM-01 and PM-05 metrics.","guidance":{"packageStructure":"lunabot_perception/robustness/\n  degrade.py\n  scenarios.yaml\n  evaluate_robustness.py","files":["degrade.py","scenarios.yaml","evaluate_robustness.py"],"inputs":[{"name":"/camera/image_raw","type":"sensor_msgs/msg/Image","note":"proposed"},{"name":"/lidar/points","type":"sensor_msgs/msg/PointCloud2","note":"proposed"}],"outputs":[{"name":"results/robustness/*.csv","type":"file"}],"parameters":[{"name":"contrast_loss","default":"0–0.8","description":"Image degradation."},{"name":"lidar_drop_prob","default":"0–0.5","description":"Point dropout."},{"name":"max_range_scale","default":"0.3–1.0","description":"Range reduction."}],"snippets":[{"title":"Contrast loss + noise","label":"illustrative","language":"python","code":"img = (img.astype(np.float32) - img.mean()) * (1 - loss) + img.mean()\nimg += rng.normal(0, sigma, img.shape)"}],"expectedBehavior":"Curves of detection quality vs degradation level per modality.","pitfalls":["Over-claiming dust realism.","Different seeds between compared runs."]},"testPlan":["Each level × 3 seeds."],"measure":[{"metric":"Obstacle coverage","definition":"Hazards detected / hazards."},{"metric":"False positives","definition":"Phantom detections per run."}],"document":["Curves and realism limits.","Fallback recommendations."],"integrate":"Informs NV-06 fallbacks and SF-05."},"legacy_keys":["PM-08"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"1f6b83bd-3a06-5e37-b97a-5c5f1f8bf4d1","key":"PM-08","title":"Multi-Sensor Obstacle Association","track_id":"PM","subtrack_id":"f5e86e77-ed75-51cd-b428-f68ef82eea43","priority":"medium","difficulty":"advanced","estimate_hours":36,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["fusion","tracking","advanced"],"spec":{"problem":"LiDAR, camera (and possibly radar) detections of the same obstacle must be associated; otherwise obstacles duplicate, flicker or contradict each other.","goal":"A common obstacle representation, observations transformed into a consistent frame, association across modalities, handling of contradictory measurements, and published fused obstacle tracks.","why":{"need":"A consistent obstacle picture for navigation.","contribution":"Clean inputs for the costmap and NV-08.","failureImpact":"Duplicate or flickering obstacles cause path oscillation.","consumers":["PM-01","NV-08","AG-06"]},"background":"Gating (Mahalanobis distance) and assignment (Hungarian algorithm) associate detections to tracks; tracks maintain existence probability so contradictory evidence lowers confidence instead of flipping state.","prerequisites":[{"concept":"Data association","why":"Gating and assignment.","resourceIds":["28ba189d-b72b-5610-be2c-70d7db674321"]},{"concept":"TF","why":"Common frame.","resourceIds":["b0f6e245-ddd5-52cc-a7cf-7b15535d06d8","cb661d13-252c-5af0-920b-8849b6671888"]}],"readFirst":["Tracking background.","Frames."],"references":[],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"`obstacle_fusion` node: inputs PM-05 detections (+ PM-09 radar), transform to odom at message stamp, gate + assign, track with existence probability, publish ObstacleArray and markers. Focus is data association — no sensor drivers.","guidance":{"packageStructure":"lunabot_perception/fusion/\n  obstacle_fusion.py\n  association.py\n  test/test_association.py","files":["obstacle_fusion.py","association.py","test/test_association.py"],"inputs":[{"name":"/perception/obstacles","type":"lunabot_interfaces/msg/ObstacleArray (proposed)"},{"name":"/tf","type":"tf2_msgs/msg/TFMessage"}],"outputs":[{"name":"/perception/obstacle_tracks","type":"lunabot_interfaces/msg/ObstacleArray (proposed)"}],"parameters":[{"name":"gate_chi2","default":"9.21","description":"99% gate for 2D."},{"name":"p_birth / p_death","default":"tuned","description":"Track existence."}],"snippets":[{"title":"Hungarian assignment","label":"illustrative","language":"python","code":"from scipy.optimize import linear_sum_assignment\nrows, cols = linear_sum_assignment(cost)\npairs = [(r, c) for r, c in zip(rows, cols) if cost[r, c] < gate]"}],"expectedBehavior":"One track per real obstacle; confidence reflects agreement between modalities.","pitfalls":["Time misalignment between sensors.","Associating in the sensor frame."]},"testPlan":["Sim scenes with known obstacle sets and two modalities."],"measure":[{"metric":"Duplicate rate","definition":"Extra tracks per true obstacle."},{"metric":"Miss rate","definition":"True obstacles without a track."}],"document":["Message definition.","Association parameters."],"integrate":"Feeds the costmap and AG-06."},"legacy_keys":["PM-07"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"83662f45-9f4c-58a7-a326-95399a8568ba","key":"PM-09","title":"Radar-Assisted Obstacle Detection","track_id":"PM","subtrack_id":"ce0f03a5-4b26-5922-9b89-a3e532225ea2","priority":"low","difficulty":"expert","estimate_hours":40,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["radar","advanced"],"spec":{"problem":"If radar is adopted (SF-05), its detections must become obstacle information usable by the costmap, especially when LiDAR and cameras degrade in dust.","goal":"A radar obstacle layer prototype (from simulated or recorded detections) that marks obstacles in dust where LiDAR fails, evaluated against LiDAR-only, with false-positive behavior documented.","why":{"need":"Obstacle avoidance robust to dust.","contribution":"An extra evidence source for PM-08 and the costmap.","failureImpact":"Ghost obstacles from multipath block navigation.","consumers":["PM-08","NV-02"]},"background":"Radar detections need clustering, persistence filtering and ground/wall clutter rejection before marking obstacles. This is perception work on detections; driver integration is Electrical/Controls.","prerequisites":[{"concept":"Occupancy grids","why":"Layer output.","resourceIds":["a90c1792-89cb-532d-a2b3-d146f8d8141b"]},{"concept":"Clustering","why":"Detection grouping.","resourceIds":["03399223-0ba3-5288-8423-163bf1e33889"]}],"readFirst":["Costmap layers.","Clustering."],"references":[],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Costmap layer (or occupancy input to PM-01) fed by clustered, persistence-filtered radar detections from the SF-05 model or recorded data.","guidance":{"packageStructure":"lunabot_perception/radar/\n  radar_obstacle_layer.py\n  clutter_filter.py","files":["radar_obstacle_layer.py","clutter_filter.py"],"inputs":[{"name":"/radar/detections","type":"TBD (SF-05)"}],"outputs":[{"name":"/perception/radar_occupancy","type":"nav_msgs/msg/OccupancyGrid","note":"proposed"}],"parameters":[{"name":"persistence_frames","default":"3","description":"Detections required before marking."},{"name":"wall_margin_m","default":"0.3","description":"Ignore returns near arena walls."}],"snippets":[{"title":"Persistence filter","label":"illustrative","language":"python","code":"hits[cell] = hits.get(cell, 0) + 1\noccupied = {c for c, n in hits.items() if n >= cfg.persistence_frames}"}],"expectedBehavior":"Obstacles marked in dust where LiDAR-only misses them, with bounded phantom detections.","pitfalls":["Multipath reflections off arena walls.","Assuming radar specs without SF-05 evidence."]},"testPlan":["PM-07 dust scenario matrix."],"measure":[{"metric":"Detection recall in dust","definition":"Obstacles marked / obstacles."},{"metric":"False positives","definition":"Phantom cells per run."}],"document":["Layer behavior and limits."],"integrate":"PM-08 and the costmap consume it.","researchNeeded":["Depends on SF-05 sensor selection; no reference implementation verified."]},"legacy_keys":["SF-07"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"e8bd3d32-3ba4-5ab6-9096-41e34c32cb1f","key":"NV-04","title":"Terrain-Aware Global Planning","track_id":"NV","subtrack_id":"23bf0e91-23ec-5166-9f8e-401ec23ef38a","priority":"medium","difficulty":"advanced","estimate_hours":32,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["planning","terrain","advanced"],"spec":{"problem":"Planners weight distance heavily; on regolith, slope, roughness, obstacle density and uncertainty matter more for time and safety.","goal":"A global planning cost that incorporates slope, roughness, obstacle density and map uncertainty, with weights fitted from simulated traversal data and validated against distance-only planning.","why":{"need":"Faster, safer cycles.","contribution":"Better routes for NV-02 and mission timing for AG-09.","failureImpact":"Routes over slip-prone or uncertain terrain.","consumers":["NV-02","AG-09"]},"background":"Edge cost = distance × f(slope, roughness, density) + λ·uncertainty. Parameters can be fitted from traversal time and slip observed in SIM-03 scenarios.","prerequisites":[{"concept":"Planning costs","why":"Weighting.","resourceIds":["3c89f409-b976-5345-8cbb-3b1b80a8cfd8","9e89b990-e8fb-533a-9bea-e5e36149cdca"]},{"concept":"Terrain layers","why":"Inputs from PM-06.","resourceIds":["ca85ca36-be1a-5017-a601-05df5375fb6e"]}],"readFirst":["Cost functions.","Terrain layers.","S-Theta* costs."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_nav/src/stheta_star.cpp","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_nav/src/stheta_star.cpp","isFolder":false,"summary":"S-Theta* with costmap-weighted traversal costs.","inspect":["`SThetaStar::getTraversalCost`","`SThetaStar::calculatePathCost`"],"relevance":"Where a terrain term plugs into an any-angle planner.","questions":["How is costmap cost scaled relative to distance?"],"adaptation":"Replace the single cost with a weighted terrain cost from PM-06 layers.","limitations":["Single-layer cost."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Extend NV-01''s traversal cost with PM-06 layers; fit weights from SIM-03 traversal logs; compare on identical maps.","guidance":{"packageStructure":"lunabot_planning/\n  lunabot_planning/terrain_cost.py\n  scripts/fit_weights.py","files":["terrain_cost.py","scripts/fit_weights.py"],"inputs":[{"name":"/perception/elevation","type":"terrain layers (PM-06)"},{"name":"/perception/traversability","type":"nav_msgs/msg/OccupancyGrid","note":"proposed"}],"outputs":[{"name":"/plan","type":"nav_msgs/msg/Path"}],"parameters":[{"name":"w_slope / w_rough / w_density / w_uncertainty","default":"fitted","description":"Cost weights."}],"snippets":[{"title":"Weighted edge cost","label":"illustrative","language":"python","code":"cost = dist * (1 + w_slope * slope + w_rough * rough + w_density * density) + w_unc * variance"}],"expectedBehavior":"Lower traversal time and fewer slip events than distance-only, no extra collisions.","pitfalls":["Fitting to simulation artifacts.","Inadmissible heuristics after adding costs."]},"testPlan":["Paired runs on identical scenarios."],"measure":[{"metric":"Traversal time","definition":"Start→goal (s)."},{"metric":"Slip events","definition":"SF-06 slip detections per run."}],"document":["Cost model and fitted weights."],"integrate":"NV-02 uses the planner; AG-09 uses travel-time estimates."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"60c6c8ef-b084-5ca3-b80c-5526db1c3382","key":"NV-05","title":"Local Obstacle Avoidance","track_id":"NV","subtrack_id":"b79d6a68-d96d-5b73-8348-8d5b215db302","priority":"medium","difficulty":"advanced","estimate_hours":28,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["nav2","local-planning","advanced"],"spec":{"problem":"The local controller decides how the rover follows global paths and dodges nearby obstacles on low-traction terrain.","goal":"Simulated obstacle scenarios and a configured, evaluated Nav2 local controller (e.g. Regulated Pure Pursuit, MPPI) selected with evidence. Low-level motor control and wheel PID are out of scope (Controls).","why":{"need":"Smooth, safe local motion.","contribution":"The controller inside NV-02.","failureImpact":"Oscillation or corner cutting into hazards.","consumers":["NV-02"]},"background":"Pure pursuit tracks a lookahead point; MPPI samples trajectories and scores them with critics (obstacles, path alignment, goal). Output is a velocity request on the AG-07 topic — never wheel commands.","prerequisites":[{"concept":"Nav2 controllers","why":"Options.","resourceIds":["a90c1792-89cb-532d-a2b3-d146f8d8141b","b1d13bcf-6b0c-5984-a22b-bdaf30aa5dd7"]},{"concept":"Local costmaps","why":"Obstacle inputs.","resourceIds":["a90c1792-89cb-532d-a2b3-d146f8d8141b"]}],"readFirst":["Controller plugins.","Controller source.","Nav2 basics."],"references":[{"repo":"GOFIRST-Robotics/Lunabotics","path":"config/nav2_isaac_sim.yaml","url":"https://github.com/GOFIRST-Robotics/Lunabotics/blob/main/config/nav2_isaac_sim.yaml","isFolder":false,"summary":"Full Nav2 parameter file including controller_server.","inspect":["controller_server plugin selection"],"relevance":"A real controller configuration to compare against.","questions":["Which controller and critics are configured?"],"adaptation":"Use as a baseline row in the comparison.","limitations":["Tuned for a different robot."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Scenario set (static, late-revealed, narrow passage) in SIM-01; tune two controllers; compare tracking error, clearance and smoothness.","guidance":{"packageStructure":"lunabot_navigation/\n  config/controllers/rpp.yaml\n  config/controllers/mppi.yaml\n  scripts/eval_controllers.py","files":["config/controllers/rpp.yaml","config/controllers/mppi.yaml","scripts/eval_controllers.py"],"inputs":[{"name":"/plan","type":"nav_msgs/msg/Path"},{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"},{"name":"/perception/traversability","type":"nav_msgs/msg/OccupancyGrid","note":"proposed"}],"outputs":[{"name":"/autonomy/cmd_vel","type":"geometry_msgs/msg/TwistStamped","note":"autonomy motion request — AG-07 contract (proposed)"}],"parameters":[{"name":"desired_linear_vel","default":"≤ AG-07 limit","description":"Must respect Controls'' advertised limits."},{"name":"lookahead_dist","default":"tuned","description":"RPP."}],"snippets":[{"title":"Switch controller plugin","label":"adapt","language":"yaml","code":"controller_server:\n  ros__parameters:\n    controller_plugins: [\"FollowPath\"]\n    FollowPath:\n      plugin: \"nav2_regulated_pure_pursuit_controller::RegulatedPurePursuitController\""}],"expectedBehavior":"Chosen controller avoids obstacles without oscillation within Controls'' limits.","pitfalls":["Implementing wheel-level control (Controls scope).","Tuning only on flat ground."]},"testPlan":["Same paths and scenarios per controller."],"measure":[{"metric":"Trajectory tracking error","definition":"RMS lateral error (m)."},{"metric":"Minimum clearance","definition":"m to obstacles."}],"document":["Tuning rationale."],"integrate":"NV-02 adopts the recommended configuration."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"abb74e9b-c86b-5989-a011-066e0cf96267","key":"NV-06","title":"Navigation Recovery Strategies","track_id":"NV","subtrack_id":"da351eb5-1a33-5b7e-a96b-a4396db6eff6","priority":"high","difficulty":"advanced","estimate_hours":28,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["recovery","behavior-tree","advanced"],"spec":{"problem":"Recovery behaviors designed for indoor robots (spin in place) can make things worse on regolith, and we have no tested plan for blocked paths, localization degradation, unreachable goals, failed actions or path invalidation.","goal":"Designed and evaluated recovery behavior for blocked paths, localization degradation, unreachable goals, failed navigation actions and path invalidation, encoded in the Nav2 BT and reported to AG-01.","why":{"need":"Get unstuck without making it worse.","contribution":"Navigation-level recovery that AG-10 escalates from.","failureImpact":"Digging in further or wasting minutes.","consumers":["NV-02","AG-01","AG-10"]},"background":"Nav2''s behavior server provides spin, back up, wait and clear-costmap behaviors; ordering lives in the BT. Localization degradation (SF-04) should pause navigation rather than trigger motion-based recovery.","prerequisites":[{"concept":"Nav2 behavior trees","why":"Recovery structure.","resourceIds":["2d84255f-edba-5a71-ad3c-56bed1d99bdd","4f7a858c-e5fe-5281-9da7-077ae4d5228f"]},{"concept":"Failure taxonomy","why":"Classify failures.","resourceIds":["a90c1792-89cb-532d-a2b3-d146f8d8141b"]}],"readFirst":["Behavior server.","BT semantics.","Replanning BT."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_config/behavior_trees/nav_to_pose_with_consistent_replanning_and_if_path_becomes_invalid.xml","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_config/behavior_trees/nav_to_pose_with_consistent_replanning_and_if_path_becomes_invalid.xml","isFolder":false,"summary":"BT with RecoveryNode (6 retries), IsPathValid-gated replanning and a Wait recovery.","inspect":["`RecoveryNode number_of_retries=\"6\"`","`IsPathValid` + `Inverter`","Recovery branch with `Wait`"],"relevance":"Starting tree for our recovery design.","questions":["Which failure types does it distinguish?","Which recoveries are missing for regolith?"],"adaptation":"Add failure-specific branches and report outcomes to AG-01.","limitations":["Minimal recovery set."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Failure taxonomy → per-failure recovery branch in the BT → result codes surfaced to AG-01 via the NavigateToPose result.","guidance":{"packageStructure":"lunabot_navigation/\n  behavior_trees/navigate_lunar_recovery.xml\n  scenarios/recovery/*.yaml","files":["behavior_trees/navigate_lunar_recovery.xml","scenarios/recovery/*.yaml"],"inputs":[{"name":"/localization/health","type":"diagnostic_msgs/msg/DiagnosticStatus","note":"proposed; may become a custom msg"},{"name":"/perception/traversability","type":"nav_msgs/msg/OccupancyGrid","note":"proposed"},{"name":"/plan","type":"nav_msgs/msg/Path"}],"outputs":[{"name":"navigate_to_pose result","type":"nav2_msgs/action/NavigateToPose","note":"error codes to AG-01"}],"parameters":[{"name":"number_of_retries","default":"bounded","description":"Per failure type."},{"name":"backup_dist_m","default":"small","description":"If backing up is safe."}],"snippets":[{"title":"Recovery branch sketch","label":"illustrative","language":"xml","code":"<RecoveryNode number_of_retries=\"2\" name=\"BlockedPath\">\n  <PipelineSequence>…</PipelineSequence>\n  <Sequence><ClearEntireCostmap service_name=\"global_costmap/clear_entirely_global_costmap\"/><Wait wait_duration=\"2\"/></Sequence>\n</RecoveryNode>"}],"expectedBehavior":"Each failure type resolves or fails cleanly within bounded retries.","pitfalls":["Motion-based recovery while localization is degraded.","Infinite retries."]},"testPlan":["Scenario per failure type × seeds."],"measure":[{"metric":"Recovery success rate","definition":"Failures resolved / failures."},{"metric":"Recovery frequency","definition":"Recoveries per run."}],"document":["Recovery policy table."],"integrate":"NV-02 BT; AG-10 escalates when navigation recovery fails."},"legacy_keys":["NV-07"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"6bf3e49f-41af-56da-93e2-6fe45bb567a1","key":"NV-07","title":"Path Planning Benchmark Tool","track_id":"NV","subtrack_id":"ce027498-9cdb-5a3d-9306-e05504e1cf82","priority":"medium","difficulty":"intermediate","estimate_hours":24,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["benchmark","planning","advanced"],"spec":{"problem":"Planner comparisons are done ad hoc on different maps, so results aren''t comparable.","goal":"A repeatable tool comparing A*, Dijkstra, an any-angle planner and Nav2 planner options on consistent test maps with measurable metrics.","why":{"need":"Evidence-based planner choices.","contribution":"Decides the planner for NV-02 (ADR: Which navigation planner?).","failureImpact":"Planner choice by opinion.","consumers":["NV-01","NV-04","ADR: planner"]},"background":"Purdue''s test.launch runs map_server + planner_server with a fixed map — the minimal harness for evaluating Nav2 planner plugins outside a full stack.","prerequisites":[{"concept":"Graph search","why":"Algorithms compared.","resourceIds":["3c89f409-b976-5345-8cbb-3b1b80a8cfd8","9e89b990-e8fb-533a-9bea-e5e36149cdca"]},{"concept":"Nav2 planner server","why":"Plugin evaluation.","resourceIds":["a90c1792-89cb-532d-a2b3-d146f8d8141b"]}],"readFirst":["test.launch harness and S-Theta*.","Smac planner.","Theta* planner."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_bringup/launch/test.launch","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_bringup/launch/test.launch","isFolder":false,"summary":"Minimal launch: RViz, a static map→robot transform, nav2_planner planner_server with test_planner.yml, nav2_map_server with a saved map, and a lifecycle manager.","inspect":["`planner_server` node with `test_planner.yml`","`map_server` with `yaml_filename`","`lifecycle_manager` autostart"],"relevance":"Exactly the harness shape for benchmarking planners on fixed maps.","questions":["How would you call ComputePathToPose repeatedly from a script?","Which planner parameters live in test_planner.yml?"],"adaptation":"Wrap this pattern in a Python launch with a map list and a benchmark client.","limitations":["Single map; manual goals."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"`lunabot_planning/benchmark/`: maps/*.yaml (from PM-01 and SIM scenarios), a launch modeled on Purdue''s test.launch, and a client that calls ComputePathToPose for start/goal pairs per planner, plus offline runs of our own A*/Dijkstra/S-Theta*; writes CSV and plots.","guidance":{"packageStructure":"lunabot_planning/benchmark/\n  maps/\n  pairs.yaml\n  launch/planner_bench.launch.py\n  bench_client.py\n  plot_results.py","files":["launch/planner_bench.launch.py","bench_client.py","pairs.yaml","plot_results.py"],"inputs":[{"name":"/map","type":"nav_msgs/msg/OccupancyGrid","note":"map_server"},{"name":"compute_path_to_pose","type":"nav2_msgs/action/ComputePathToPose"}],"outputs":[{"name":"results/planning/*.csv","type":"file"}],"parameters":[{"name":"planners","default":"[astar, dijkstra, stheta, nav2_navfn, nav2_smac, nav2_thetastar]","description":"Compared set."},{"name":"repeats","default":"5","description":"Timing repeats."}],"snippets":[{"title":"Call the planner server","label":"adapt","language":"python","code":"goal = ComputePathToPose.Goal(goal=goal_pose, start=start_pose, use_start=True, planner_id=pid)\nres = await client.send_goal_async(goal)"}],"expectedBehavior":"One CSV row per (map, pair, planner) with runtime, length, clearance and turns.","pitfalls":["Different maps or inflation per planner.","Timing including first-call warm-up."]},"testPlan":["Each planner × each pair × 5 repeats."],"measure":[{"metric":"Planning time","definition":"ms (median)."},{"metric":"Path length","definition":"m."},{"metric":"Minimum clearance","definition":"m."},{"metric":"Turn count","definition":"Heading changes > 10°."}],"document":["How to add a planner or map."],"integrate":"Evidence for the planner ADR and NV-04."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"623f2fa1-f75b-5589-a854-54e6efd3fa76","key":"NV-08","title":"Dynamic Obstacle Replanning","track_id":"NV","subtrack_id":"30713db3-dd8b-533d-a481-6ca349dc1cd4","priority":"low","difficulty":"advanced","estimate_hours":24,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["replanning","advanced"],"spec":{"problem":"Obstacles discovered late (behind crater rims) require fast, stable replanning.","goal":"Replanning triggers and parameters that react quickly and stably to newly observed obstacles, validated in simulation.","why":{"need":"Robust navigation in partially observed terrain.","contribution":"Stability for NV-02.","failureImpact":"Collisions or plan flip-flopping.","consumers":["NV-02","NV-06"]},"background":"Replan triggers: path invalidation, periodic replanning, costmap change; hysteresis prevents oscillation between near-equal plans.","prerequisites":[{"concept":"Nav2 BTs","why":"Replanning triggers.","resourceIds":["2d84255f-edba-5a71-ad3c-56bed1d99bdd"]},{"concept":"Costmaps","why":"Update timing.","resourceIds":["a90c1792-89cb-532d-a2b3-d146f8d8141b"]}],"readFirst":["BT semantics.","Costmap updates."],"references":[],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Late-reveal scenario set; tune replan rate, path-validity checks and hysteresis in the BT.","guidance":{"packageStructure":"lunabot_navigation/\n  behavior_trees/replanning.xml\n  scenarios/late_reveal/*.yaml","files":["behavior_trees/replanning.xml","scenarios/late_reveal/*.yaml"],"inputs":[{"name":"/perception/traversability","type":"nav_msgs/msg/OccupancyGrid","note":"proposed"},{"name":"/plan","type":"nav_msgs/msg/Path"}],"outputs":[{"name":"/plan","type":"nav_msgs/msg/Path"}],"parameters":[{"name":"replan_hz","default":"1–2","description":"RateController."},{"name":"switch_threshold","default":"tuned","description":"Cost improvement required to switch plans."}],"snippets":[{"title":"Rate-limited replanning","label":"adapt","language":"xml","code":"<RateController hz=\"1.0\">\n  <ComputePathToPose goal=\"{goal}\" path=\"{path}\" planner_id=\"GridBased\"/>\n</RateController>"}],"expectedBehavior":"Fast reaction with bounded plan switches.","pitfalls":["Replanning so often the controller never settles."]},"testPlan":["Late-reveal set × seeds."],"measure":[{"metric":"Reaction time","definition":"Obstacle observed → new plan (ms)."},{"metric":"Plan switches","definition":"Per run."}],"document":["Parameters and rationale."],"integrate":"NV-02 BT."},"legacy_keys":["NV-06"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"200c6aa3-aa3a-5c0f-a86c-3a4996adc549","key":"SIM-04","title":"LiDAR and Camera Simulation","track_id":"SIM","subtrack_id":"84a840d6-82e4-5974-a663-f6026df273d4","priority":"high","difficulty":"intermediate","estimate_hours":28,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["sensors","simulation","advanced"],"spec":{"problem":"Perception and localization can only be tested in simulation if simulated LiDAR and cameras publish realistic data, on the right topics, in the right frames.","goal":"Simulated LiDAR and camera outputs added to the rover model, ROS topic bridges configured, frame conventions verified, representative test data generated and recorded to bags — with rates, fields and noise compared to the intended sensors (specs from Hardware/Electrical when available).","why":{"need":"Every perception and LIO task needs simulated sensors.","contribution":"Inputs for PM-01/02/03, SF-03 and AG-05 datasets.","failureImpact":"Algorithms tuned to unrealistic or mis-framed data.","consumers":["PM-01","PM-02","SF-03","AG-05"]},"background":"Gazebo sensors (gpu_lidar, camera, imu) publish to Gazebo topics bridged by ros_gz_bridge. LIO needs per-point timestamps; check whether the simulated LiDAR provides them.","prerequisites":[{"concept":"Gazebo sensors","why":"Configuration.","resourceIds":["4cbed166-f914-5a76-a384-58aaf16d4896"]},{"concept":"ros_gz bridge","why":"Topic bridging.","resourceIds":["5bc659ce-ac67-5c98-8285-9a73a5d91cce","b5e4dc6c-ed48-5a69-969f-e7b36916c458"]},{"concept":"Frames","why":"Sensor frames match SF-02.","resourceIds":["76c47da2-5108-5439-a417-9023737fbe51"]}],"readFirst":["Sensor configuration.","Bridging.","Xacro with sim sensors."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_description/urdf/v2_bot.urdf.xacro","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_description/urdf/v2_bot.urdf.xacro","isFolder":false,"summary":"COD''s Xacro with a use_sim argument and sensor plate pitch property.","inspect":["`xacro:arg name=\"use_sim\"`","`sensor_plate_pitch`","sensor links"],"relevance":"How a team attached simulated sensors with sim/real differences.","questions":["Where are the sensor plugins defined?","How do sim and real frame offsets differ?"],"adaptation":"Add sensor plugins behind a use_sim flag in SIM-02''s model.","limitations":["Team-specific sensors."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Sensor macros in `lunabot_description/urdf/sensors.xacro` (gpu_lidar, camera, imu) behind use_sim; bridge config `lunabot_sim/config/bridge.yaml`; `scripts/record_dataset.sh` recording standard topics per scenario.","guidance":{"packageStructure":"lunabot_description/urdf/sensors.xacro\nlunabot_sim/config/bridge.yaml\nlunabot_sim/scripts/record_dataset.sh\ndocs/sensor_sim.md","files":["urdf/sensors.xacro","config/bridge.yaml","scripts/record_dataset.sh"],"inputs":[],"outputs":[{"name":"/lidar/points","type":"sensor_msgs/msg/PointCloud2","note":"proposed"},{"name":"/camera/image_raw","type":"sensor_msgs/msg/Image","note":"proposed"},{"name":"/camera/camera_info","type":"sensor_msgs/msg/CameraInfo","note":"proposed"},{"name":"/imu/data","type":"sensor_msgs/msg/Imu","note":"proposed"}],"parameters":[{"name":"lidar_rate_hz","default":"from Hardware spec or assumed","description":"Labeled."},{"name":"camera_resolution","default":"from Hardware spec or assumed","description":"Labeled."}],"snippets":[{"title":"Bridge a LiDAR point cloud","label":"adapt","language":"yaml","code":"- ros_topic_name: \"/lidar/points\"\n  gz_topic_name: \"/lidar/points\"\n  ros_type_name: \"sensor_msgs/msg/PointCloud2\"\n  gz_type_name: \"gz.msgs.PointCloudPacked\"\n  direction: GZ_TO_ROS"},{"title":"Check rate and frame","label":"verified","language":"bash","code":"ros2 topic hz /lidar/points\nros2 topic echo /lidar/points --field header --once"}],"expectedBehavior":"Sensors publish at configured rates in frames matching SF-02; bags exist for each SIM-01 scenario.","pitfalls":["Frame ids that don''t exist in TF.","Camera optical frame vs camera_link confusion.","Inventing specs instead of labeling assumptions."]},"testPlan":["Static and moving recordings per scenario."],"measure":[{"metric":"Sensor publication frequency","definition":"Hz vs spec."},{"metric":"Noise sigma","definition":"Std. dev. on a static target."}],"document":["Sensor configuration and assumptions."],"integrate":"PM/SF tasks and AG-05 datasets."},"legacy_keys":["SIM-05"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"4a899943-27c2-5308-a725-93a69524c751","key":"SIM-05","title":"Simulation Scenario Generator","track_id":"SIM","subtrack_id":"cab1c7a4-405b-5d3b-a8b9-3227d7497422","priority":"medium","difficulty":"intermediate","estimate_hours":24,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["scenarios","advanced"],"spec":{"problem":"Hand-built scenarios cover few cases; bugs hide in combinations.","goal":"A generator that creates obstacle arrangements, randomizes start and goal locations, varies terrain parameters, supports deterministic seeds and exports benchmark results.","why":{"need":"Broader, reproducible test coverage.","contribution":"Feeds SIM-07 and AG-08.","failureImpact":"Overfitting to a few scenarios.","consumers":["SIM-07","AG-08","NV-08"]},"background":"Procedural generation with constraints (reachable goals, minimum clearances) and seeds; validate each scenario before use.","prerequisites":[{"concept":"SDF worlds and spawning","why":"Scenario format.","resourceIds":["20615bd3-848f-55fb-ab76-08846fe13557"]},{"concept":"Seeded randomness","why":"Reproducibility.","resourceIds":["73298a07-2ed6-5224-99d5-c009df68ca5e"]}],"readFirst":["World format.","Base world."],"references":[{"repo":"GOFIRST-Robotics/Lunabotics","path":"src/gazebo/gazebo_files/worlds/NASA_field.sdf","url":"https://github.com/GOFIRST-Robotics/Lunabotics/blob/main/src/gazebo/gazebo_files/worlds/NASA_field.sdf","isFolder":false,"summary":"SDF 1.8 world skeleton with Gazebo system plugins.","inspect":["`<world name=\"NASA_field\">`","system plugins"],"relevance":"Base world that generated scenarios populate.","questions":["What must every generated world include?"],"adaptation":"Generate scenario YAML consumed by SIM-01''s spawner rather than whole SDF files.","limitations":["Uses ignition- plugin names."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"`lunabot_sim/generator/generate.py --seed N` → scenario YAML (rocks, craters, start, goals, terrain params) + validity checks (reachability via grid A*, clearances); `export.py` writes a results index.","guidance":{"packageStructure":"lunabot_sim/generator/\n  generate.py\n  validate.py\n  export.py\n  schema.yaml","files":["generate.py","validate.py","export.py"],"inputs":[],"outputs":[{"name":"scenarios/generated/*.yaml","type":"file"}],"parameters":[{"name":"seed","default":"int","description":"Deterministic."},{"name":"rock_density","default":"range","description":"Obstacles per m²."},{"name":"min_clearance_m","default":"rover width + margin","description":"Validity."}],"snippets":[{"title":"Seeded generation","label":"illustrative","language":"python","code":"rng = np.random.default_rng(seed)\nrocks = [(rng.uniform(*x_range), rng.uniform(*y_range), rng.choice(sizes)) for _ in range(n)]"}],"expectedBehavior":"Same seed → identical scenario; invalid scenarios rejected automatically.","pitfalls":["Generating unreachable goals.","Arena dimensions not from the guidebook."]},"testPlan":["Generate 100 scenarios; validate all; regenerate 10 and diff."],"measure":[{"metric":"Valid scenario rate","definition":"Passing / generated."}],"document":["Schema and parameters."],"integrate":"SIM-07 runs generated scenarios."},"legacy_keys":["SIM-06"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"2616208a-1b7d-5f74-ad87-2b7611326800","key":"SIM-06","title":"Isaac Sim Feasibility Study","track_id":"SIM","subtrack_id":"e6c5ff36-f4fc-5401-a87f-bd6eb872cb3d","priority":"low","difficulty":"expert","estimate_hours":32,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["isaac-sim","research","advanced"],"spec":{"problem":"Gazebo''s rendering may be insufficient for camera-based perception; Isaac Sim offers photoreal sensors but needs RTX GPUs. Migrating the team without evidence would be costly.","goal":"A study of Isaac Sim capabilities vs Gazebo, GPU requirements, synthetic sensor support, and a recommendation on whether to use it as a supplementary environment — not a team migration.","why":{"need":"Pick the right tool for perception work.","contribution":"Informs PM-05/PM-07 data generation.","failureImpact":"Investing in a tool few members can run.","consumers":["PM-05","PM-07","ADR: Gazebo baseline"]},"background":"GOFIRST''s Nav2 configuration targets Isaac Sim, so a Lunabotics team has made it work; hardware access is the main constraint.","prerequisites":[{"concept":"Isaac Sim basics","why":"Setup.","resourceIds":["9a8130e4-5917-5dba-baee-be522be834cb"]},{"concept":"URDF import","why":"Rover model.","resourceIds":["87f943be-21c8-56cc-bd51-e29e089e9a00"]}],"readFirst":["Isaac Sim.","Isaac Sim Nav2 config."],"references":[{"repo":"GOFIRST-Robotics/Lunabotics","path":"config/nav2_isaac_sim.yaml","url":"https://github.com/GOFIRST-Robotics/Lunabotics/blob/main/config/nav2_isaac_sim.yaml","isFolder":false,"summary":"Nav2 parameters for Isaac Sim (use_sim_time False at top).","inspect":["`bt_navigator` section","costmap sources"],"relevance":"Evidence of a Lunabotics Nav2 stack on Isaac Sim.","questions":["Which topics/frames differ from Gazebo setups?"],"adaptation":"Use to estimate integration effort.","limitations":["Different robot and sensors."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Inventory GPUs on the team; import SIM-02 URDF; minimal arena; bridge camera/LiDAR; compare with Gazebo on one perception scenario.","guidance":{"packageStructure":"research/isaac_sim/\n  setup.md\n  comparison.md\n  recommendation.md","files":["setup.md","comparison.md","recommendation.md"],"inputs":[],"outputs":[{"name":"research/isaac_sim/recommendation.md","type":"file"}],"parameters":[{"name":"gpu","default":"team inventory","description":"Who can run it."}],"snippets":[{"title":"Compare sensor rates","label":"verified","language":"bash","code":"ros2 topic hz /camera/image_raw"}],"expectedBehavior":"A recommendation with hardware requirements and a supplementary-use plan.","pitfalls":["Moving the team before benefits are justified.","Ignoring members without RTX GPUs."]},"testPlan":["Same perception scenario in both simulators."],"measure":[{"metric":"Real-time factor","definition":"Sim/wall time."},{"metric":"Sensor publication frequency","definition":"Hz."}],"document":["Setup, comparison and recommendation."],"integrate":"Decides whether perception data generation uses Isaac Sim."},"legacy_keys":["SIM-04"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"52b46bd5-54cf-5189-b9a6-c7832cc26b78","key":"SIM-07","title":"Automated Autonomy Regression Testing","track_id":"SIM","subtrack_id":"87a787a1-6da5-5f9a-b6a9-04cd0134a266","priority":"high","difficulty":"intermediate","estimate_hours":28,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["regression","automation","advanced"],"spec":{"problem":"Running scenarios by hand is slow, so people stop doing it, and regressions slip in.","goal":"Automation that launches simulation scenarios headless, executes autonomy test cases, records outputs, calculates success metrics and flags regressions against stored baselines.","why":{"need":"Catch regressions every time code changes.","contribution":"Runs AG-05 and AG-08 checks unattended; CI hook for AG-13.","failureImpact":"Broken autonomy discovered at integration.","consumers":["AG-05","AG-08","AG-13"]},"background":"Headless Gazebo + launch_testing or a Python runner can start a scenario, wait for a mission result or timeout, then evaluate a bag. Determinism needs fixed seeds and sim time.","prerequisites":[{"concept":"Launch testing","why":"Automated launches.","resourceIds":["5b0717be-ed08-56c5-a602-6eabadaa2cec"]},{"concept":"Bag evaluation","why":"Metrics from recordings.","resourceIds":["6f784f87-cfa7-5ead-a50c-c10257e214bd"]}],"readFirst":["Testing.","Bag evaluation.","Replay launch pattern."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_bringup/launch/bag.launch","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_bringup/launch/bag.launch","isFolder":false,"summary":"Playback launch with arguments for sim vs real and the nodes re-run on recorded data.","inspect":["`<arg name=\"sim\">`","nodes started alongside playback"],"relevance":"Pattern for replaying recorded data through nodes under test.","questions":["Which nodes are re-run vs replayed?"],"adaptation":"Combine live-sim scenario runs with bag-replay checks in one runner.","limitations":["Team-specific nodes."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"`lunabot_testing/regression/run.py`: for each case (SIM-05 scenario + seed + test type), launch headless sim + stack, wait for completion/timeout, record, evaluate metrics, compare to baselines with tolerances, write a JUnit/JSON report.","guidance":{"packageStructure":"lunabot_testing/regression/\n  cases.yaml\n  run.py\n  baselines/\n  report.py","files":["cases.yaml","run.py","report.py"],"inputs":[{"name":"/mission/state","type":"std_msgs/msg/String","note":"proposed; custom msg in AG-04"},{"name":"/clock","type":"rosgraph_msgs/msg/Clock","note":"simulation time"}],"outputs":[{"name":"results/regression/<date>/report.json","type":"file"}],"parameters":[{"name":"headless","default":"true","description":"No GUI."},{"name":"tolerances","default":"per metric","description":"Regression thresholds."}],"snippets":[{"title":"Run the regression set","label":"illustrative","language":"bash","code":"python3 lunabot_testing/regression/run.py --cases cases.yaml --headless --out results/regression/"}],"expectedBehavior":"One command runs the set and reports pass/fail per case with metric deltas.","pitfalls":["Flaky timing without sim time.","Baselines updated silently."]},"testPlan":["Inject a known regression; confirm detection.","Run twice; identical results."],"measure":[{"metric":"Suite runtime","definition":"Minutes."},{"metric":"Determinism spread","definition":"Metric difference between identical runs."}],"document":["How to add a case and update a baseline (reviewed)."],"integrate":"AG-13 CI runs the subset; AG-08 uses the full set."},"legacy_keys":[],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"ee1af36f-12ee-5dfa-94ad-4bb10983e85b","key":"AG-09","title":"Mission Utility Optimization","track_id":"AG","subtrack_id":"0b7fff48-6f3f-5746-8a0e-1ffcf49c85e2","priority":"low","difficulty":"advanced","estimate_hours":32,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["mission","optimization","advanced"],"spec":{"problem":"Simple goal selection ignores time remaining and expected yield per cycle.","goal":"A utility model choosing excavation/deposition targets and cycle counts that improves simulated mission output over NV-03''s baseline.","why":{"need":"Maximize useful mission output.","contribution":"Plugs into NV-03 scoring and AG-01 cycle decisions.","failureImpact":"Wasted cycles near the end of a run.","consumers":["NV-03","AG-01"]},"background":"Expected utility per unit time with constraints (time remaining, travel time from NV-04, reported material estimates from AG-02).","prerequisites":[{"concept":"Utility functions","why":"Modeling decisions.","resourceIds":["1022e3ee-39bc-58fb-bc6c-9cc93bc49cf2"]},{"concept":"Zones","why":"Geometry.","resourceIds":["a9d3d523-0225-5ccc-865c-0984777af6c1"]}],"readFirst":["Planning background.","Zones."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_behavior/lunabot_behavior/zones.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_behavior/lunabot_behavior/zones.py","isFolder":false,"summary":"Zone definitions and distance helpers.","inspect":["`get_distance_from_exc` / `get_distance_from_berm`"],"relevance":"Distance terms in a utility model.","questions":["What would replace straight-line distance?"],"adaptation":"Use planner travel time instead of distance.","limitations":["Distance only."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Scoring plugin for NV-03 using travel time, time remaining and material estimate; cycle-continuation rule in AG-01.","guidance":{"packageStructure":"lunabot_mission/\n  lunabot_mission/utility.py\n  test/test_utility.py","files":["utility.py","test/test_utility.py"],"inputs":[{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"},{"name":"excavate result","type":"Excavate.action","note":"material estimate"}],"outputs":[{"name":"/mission/goal_pose","type":"geometry_msgs/msg/PoseStamped","note":"proposed"}],"parameters":[{"name":"weights","default":"documented","description":"Utility terms."}],"snippets":[{"title":"Continue-cycle rule","label":"illustrative","language":"python","code":"continue_cycle = time_remaining > est_cycle_time * cfg.safety_factor"}],"expectedBehavior":"More successful cycles per run than baseline.","pitfalls":["Optimizing for scoring rules not verified in the guidebook."]},"testPlan":["Paired simulated missions."],"measure":[{"metric":"Successful cycles","definition":"Per mission time."}],"document":["Terms and rationale."],"integrate":"NV-03 scoring; AG-01 cycle decision."},"legacy_keys":["MS-04"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"7841d012-2a16-58d1-a668-337bc945d618","key":"AG-10","title":"Autonomous Recovery State Machine","track_id":"AG","subtrack_id":"0b7fff48-6f3f-5746-8a0e-1ffcf49c85e2","priority":"medium","difficulty":"advanced","estimate_hours":32,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["recovery","behavior-tree","advanced"],"spec":{"problem":"AG-01 stops safely on faults but doesn''t attempt structured, mission-level recovery decisions.","goal":"A recovery sub-machine (or behavior tree) that classifies faults — navigation failure, localization loss, excavation/deposition failure, Controls fault — and decides bounded recovery sequences before escalating to safe stop.","why":{"need":"Finish missions despite recoverable faults.","contribution":"Extends AG-01 above NV-06''s navigation-level recovery.","failureImpact":"Unnecessary stops or unsafe retries.","consumers":["AG-01","AG-08"]},"background":"Mission-level recovery decides *what* to try (re-localize, choose another goal, retry an excavation request) and *when to stop*; it never commands motors. Behavior trees suit layered fallbacks.","prerequisites":[{"concept":"FSMs and BTs","why":"Structure.","resourceIds":["884a4786-fd54-5ef7-8b11-9e8784da5ec1","2d84255f-edba-5a71-ad3c-56bed1d99bdd","f3a54f40-9976-5a0c-932d-fe743f493b4b"]},{"concept":"Fault signals","why":"Inputs.","resourceIds":["c6e44073-7ccb-5ef7-8747-5a3bccac116b"]}],"readFirst":["FSM library.","BT alternative.","FSM vs BT."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_behavior/lunabot_behavior/main_states.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_behavior/lunabot_behavior/main_states.py","isFolder":false,"summary":"Mission Enum with paired *_STALL states.","inspect":["`*_STALL` states","`get_transition`"],"relevance":"How a team routed failures per operation.","questions":["Which recoveries are mission decisions vs actuator handling?"],"adaptation":"Keep the decision part; delegate actuator handling to Controls via AG-02/03 results.","limitations":["Actuator-level states."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Fault taxonomy → recovery policy table → BT subtree invoked from AG-01 RECOVERY with bounded attempts and escalation to SAFE_STOP.","guidance":{"packageStructure":"lunabot_mission/\n  lunabot_mission/recovery.py\n  config/recovery_policy.yaml\n  test/test_recovery.py","files":["recovery.py","config/recovery_policy.yaml","test/test_recovery.py"],"inputs":[{"name":"/localization/health","type":"diagnostic_msgs/msg/DiagnosticStatus","note":"proposed; may become a custom msg"},{"name":"/controls/status","type":"lunabot_interfaces/msg/ControlsStatus","note":"motion enabled, limits, faults — AG-07 (proposed)"},{"name":"/mission/state","type":"std_msgs/msg/String","note":"proposed; custom msg in AG-04"}],"outputs":[{"name":"/mission/state","type":"std_msgs/msg/String","note":"proposed; custom msg in AG-04"},{"name":"/autonomy/safe_stop_request","type":"std_msgs/msg/Bool","note":"autonomy asks Controls to stop — AG-07 (proposed)"}],"parameters":[{"name":"max_attempts","default":"per fault","description":"Bounded."},{"name":"recovery_time_budget_s","default":"per fault","description":"Bounded."}],"snippets":[{"title":"Policy table","label":"illustrative","language":"yaml","code":"LOC_LOST: [wait_for_relocalization, escalate]\nNAV_FAILED: [replan_new_goal, escalate]\nEXC_FAILED: [retry_request_once, select_new_zone, escalate]\nCONTROLS_FAULT: [escalate]"}],"expectedBehavior":"Recoverable faults resolve within bounds; others reach SAFE_STOP quickly.","pitfalls":["Infinite retry loops.","Recovering from Controls faults without Controls re-enabling motion."]},"testPlan":["Fault injection per type."],"measure":[{"metric":"Recovery count","definition":"Successful recoveries per run."},{"metric":"Mission completion rate","definition":"Missions completed with faults injected."}],"document":["Policy table and escalation rules."],"integrate":"AG-01 calls it; AG-08 exercises it."},"legacy_keys":["MS-05"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"fe4c77e7-69aa-5dd1-bc21-ba5ad5e030ee","key":"AG-11","title":"Excavation Request Strategy Comparison","track_id":"AG","subtrack_id":"0b7fff48-6f3f-5746-8a0e-1ffcf49c85e2","priority":"low","difficulty":"advanced","estimate_hours":24,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["mission","excavation","advanced"],"spec":{"problem":"Where, when and how long to request excavation affects yield and time, but we lack evidence. Actuator-level strategy (depth, power) belongs to Controls/Mechanical.","goal":"A comparison of high-level excavation request strategies (zone selection, time budget, number of requests per cycle) using the AG-02 interface in simulation, with a hardware validation plan coordinated with Controls.","why":{"need":"More material per cycle without more risk.","contribution":"Parameters for AG-01/AG-09.","failureImpact":"Too many failed or low-yield requests.","consumers":["AG-01","AG-09"]},"background":"Simulation cannot model regolith digging well; treat results as relative, and rely on Controls'' reported outcomes and material estimates for real decisions.","prerequisites":[{"concept":"Excavation interface","why":"AG-02.","resourceIds":["d52f49f7-6681-5630-ab76-69ee37ada9ca"]},{"concept":"Experiment design","why":"Fair comparison.","resourceIds":["788a889e-c6bf-5d2f-af0e-d66aee74b4be"]}],"readFirst":["Excavation interface reference."],"references":[],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Strategy parameter sets for AG-01 (time budget, zone choice rule, retry policy) evaluated with the AG-02 mock configured from Controls'' expected behavior.","guidance":{"packageStructure":"lunabot_mission/\n  config/excavation_strategies/*.yaml\n  scripts/compare_strategies.py","files":["config/excavation_strategies/*.yaml","scripts/compare_strategies.py"],"inputs":[{"name":"excavate","type":"Excavate.action results"}],"outputs":[{"name":"results/excavation/*.csv","type":"file"}],"parameters":[{"name":"time_budget_s","default":"candidate values","description":"Per request."},{"name":"zone_rule","default":"nearest | utility","description":"Selection."}],"snippets":[{"title":"Strategy file","label":"illustrative","language":"yaml","code":"name: short_bursts\ntime_budget_s: 15\nrequests_per_cycle: 2\nzone_rule: utility"}],"expectedBehavior":"Relative ranking of strategies with stated limits.","pitfalls":["Treating simulated soil as realistic.","Specifying actuator parameters (Controls scope)."]},"testPlan":["Each strategy × seeds."],"measure":[{"metric":"Excavation outcome","definition":"Success/failure counts and reported material estimates."}],"document":["Strategy comparison and limits."],"integrate":"AG-01 configuration."},"legacy_keys":["MS-06"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"cb480a2c-2df8-578e-88be-4a6e2d1f3dfe","key":"AG-12","title":"Autonomy Pipeline Latency Analysis","track_id":"AG","subtrack_id":"526a2766-2d19-54ce-9366-f8a68d898801","priority":"medium","difficulty":"advanced","estimate_hours":24,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["latency","performance","advanced"],"spec":{"problem":"End-to-end latency from sensing to the autonomy command output limits safe speed, but it''s unmeasured.","goal":"A measured latency budget across the autonomy pipeline (sensor → filter → costmap → plan → controller → AG-07 command output) with bottlenecks identified and speed implications communicated to Controls.","why":{"need":"Set autonomy speed requests from evidence.","contribution":"Input to AG-07 limits and NV-05 tuning.","failureImpact":"Reacting too late to hazards.","consumers":["AG-07","NV-05"]},"background":"Header stamps propagated through the pipeline (and ros2_tracing where needed) give per-stage latency. Measurement stops at the AG-07 boundary; Controls measures their side.","prerequisites":[{"concept":"Timestamps","why":"Measurement.","resourceIds":["54c635df-9476-5698-8046-9492aeb99971"]},{"concept":"Executors","why":"Callback scheduling.","resourceIds":["5a74315a-96bd-55b2-a39d-6f39859c7978"]}],"readFirst":["Executors and timing."],"references":[],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Instrument stage outputs with input stamps; record under nominal and loaded CPU; analysis notebook producing distributions per stage.","guidance":{"packageStructure":"lunabot_testing/latency/\n  instrument.md\n  analyze_latency.ipynb","files":["instrument.md","analyze_latency.ipynb"],"inputs":[{"name":"/lidar/points","type":"sensor_msgs/msg/PointCloud2","note":"proposed"},{"name":"/perception/traversability","type":"nav_msgs/msg/OccupancyGrid","note":"proposed"},{"name":"/plan","type":"nav_msgs/msg/Path"},{"name":"/autonomy/cmd_vel","type":"geometry_msgs/msg/TwistStamped","note":"autonomy motion request — AG-07 contract (proposed)"}],"outputs":[{"name":"results/latency/*.csv","type":"file"}],"parameters":[{"name":"cpu_load","default":"nominal | stressed","description":"Test condition."}],"snippets":[{"title":"Stage latency","label":"illustrative","language":"python","code":"lat_ms = (recv_time - msg.header.stamp).nanoseconds / 1e6"}],"expectedBehavior":"p50/p95/p99 per stage and end-to-end.","pitfalls":["Mixing clocks (sim vs wall).","Measuring beyond the AG-07 boundary."]},"testPlan":["Nominal and loaded CPU runs."],"measure":[{"metric":"Command latency","definition":"Sensor stamp → /autonomy/cmd_vel (ms) p50/p95/p99."}],"document":["Latency budget."],"integrate":"AG-07 limits and NV-05."},"legacy_keys":["CS-04"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"b69c5010-89e5-55e1-bbad-89b6896fccc5","key":"AG-13","title":"CI for ROS 2 Autonomy Packages","track_id":"AG","subtrack_id":"526a2766-2d19-54ce-9366-f8a68d898801","priority":"high","difficulty":"intermediate","estimate_hours":20,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":"2557206e-1f5d-529e-bd80-6b46d36bf565","start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["ci","advanced"],"spec":{"problem":"Without CI, broken builds and failing tests reach main.","goal":"GitHub Actions CI building the autonomy workspace, running unit tests, linting and a headless SIM-07 smoke subset on every PR.","why":{"need":"Keep main green.","contribution":"Guards every subteam''s work.","failureImpact":"Integration days spent fixing builds.","consumers":["All four subteams"]},"background":"setup-ros + action-ros-ci, or industrial_ci, provide ROS 2 CI on GitHub runners.","prerequisites":[{"concept":"GitHub Actions","why":"Workflows.","resourceIds":["c13050a8-8b3b-5598-9ee2-057be717b774"]},{"concept":"colcon test","why":"Testing.","resourceIds":["5b0717be-ed08-56c5-a602-6eabadaa2cec"]}],"readFirst":["ROS 2 CI action.","Install ROS on runners.","Alternative."],"references":[{"repo":"utahrobotics/utah-lunabotics-2027","path":"ONBOARDING.md","url":"https://github.com/utahrobotics/utah-lunabotics-2027/blob/main/ONBOARDING.md","isFolder":false,"summary":"Utah onboarding guide covering environment setup and PR workflow.","inspect":["Workflow / PR sections"],"relevance":"Expectations CI should enforce.","questions":["Which checks do they expect before a PR?"],"adaptation":"Mirror expectations in our CI guide.","limitations":["Different tooling."],"verifiedOn":"2026-10-25"}],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Workflow: checkout → setup-ros → action-ros-ci (build + colcon test) → lint → optional headless smoke test; cache dependencies.","guidance":{"packageStructure":".github/workflows/ci.yml\ndocs/ci.md","files":[".github/workflows/ci.yml","docs/ci.md"],"inputs":[],"outputs":[{"name":"GitHub check status","type":"CI"}],"parameters":[{"name":"ros_distro","default":"team decision","description":"Matches AG-04."}],"snippets":[{"title":"Workflow skeleton","label":"adapt","language":"yaml","code":"jobs:\n  build:\n    runs-on: ubuntu-latest\n    steps:\n      - uses: actions/checkout@v4\n      - uses: ros-tooling/setup-ros@v0.7\n      - uses: ros-tooling/action-ros-ci@v0.4\n        with:\n          target-ros2-distro: humble","note":"Pin action versions after checking their releases."}],"expectedBehavior":"Failing builds/tests block merges.","pitfalls":["Very slow CI from building third-party packages each time."]},"testPlan":["A deliberately failing PR is blocked."],"measure":[{"metric":"CI runtime","definition":"Minutes per run."}],"document":["CI guide."],"integrate":"Protects all subteams."},"legacy_keys":["IT-04"],"archived":false,"external_team":null,"archived_reason":"","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"5505b151-9d32-5b65-b60e-7c33c7a6677f","key":"CS-05","title":"Command Watchdog Validation","track_id":"AG","subtrack_id":"b7e6ac48-c8c5-53f5-9767-258abf175bf5","priority":"medium","difficulty":"intermediate","estimate_hours":20,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":null,"start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["archived","advanced"],"spec":{"problem":"The command watchdog must be proven under real failure modes (network loss, node crash, CPU starvation).","goal":"A validation campaign showing the watchdog stops motion within bounds under each failure mode.","why":{"need":"Confidence in safety behavior.","contribution":"Controls safety evidence.","failureImpact":"Rover continues after link loss.","consumers":["Controls"]},"background":"Fault injection across process, network and scheduling layers.","prerequisites":[{"concept":"Command timeouts","why":"twist_mux behavior.","resourceIds":["5cbab412-d11d-5c62-9a84-6221ca149c71"]}],"readFirst":["Timeout behavior."],"references":[],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Scripted fault campaign (Controls-owned).","guidance":{"packageStructure":"","files":[],"inputs":[],"outputs":[],"parameters":[],"snippets":[],"expectedBehavior":"","pitfalls":[]},"testPlan":["Each failure mode × 10 trials."],"measure":[{"metric":"Emergency-stop response","definition":"Failure → zero command (ms)."}],"document":["Validation report."],"integrate":"Controls safety case."},"legacy_keys":[],"archived":true,"external_team":"Controls","archived_reason":"Watchdogs that stop motors after link loss run on the Controls side. Autonomy''s contribution — timestamped requests with validity windows and contract tests — is part of AG-07.","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"357721b2-7e8e-5045-b3a3-485426873188","key":"CS-06","title":"Rover Motion Envelope Enforcement","track_id":"AG","subtrack_id":"b7e6ac48-c8c5-53f5-9767-258abf175bf5","priority":"medium","difficulty":"intermediate","estimate_hours":24,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":null,"start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["archived","advanced"],"spec":{"problem":"Commands may exceed safe speed/acceleration for terrain, slope or actuator state.","goal":"An envelope filter that limits velocity/acceleration based on state.","why":{"need":"Prevent tip-over and unsafe motion.","contribution":"Controls safety layer.","failureImpact":"Tipping on slopes with the bucket raised.","consumers":["Controls"]},"background":"State-dependent limits applied below autonomy.","prerequisites":[{"concept":"Kinematic limits","why":"Envelope.","resourceIds":["493e250b-6519-5d3e-9fe3-e3d641738a71"]}],"readFirst":["Velocity limiting patterns."],"references":[],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Filter between arbitration and the drivetrain (Controls-owned).","guidance":{"packageStructure":"","files":[],"inputs":[],"outputs":[],"parameters":[],"snippets":[],"expectedBehavior":"","pitfalls":[]},"testPlan":["Each state with excessive commands."],"measure":[{"metric":"Envelope violations","definition":"Commands exceeding limits reaching the drivetrain."}],"document":["Limit table."],"integrate":"Controls command chain."},"legacy_keys":[],"archived":true,"external_team":"Controls","archived_reason":"Enforcing speed/acceleration limits on the hardware is Controls-owned. Autonomy respects the limits Controls advertises through the AG-07 ControlsStatus message.","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"c0fd8886-dfe7-590d-8588-0f9bb65f4d11","key":"IT-05","title":"Autonomy Hardware-in-the-Loop Testing","track_id":"AG","subtrack_id":"b7e6ac48-c8c5-53f5-9767-258abf175bf5","priority":"low","difficulty":"expert","estimate_hours":40,"status":"backlog","status_before_blocked":null,"backlog":"advanced","sprint_id":null,"milestone_id":null,"start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["archived","advanced"],"spec":{"problem":"Simulation hides timing, driver and compute limits of real hardware.","goal":"A HIL setup running the autonomy stack on target compute with real or emulated sensors/actuators.","why":{"need":"Find hardware integration issues early.","contribution":"Joint autonomy/hardware validation.","failureImpact":"Compute limits discovered late.","consumers":["Controls","Electrical","Autonomy"]},"background":"HIL mixes real hardware with simulated environment inputs.","prerequisites":[{"concept":"Bringup","why":"AG-04.","resourceIds":["f25dec27-c4cf-5762-a7b9-9643f1443b1f"]}],"readFirst":["Hardware interfaces."],"references":[],"analyze":["Which assumptions from the prerequisite tasks does this depend on?","What is the smallest experiment that shows the approach is worth pursuing?","What result would make you stop and recommend against it?"],"design":"Bench HIL rig (joint effort with hardware teams).","guidance":{"packageStructure":"","files":[],"inputs":[],"outputs":[],"parameters":[],"snippets":[],"expectedBehavior":"","pitfalls":[]},"testPlan":["Mission subset on HIL with a safety observer."],"measure":[{"metric":"CPU utilization","definition":"On target compute."}],"document":["HIL procedure."],"integrate":"Joint validation."},"legacy_keys":[],"archived":true,"external_team":"Hardware","archived_reason":"Bench rigs with real actuators depend on Controls/Electrical hardware readiness. Autonomy''s current milestone is the simulated end-to-end mission (AG-08); revisit HIL jointly with the hardware teams later.","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"829c8465-3d52-5954-9682-ac7c2b7a11ed","key":"CS-01","title":"Drivetrain Controller","track_id":"AG","subtrack_id":"b7e6ac48-c8c5-53f5-9767-258abf175bf5","priority":"high","difficulty":"intermediate","estimate_hours":32,"status":"backlog","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":null,"start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["control","pid","odometry"],"spec":{"problem":"Navigation outputs body velocities (Twist). Motors need wheel speeds tracked by feedback control, with limits, and the rest of the stack needs wheel odometry back.","goal":"A drivetrain controller that receives velocity commands, computes wheel commands from kinematics, applies feedback control, enforces speed limits, generates wheel odometry, and is validated with trajectory-following tests and plots.","why":{"need":"Every autonomous motion goes through this controller.","contribution":"Executes NV-02 commands (via CS-02) and provides wheel odometry for SF-01.","failureImpact":"Poor tracking makes paths impossible to follow; wrong odometry corrupts localization.","consumers":["CS-02","SF-01","CS-03","NV-02"]},"background":"Differential drive: v_l = v − ω·W/2, v_r = v + ω·W/2. Wheel speed → RPM via radius and gear ratio. PID with feedforward tracks wheel velocity. Odometry integrates measured wheel speeds back to pose.","prerequisites":[{"concept":"Differential-drive kinematics","why":"Core math.","resourceIds":["493e250b-6519-5d3e-9fe3-e3d641738a71","0ed79493-fbed-5832-893a-c97ae10eff1b"]},{"concept":"PID control","why":"Velocity loops.","resourceIds":["63ce2bea-983e-5433-ba26-521b2ee04877"]},{"concept":"ros2_control","why":"Sim/hardware abstraction.","resourceIds":["c7bfc3a9-2e35-554f-a3d1-28f612361a6f","a7c43cc7-2baf-5cbb-81d6-c9e4467d3d7c"]}],"readFirst":["Purdue differential_drive_controller.py.","Purdue pid_controller.py.","ros2_controllers diff_drive_controller README."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_control/src/lunabot_control/differential_drive_controller.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_control/src/lunabot_control/differential_drive_controller.py","isFolder":false,"summary":"`DifferentialDriveController` node: subscribes to velocity commands, robot state and autonomy enable; a control loop converts to wheel RPM, constrains values, and stops on shutdown.","inspect":["`DifferentialDriveController._vel_cb`","`_robot_state_cb`","`_autonomy_cb`","`_loop`","`constrain(val)`","`meters_per_sec_to_rpm(vel)`","`shutdown_hook`"],"relevance":"Complete small controller from a Lunabotics team, including safe shutdown.","questions":["How does _loop combine command and feedback?","What happens when autonomy is disabled?","What does shutdown_hook command?"],"adaptation":"Prefer ros2_control''s diff_drive_controller if it fits; otherwise replicate this structure with parameters for all limits.","limitations":["Hardware-specific messages and units."],"verifiedOn":"2026-10-25"},{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_control/src/lunabot_control/pid_controller.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_control/src/lunabot_control/pid_controller.py","isFolder":false,"summary":"`VelocityPIDController` (with feedforward kf), `PIDController` (limits, tolerance, setpoint), and `ParameterizedPIDController` exposing gains as ROS parameters with a callback for live tuning.","inspect":["`VelocityPIDController.update(state, dt)`","`PIDController.calculate(state, dt, setpoint)`","`PIDController.set_max_value` / `set_tolerance`","`ParameterizedPIDController.parameter_cb`"],"relevance":"Live-tunable PID via parameters is exactly what tuning in sim needs.","questions":["Is there integral windup protection?","How is derivative computed (on error or measurement)?","How does parameter_cb validate new gains?"],"adaptation":"Reuse the ParameterizedPID idea; add anti-windup and derivative-on-measurement if missing.","limitations":["Check windup handling before reuse."],"verifiedOn":"2026-10-25"}],"analyze":["Write the kinematic equations used in the controller.","Identify units at each stage.","Decide: ros2_control diff_drive_controller vs custom node — justify."],"design":"Prefer `diff_drive_controller` via ros2_control (works with gz_ros2_control in sim and our hardware interface later). Configure limits, wheel geometry, odometry publishing (publish_tf false if SF-01 owns odom → base_link). Custom PID only in the hardware interface for wheel velocity if motor controllers lack it.","guidance":{"packageStructure":"lunabot_control/\n  config/controllers.yaml\n  launch/control.launch.py\n  scripts/track_test.py\n  scripts/plot_tracking.py","files":["config/controllers.yaml","launch/control.launch.py","scripts/track_test.py","scripts/plot_tracking.py"],"inputs":[{"name":"/cmd_vel","type":"geometry_msgs/msg/Twist","note":"Controls-owned input (external)"},{"name":"/joint_states","type":"sensor_msgs/msg/JointState"}],"outputs":[{"name":"/wheel/odometry","type":"nav_msgs/msg/Odometry","note":"proposed"},{"name":"wheel velocity commands","type":"ros2_control command interfaces"}],"parameters":[{"name":"wheel_separation / wheel_radius","default":"from SIM-02","description":"Kinematics."},{"name":"linear.x.max_velocity","default":"set with mechanical team","description":"Speed limit."},{"name":"enable_odom_tf","default":"false","description":"SF-01 owns odom → base_link."}],"snippets":[{"title":"Spawn the controller","label":"verified","language":"bash","code":"ros2 control list_controllers"},{"title":"Step test","label":"verified","language":"bash","code":"ros2 topic pub --rate 10 /cmd_vel geometry_msgs/msg/Twist \"{linear: {x: 0.3}}\""}],"expectedBehavior":"Commanded velocity is tracked with small steady-state error; limits clamp excessive commands; odometry matches ground truth on flat ground.","pitfalls":["Two odom → base_link publishers.","Wheel separation measured to wheel edge instead of center.","Ignoring acceleration limits causing wheel slip."]},"testPlan":["Step response per wheel.","Circle of known radius.","Odometry vs ground truth on flat ground.","Limit test with excessive commands."],"measure":[{"metric":"Tracking error","definition":"RMS of commanded − measured body velocity."},{"metric":"Odometry drift (flat)","definition":"Final position error over a 10 m loop."}],"document":["Kinematics and parameters.","Tuning procedure and plots."],"integrate":"CS-02 feeds it; SF-01 fuses its odometry; CS-03 monitors effort vs motion."},"legacy_keys":[],"archived":true,"external_team":"Controls","archived_reason":"Drivetrain kinematics, wheel PID and motor commands are Controls-owned. Autonomy consumes wheel odometry and publishes velocity requests through the AG-07 contract.","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"6f0c9d17-d505-5c48-982a-d053cce4daf9","key":"CS-02","title":"Teleoperation and Safety Arbitration","track_id":"AG","subtrack_id":"b7e6ac48-c8c5-53f5-9767-258abf175bf5","priority":"critical","difficulty":"intermediate","estimate_hours":32,"status":"backlog","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":null,"start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["safety","teleop","archived"],"spec":{"problem":"Autonomy, teleoperation and safety stops all want to command the drivetrain. Without a single arbiter with clear priority, stale autonomous commands can override a human, or a dropped link leaves the rover driving.","goal":"A command arbiter accepting autonomous and teleop commands with priority, manual takeover, stop states, stale-command rejection, watchdog behavior and deliberate recovery from emergency stop — demonstrated with fault injection, and documenting the need for hardware-level safety.","why":{"need":"Safety is the first requirement for any autonomous machine.","contribution":"The single gate between all command sources and CS-01.","failureImpact":"Runaway motion, ignored operator overrides, or unrecoverable stops.","consumers":["CS-01","NV-02","MS-01","IT-03"]},"background":"Priority multiplexing: each source has a priority and timeout; the highest-priority fresh source wins. A watchdog zeros output when nothing fresh arrives. E-stop is latched: once triggered, motion stays disabled until a deliberate reset — not merely when the stop signal clears. Software stops complement, never replace, a hardware E-stop.","prerequisites":[{"concept":"Topic timing and staleness","why":"Detect stale commands.","resourceIds":["54c635df-9476-5698-8046-9492aeb99971"]},{"concept":"State machines","why":"Latching E-stop.","resourceIds":["884a4786-fd54-5ef7-8b11-9e8784da5ec1"]},{"concept":"Priority multiplexers","why":"Arbitration design.","resourceIds":["5cbab412-d11d-5c62-9a84-6221ca149c71"]}],"readFirst":["COD controller_teleop.cpp — especially `emergency_stop_callback` and `mode_switch_callback`.","Purdue state_manager.py `stop_everything`.","twist_mux README."],"references":[{"repo":"College-of-DuPage-Lunabotics/lunabot_ros","path":"lunabot_teleop/src/controller_teleop.cpp","url":"https://github.com/College-of-DuPage-Lunabotics/lunabot_ros/blob/master/lunabot_teleop/src/controller_teleop.cpp","isFolder":false,"summary":"`ControllerTeleop` node: joystick and velocity inputs, GUI emergency-stop and manual/autonomous mode switch, camera control and goal sending for excavate/deposit, publishing motor commands and state.","inspect":["`emergency_stop_callback` — sets robot_disabled_ and publishes zero MotorCommands","`mode_switch_callback` — manual vs autonomous","`control_loop`","`joy_callback`","`velocity_callback`","`publish_state`"],"relevance":"Real teleop + E-stop + mode switching from a Lunabotics team.","questions":["When the E-stop message becomes false, the robot is re-enabled immediately — is that a deliberate recovery?","Which source wins when both joystick and autonomous velocity arrive?","Is there a timeout on velocity_callback inputs?"],"adaptation":"Keep the zero-on-stop behavior; add latching (require an explicit reset service), per-source timeouts and a published arbitration state.","limitations":["E-stop clears as soon as the signal is false (not latched).","Combines teleop UI handling with arbitration in one node."],"verifiedOn":"2026-10-25"},{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_behavior/lunabot_behavior/state_manager.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_behavior/lunabot_behavior/state_manager.py","isFolder":false,"summary":"`StateManager.stop_everything` / `stop_current_state` routines and autonomy enable callback.","inspect":["`stop_everything`","`autonomy_cb`"],"relevance":"How mission logic halts outputs when autonomy is disabled.","questions":["What outputs does stop_everything zero?","How should mission logic and the arbiter coordinate on stop?"],"adaptation":"Arbiter publishes its state; MS-01 transitions to SAFE_STOP when the arbiter reports E-stop.","limitations":["Mission-specific outputs."],"verifiedOn":"2026-10-25"}],"analyze":["Write the priority table for all sources.","List every failure (link loss, node crash, stale autonomy) and the required output.","Compare COD''s design with twist_mux."],"design":"Package `lunabot_safety`, node `cmd_arbiter`. Inputs: /cmd_vel/teleop (priority 100, timeout 0.3 s), /cmd_vel/auto (priority 10, timeout 0.5 s), /safety/estop (latched). Output /cmd_vel to CS-01. States: ESTOP (latched) > MANUAL > AUTO > IDLE. Reset via `~/reset_estop` service requiring estop signal false AND no motion commands for 1 s. Publishes /safety/arbiter_state. Optional speed limit input from SF-04 DEGRADED.","guidance":{"packageStructure":"lunabot_safety/\n  lunabot_safety/cmd_arbiter.py\n  lunabot_safety/arbiter_logic.py\n  config/arbiter.yaml\n  test/test_arbiter_logic.py\n  docs/hardware_safety.md","files":["cmd_arbiter.py","arbiter_logic.py","config/arbiter.yaml","test/test_arbiter_logic.py","docs/hardware_safety.md"],"inputs":[{"name":"/autonomy/cmd_vel","type":"geometry_msgs/msg/TwistStamped","note":"autonomy motion request — AG-07 contract (proposed)"},{"name":"/cmd_vel/teleop","type":"geometry_msgs/msg/Twist","note":"Controls-owned (external)"},{"name":"/controls/estop_state","type":"std_msgs/msg/Bool","note":"published by Controls; read-only for autonomy (proposed)"},{"name":"/localization/health","type":"diagnostic_msgs/msg/DiagnosticStatus","note":"proposed; may become a custom msg"}],"outputs":[{"name":"/cmd_vel","type":"geometry_msgs/msg/Twist","note":"Controls-owned input (external)"},{"name":"/safety/arbiter_state","type":"std_msgs/msg/String","note":"proposed"}],"parameters":[{"name":"sources","default":"[{teleop, 100, 0.3}, {auto, 10, 0.5}]","description":"Priority and timeout per source."},{"name":"watchdog_hz","default":"20","description":"Output rate; zeros when stale."},{"name":"degraded_speed_scale","default":"0.5","description":"Applied when localization DEGRADED."}],"snippets":[{"title":"Latching E-stop logic","label":"illustrative","language":"python","code":"if estop_msg.data:\n    self.state = ''ESTOP''\n# clearing the signal does NOT leave ESTOP; only reset_estop() does\ndef reset_estop(self, req, res):\n    res.success = (not self.estop_signal) and self.quiet_for() > 1.0\n    if res.success: self.state = ''IDLE''\n    return res"},{"title":"Trigger and reset","label":"illustrative","language":"bash","code":"ros2 topic pub --once /safety/estop std_msgs/msg/Bool \"{data: true}\"\nros2 service call /cmd_arbiter/reset_estop std_srvs/srv/Trigger"}],"expectedBehavior":"Teleop overrides autonomy instantly; stale sources are ignored; with no fresh input output is zero; E-stop zeros output and remains latched until reset.","pitfalls":["Re-enabling on E-stop signal clear (not latched).","Only zeroing once instead of continuously publishing zero.","Treating this as a substitute for the hardware E-stop."]},"testPlan":["Unit tests of arbiter_logic for every source/state combination.","Fault injection: kill each source mid-motion.","E-stop while driving; verify latched until reset.","Measure stop latency."],"measure":[{"metric":"Emergency-stop response","definition":"E-stop message → zero /cmd_vel (ms)."},{"metric":"Stale rejection latency","definition":"Source silence → output zero (ms)."}],"document":["Priority table and state diagram.","Hardware safety note."],"integrate":"NV-02 publishes to /cmd_vel/auto; IT-03 sends teleop and displays arbiter state; MS-01 reacts to ESTOP."},"legacy_keys":[],"archived":true,"external_team":"Controls","archived_reason":"Teleoperation, command arbitration, watchdogs and E-stop latching are Controls-owned. Autonomy''s side (timestamped requests, safe-stop requests, reacting to Controls status) is specified in AG-07.","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"},{"id":"f017944d-68c6-58dd-bc5b-59b608dd18b7","key":"CS-03","title":"Slip and Stall Detection","track_id":"AG","subtrack_id":"b7e6ac48-c8c5-53f5-9767-258abf175bf5","priority":"medium","difficulty":"intermediate","estimate_hours":24,"status":"backlog","status_before_blocked":null,"backlog":"initial","sprint_id":null,"milestone_id":null,"start_date":null,"due_date":null,"reviewer_id":null,"requires_independent_review":true,"claimable":false,"labels":["fault-detection","control"],"spec":{"problem":"In regolith, wheels can spin without moving (slip) or motors can push without turning (stall). Both waste time and can damage hardware; both corrupt wheel odometry.","goal":"A node that monitors commanded effort and measured motion, detects persistent stalls, compares wheel motion with independent odometry to flag slip, publishes fault states, requests recovery and is tested for false positives.","why":{"need":"Early detection prevents digging the rover in and protects motors.","contribution":"Feeds MS-02/MS-05 recovery and SF-01 (down-weight wheel odometry during slip).","failureImpact":"Undetected stalls burn motors; undetected slip makes localization drift.","consumers":["MS-01","MS-02","SF-01","SF-06"]},"background":"Stall: high effort with near-zero measured velocity, persisting for N cycles. Slip: wheel-derived velocity disagrees with an independent estimate (IMU/LIO) beyond a threshold. Persistence and hysteresis prevent false alarms during acceleration.","prerequisites":[{"concept":"Motor effort vs velocity","why":"Signals to compare.","resourceIds":["c7bfc3a9-2e35-554f-a3d1-28f612361a6f"]},{"concept":"Odometry sources","why":"Independent velocity reference.","resourceIds":["24908517-b857-5893-88e8-9bff94c9bcfb"]},{"concept":"Fault state machines","why":"Persistence and reset.","resourceIds":["884a4786-fd54-5ef7-8b11-9e8784da5ec1"]}],"readFirst":["Purdue stall_detector.py (≈70 lines)."],"references":[{"repo":"PurdueLunabotics/purdue_lunabotics","path":"lunabot_control/src/lunabot_control/stall_detector.py","url":"https://github.com/PurdueLunabotics/purdue_lunabotics/blob/master/lunabot_control/src/lunabot_control/stall_detector.py","isFolder":false,"summary":"`StallDetector` node: stores latest effort; on each sensors message, increments per-actuator counters (left/right drive, excavation) when |velocity| < 10 and |effort| > 100, sets stall flags when counters exceed `~waitTime`, publishes RobotStall and a STALL event.","inspect":["`StallDetector.effort_callback`","`StallDetector.sensors_callback` — counters, thresholds, flags, Event publishing","`~waitTime` parameter"],"relevance":"Straightforward persistence-counter stall detection for drive and excavation motors.","questions":["Stall flags are set True but never cleared in this callback — what are the consequences?","Thresholds (10, 100) are hard-coded — in what units?","The persistence is counted in messages, not seconds — why does that matter?"],"adaptation":"Use time-based persistence, parameterized thresholds, and explicit clear conditions with hysteresis; add slip detection against independent odometry.","limitations":["Flags never reset.","Hard-coded thresholds.","Message-count persistence depends on sensor rate."],"verifiedOn":"2026-10-25"}],"analyze":["Trace the counters for an acceleration from rest — would it false-trigger?","Determine units of effort/velocity in Purdue''s messages.","Choose the independent velocity reference for slip."],"design":"Node `motion_fault_detector` in `lunabot_safety`: per-wheel stall detection with time-based persistence and hysteresis; slip ratio = (v_wheel − v_ref)/max(|v_wheel|, ε) using /odometry/filtered or /lio/odometry as v_ref; publishes diagnostic status and fault events; clears after condition absent for hold time.","guidance":{"packageStructure":"lunabot_safety/\n  lunabot_safety/motion_fault_detector.py\n  lunabot_safety/fault_logic.py\n  config/motion_faults.yaml\n  test/test_fault_logic.py","files":["motion_fault_detector.py","fault_logic.py","config/motion_faults.yaml","test/test_fault_logic.py"],"inputs":[{"name":"/joint_states","type":"sensor_msgs/msg/JointState"},{"name":"/drivetrain/effort","type":"std_msgs/msg/Float64MultiArray","note":"proposed"},{"name":"/wheel/odometry","type":"nav_msgs/msg/Odometry","note":"proposed"},{"name":"/odometry/filtered","type":"nav_msgs/msg/Odometry","note":"robot_localization default"}],"outputs":[{"name":"/control/stall","type":"diagnostic_msgs/msg/DiagnosticStatus","note":"proposed"},{"name":"/control/slip","type":"diagnostic_msgs/msg/DiagnosticStatus","note":"proposed"}],"parameters":[{"name":"stall_effort_min","default":"tuned","description":"Effort threshold."},{"name":"stall_velocity_max","default":"tuned","description":"Velocity threshold."},{"name":"persist_s / clear_s","default":"0.5 / 1.0","description":"Hysteresis."},{"name":"slip_ratio_threshold","default":"tuned","description":"Slip detection."}],"snippets":[{"title":"Slip ratio","label":"illustrative","language":"python","code":"slip = (v_wheel - v_ref) / max(abs(v_wheel), 0.05)\nslipping = abs(slip) > cfg.slip_ratio_threshold"}],"expectedBehavior":"Blocking a wheel in sim triggers STALL after persist_s; low-traction scenarios (SIM-03) trigger SLIP; normal acceleration does not trigger either.","pitfalls":["Never clearing faults.","Message-count persistence.","Using the filtered odometry that itself fuses wheel odometry as the slip reference without accounting for that."]},"testPlan":["Unit tests for persistence and hysteresis.","Sim: blocked wheel → stall.","Sim: low traction (SIM-03) → slip.","Nominal driving 10 min → zero faults."],"measure":[{"metric":"Stall detection delay","definition":"Stall onset → fault published (ms)."},{"metric":"False positives","definition":"Fault events during nominal runs."}],"document":["Thresholds and rationale.","Test report."],"integrate":"MS-02 aborts on stall; SF-01/SF-06 can down-weight wheel odometry during slip."},"legacy_keys":[],"archived":true,"external_team":"Controls","archived_reason":"Motor stall detection from effort/current is Controls-owned. Autonomy-level slip estimation (wheel vs. independent odometry) is covered by the SF-06 benchmark suite; Controls reports stalls as faults through AG-07.","created_by":null,"created_at":"2026-10-25T12:00:00.000Z","updated_at":"2026-10-25T12:00:00.000Z","status_changed_at":"2026-10-25T12:00:00.000Z"}]'::jsonb) on conflict (id) do nothing;
