740579","task_id":"357721b2-7e8e-5045-b3a3-485426873188","order":0,"title":"Envelope filter","kind":"code","required":true},{"id":"99ac10ad-82e4-5f70-829f-aeb283342463","task_id":"357721b2-7e8e-5045-b3a3-485426873188","order":1,"title":"State-based tests","kind":"tests","required":true},{"id":"107bc2ef-6220-5ffd-95f9-6bd14af17e68","task_id":"357721b2-7e8e-5045-b3a3-485426873188","order":2,"title":"README / documentation","kind":"docs","required":true},{"id":"e9b3ca1e-b9c8-543f-bbcc-e63f76709880","task_id":"c0fd8886-dfe7-590d-8588-0f9bb65f4d11","order":0,"title":"HIL procedure and safety checklist","kind":"docs","required":true},{"id":"0b2a3d88-a33d-52b5-a8c1-2eba4eacd567","task_id":"c0fd8886-dfe7-590d-8588-0f9bb65f4d11","order":1,"title":"HIL results","kind":"benchmark","required":true},{"id":"ddde680d-9d24-5d4e-8e91-b645afd2bc84","task_id":"829c8465-3d52-5954-9682-ac7c2b7a11ed","order":0,"title":"Controller configuration / node","kind":"code","required":true},{"id":"73f2e51c-0ffc-5824-a445-36cd47c663bd","task_id":"829c8465-3d52-5954-9682-ac7c2b7a11ed","order":1,"title":"Tracking plots","kind":"benchmark","required":true},{"id":"af8c2e29-6215-5772-b358-3b12535d6ed9","task_id":"829c8465-3d52-5954-9682-ac7c2b7a11ed","order":2,"title":"Motion tests","kind":"tests","required":true},{"id":"1102f8d7-c5b7-5457-8037-9f4b8096bdbe","task_id":"829c8465-3d52-5954-9682-ac7c2b7a11ed","order":3,"title":"README / documentation","kind":"docs","required":true},{"id":"caa30d9d-eb6c-5517-afad-1bf77e13f442","task_id":"6f0c9d17-d505-5c48-982a-d053cce4daf9","order":0,"title":"Command arbiter","kind":"code","required":true},{"id":"d270596b-73f9-5cb0-a45c-61eca3f26a9e","task_id":"6f0c9d17-d505-5c48-982a-d053cce4daf9","order":1,"title":"Fault-injection demonstration","kind":"media","required":true},{"id":"eb899f79-194a-5956-8ff5-ef1083303f4a","task_id":"6f0c9d17-d505-5c48-982a-d053cce4daf9","order":2,"title":"Arbiter logic tests","kind":"tests","required":true},{"id":"62e2a717-6e65-5df7-977f-28fa8e51e935","task_id":"6f0c9d17-d505-5c48-982a-d053cce4daf9","order":3,"title":"Hardware safety and design note","kind":"docs","required":true},{"id":"b9a5ba07-e978-5f37-b65b-3899e8d9e498","task_id":"f017944d-68c6-58dd-bc5b-59b608dd18b7","order":0,"title":"Slip/stall detection node","kind":"code","required":true},{"id":"0c7e8b46-99ae-5b33-8ef1-e9e944776b21","task_id":"f017944d-68c6-58dd-bc5b-59b608dd18b7","order":1,"title":"Test report (detection delay, false positives)","kind":"benchmark","required":true},{"id":"ea4d0586-f078-5b3b-bdb5-fc8f61d3852c","task_id":"f017944d-68c6-58dd-bc5b-59b608dd18b7","order":2,"title":"Unit tests","kind":"tests","required":true},{"id":"989cd421-47f4-5ac0-91db-5316e2dbadba","task_id":"f017944d-68c6-58dd-bc5b-59b608dd18b7","order":3,"title":"README / documentation","kind":"docs","required":true}]'::jsonb) on conflict (id) do nothing;
insert into task_acceptance_criteria select * from jsonb_populate_recordset(null::task_acceptance_criteria, '[{"id":"1d56496b-6eaf-5068-a04a-443b7ed21521","task_id":"20c6ab88-05ca-5add-b926-411b30386c9c","order":0,"text":"Every state has a defined transition for localization loss, Controls fault and cancellation; the table is fully unit-tested.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"7e636401-3aa9-5510-9529-c832284e841d","task_id":"20c6ab88-05ca-5add-b926-411b30386c9c","order":1,"text":"At least two consecutive autonomous cycles complete in simulation against the mock excavation/deposition servers.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"e1ca2be1-bf2a-5be6-8c12-7cd5f908015c","task_id":"20c6ab88-05ca-5add-b926-411b30386c9c","order":2,"text":"The mission package publishes no motor, actuator or wheel commands; Safe Stop is a request through the AG-07 interface.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"20276e95-9b0c-5bf0-88f2-41e1f9d1d595","task_id":"c4795d19-bd20-5bdd-9bfd-253e4fc310ab","order":0,"text":"The client produces exactly one mission event per request, with a reason, for success, failure, cancellation, timeout and server unavailability.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"ec865efc-f21e-5520-b853-ee7b2a143162","task_id":"c4795d19-bd20-5bdd-9bfd-253e4fc310ab","order":1,"text":"No actuator positions, motor powers or hardware commands appear in the contract or the autonomy code.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"af2f51a5-56ee-51d6-b65f-11ec9a7e3db6","task_id":"c4795d19-bd20-5bdd-9bfd-253e4fc310ab","order":2,"text":"Controls has reviewed the interface document (comment or sign-off linked in the task).","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"5553c02f-0f92-504b-a189-846fee80dac5","task_id":"7bafdba8-75f3-5a8d-ac0a-9882a055c76e","order":0,"text":"A deposit is never requested unless alignment and localization confidence are validated.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"2a8775fb-7f9e-58e9-917b-e5fe595d37eb","task_id":"7bafdba8-75f3-5a8d-ac0a-9882a055c76e","order":1,"text":"Every outcome (success, failure, cancel, timeout) produces one mission event with a reason.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"02a12ca2-063a-52f0-89bb-b4292deda5c6","task_id":"7bafdba8-75f3-5a8d-ac0a-9882a055c76e","order":2,"text":"Demonstrated in simulation from at least three start poses against the mock server.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"1d3bd24f-a370-571f-91fe-89ad005e63f3","task_id":"5d60e9c6-9e3a-5f3c-8935-3ce633fb9855","order":0,"text":"A clean clone builds and launches the sim bringup using only README commands.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"5fbcecb5-023f-558d-8d37-b4337f6a1b30","task_id":"5d60e9c6-9e3a-5f3c-8935-3ce633fb9855","order":1,"text":"Topic and TF contract tables are published and reviewed by each track lead.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"f720b23a-6a5f-5d88-bedd-2d4ea21d4ed1","task_id":"5d60e9c6-9e3a-5f3c-8935-3ce633fb9855","order":2,"text":"use_sim_time is consistent across all launched nodes.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"d45ab651-8529-5a4a-865f-d0591d512987","task_id":"7a4f5bbb-c23d-5204-b744-a7bc2d348122","order":0,"text":"Replayed tests produce reproducible outputs within documented tolerance.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"c39bd703-53a9-5ee8-84d0-2f145770888d","task_id":"7a4f5bbb-c23d-5204-b744-a7bc2d348122","order":1,"text":"At least three scenarios have stored baseline results with commit hash.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"02a38b74-588e-5ab8-a36f-65ad02bd3474","task_id":"7a4f5bbb-c23d-5204-b744-a7bc2d348122","order":2,"text":"A deliberately introduced regression is detected.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"4a96f4b5-d71a-53ec-b903-2169a8f19f83","task_id":"5d9ab24b-f42c-511a-a0f2-b14783e48c9d","order":0,"text":"Displays estimated position, localization confidence, perception status, planned route, mission state, faults and subsystem health from simulated or replayed data.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"0a44b52a-3ef1-5bb0-99db-bf41cf666be5","task_id":"5d9ab24b-f42c-511a-a0f2-b14783e48c9d","order":1,"text":"The only outputs are confirmed autonomy mission requests; no velocity, actuator or E-stop topics are published.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"5f69198b-61d0-5eda-84d4-f677971756ea","task_id":"5d9ab24b-f42c-511a-a0f2-b14783e48c9d","order":2,"text":"Ground truth (when shown) is visually distinct from estimates.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"ab5483da-8442-58be-bf10-a1097a4b599a","task_id":"e5839c37-c400-51c0-b926-2e44b2993145","order":0,"text":"The specification covers motion commands, limits, timestamps/validity, feedback, faults, enable/disable and safe-stop requests, with units and an ownership table.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"8a7eafdc-a7a4-50f9-8bc6-095249771475","task_id":"e5839c37-c400-51c0-b926-2e44b2993145","order":1,"text":"Navigation runs in simulation through the adapter and mock with no direct motor-level messages from autonomy.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"79d96757-22e9-5a40-a029-2b723aa578f0","task_id":"e5839c37-c400-51c0-b926-2e44b2993145","order":2,"text":"Contract tests pass against the mock, and the Controls lead has reviewed the spec (linked comment or sign-off).","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"009f159e-7d3d-5553-a60f-a43091db63c1","task_id":"495d9c18-8a65-5cdc-ac45-b603c7e63687","order":0,"text":"Pass criteria were committed before the first evaluated run.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"ce11db0a-b779-5d3f-8bf9-da0854bd0aed","task_id":"495d9c18-8a65-5cdc-ac45-b603c7e63687","order":1,"text":"From a clean bringup, using estimated localization, the rover completes ≥ 1 full excavate→deposit cycle unattended in simulation, with a linked recording and bag.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"3bf8e0fa-2c3a-540b-bcc4-2dc1952c8863","task_id":"495d9c18-8a65-5cdc-ac45-b603c7e63687","order":2,"text":"Each fault variant ends in a documented recovery or safe stop.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"d5bc6b20-b476-52ee-a146-104a92fecd08","task_id":"ad5ad035-2683-5642-9a09-3ec5b942a38e","order":0,"text":"Fused odometry publishes on /odometry/filtered with valid (non-zero, positive) covariance and correct frame_ids.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"58232b34-b467-5091-86e1-a7f050d21e56","task_id":"ad5ad035-2683-5642-9a09-3ec5b942a38e","order":1,"text":"Exactly one publisher owns the odom → base_link transform; TF tree is consistent in `ros2 run tf2_tools view_frames`.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"56a437ef-d1a0-5b48-a057-6d269fe7c089","task_id":"ad5ad035-2683-5642-9a09-3ec5b942a38e","order":2,"text":"A reproducible comparison of wheel-only and fused localization exists, runnable from documented commands.","target":"Fused ATE < wheel-only ATE in the slip scenario","rationale":"Internal engineering goal; demonstrates value of fusion. Not a competition requirement.","verified":false,"verified_by":null},{"id":"52577283-cdbe-54fc-9504-62e4f66cbe5a","task_id":"ad5ad035-2683-5642-9a09-3ec5b942a38e","order":3,"text":"Results include the slip scenario and describe degradation and recovery behavior.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"0b8e443f-c7af-5b0f-8e5f-d4b86aca2a07","task_id":"f05ffa4c-b505-5dda-a737-b97c3901fca2","order":0,"text":"All expected sensor frames exist under base_link with no duplicate publishers.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"23f115b9-864a-528b-b213-5939e4fb0538","task_id":"f05ffa4c-b505-5dda-a737-b97c3901fca2","order":1,"text":"Transform utilities pass round-trip and known-rotation unit tests.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"f7b0bac3-7a4b-5d05-bf7d-324af9ed23cc","task_id":"f05ffa4c-b505-5dda-a737-b97c3901fca2","order":2,"text":"Synthetic hand-eye test recovers a known transform.","target":"< 1 cm and < 1° with the documented noise level","rationale":"Internal goal; sufficient for costmap resolution of 5–10 cm.","verified":false,"verified_by":null},{"id":"3892467b-5a7c-5a39-b069-5682a2937304","task_id":"f05ffa4c-b505-5dda-a737-b97c3901fca2","order":3,"text":"Calibration output is consumable by launch without manual editing.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"7fef2837-8f30-5590-ade6-2cd8ec3a9315","task_id":"e3919c33-0c0b-50fb-a063-8680deadc484","order":0,"text":"LIO runs on simulated data from documented commands and publishes nav_msgs/Odometry with frame_ids consistent with the TF tree.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"760a99d6-16d3-5872-92dc-5a6866eebdf2","task_id":"e3919c33-0c0b-50fb-a063-8680deadc484","order":1,"text":"Benchmark compares LIO against at least wheel-only and SF-01 fused on identical bags, with drift and latency.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"633132fe-a222-5ea1-ad82-10e517b3bb34","task_id":"e3919c33-0c0b-50fb-a063-8680deadc484","order":2,"text":"Failure modes (degenerate geometry, bad init) are reproduced and documented.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"f242a390-d352-5029-9322-8baf7fbd39b2","task_id":"2581b052-1712-55fc-8b1e-50ada3c5a0f4","order":0,"text":"Status transitions to DEGRADED/LOST within the configured timeout after inputs stop (verified in the dropout test).","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"4c006308-3581-523c-9e78-bbc9a6bc3c81","task_id":"2581b052-1712-55fc-8b1e-50ada3c5a0f4","order":1,"text":"Recovery requires healthy inputs for the full hold period; no flapping in the threshold test.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"a5a79c88-a928-59c3-a2f5-33dd17c8754a","task_id":"2581b052-1712-55fc-8b1e-50ada3c5a0f4","order":2,"text":"Mission logic receives the status and performs a documented safe response in simulation.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"184134ae-d654-5224-9281-3945aa890f06","task_id":"9a90482b-015a-5d7a-89b9-149227bf65a7","order":0,"text":"Costmap distinguishes traversable, dangerous and unknown terrain using valid OccupancyGrid values.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"5a823930-331f-5eaf-a97d-0c77c59da0a5","task_id":"9a90482b-015a-5d7a-89b9-149227bf65a7","order":1,"text":"Obstacles are inflated by the documented rover footprint.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"6d4a4b32-ec30-58d3-a460-7a7a62cd2732","task_id":"9a90482b-015a-5d7a-89b9-149227bf65a7","order":2,"text":"Map remains world-aligned while the rover moves (no origin jumping).","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"196f860f-7844-58f8-bae6-4caa55643cc7","task_id":"9a90482b-015a-5d7a-89b9-149227bf65a7","order":3,"text":"All four scenario types are tested with recorded evidence.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"d2d34e76-559b-582f-8ce2-d2dde5bb68b3","task_id":"5da4dde9-125f-5417-b116-5417115ab06b","order":0,"text":"Output cloud contains no invalid points and no rover self-hits in the stationary test.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"dd4c08b4-3959-5aed-8615-69084a4d5120","task_id":"5da4dde9-125f-5417-b116-5417115ab06b","order":1,"text":"Every stage is configurable by parameter and can be disabled.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"6a9e819f-f0cc-55ec-9772-91dc32d1bc2d","task_id":"5da4dde9-125f-5417-b116-5417115ab06b","order":2,"text":"Benchmark reports runtime, density and latency for at least three configurations on the same bag.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"903fca45-9e12-5338-86d6-71cffd6287d1","task_id":"efd58f27-b4c0-5056-a2fc-2b97eb2b54d9","order":0,"text":"Tags are detected and converted to a map-frame pose with covariance.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"cc768d0d-c637-5542-acd7-6cdc084f98a3","task_id":"efd58f27-b4c0-5056-a2fc-2b97eb2b54d9","order":1,"text":"Pose error is reported against ground truth across distance and angle.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"55d6c925-72a6-536c-9b68-c3e5145c00cf","task_id":"efd58f27-b4c0-5056-a2fc-2b97eb2b54d9","order":2,"text":"Competition-use restrictions are documented with a citation to the official rules.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"8974337b-8d1a-5419-be47-0dfdd275e883","task_id":"9844330b-91a8-5120-9ae7-3ef106e02e75","order":0,"text":"Every claimed modality or label is backed by an inspected sample in the notebook.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"a4f9cb52-f763-503a-a4cc-b145147295f6","task_id":"9844330b-91a8-5120-9ae7-3ef106e02e75","order":1,"text":"Formats, metadata and timestamps found (or absent) are documented.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"4ac729d8-2ec5-5748-995c-b53920df7608","task_id":"9844330b-91a8-5120-9ae7-3ef106e02e75","order":2,"text":"A feasibility assessment lists at least one go/no-go benchmark decision with rationale.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"c4008274-87be-5563-b87e-b0adad85e789","task_id":"e5fd0912-0a1b-5c05-9f43-7afa095f3392","order":0,"text":"Paths are collision-free under the rover footprint model on all benchmark maps.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"2bd17f6b-68ba-5564-9624-416fb8ceefab","task_id":"e5fd0912-0a1b-5c05-9f43-7afa095f3392","order":1,"text":"Both planners handle unreachable goals without hanging.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"3bc33733-25b1-5e31-9157-33a07f97c61f","task_id":"e5fd0912-0a1b-5c05-9f43-7afa095f3392","order":2,"text":"Benchmark compares runtime, length, clearance and turns on identical maps.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"18a3878f-2fd2-56e4-bdb1-ad8a4a8c61de","task_id":"3f3aa0af-f122-53ba-b2d5-514fa557a5d3","order":0,"text":"Rover completes a multi-waypoint mission in simulation using estimated (not ground-truth) localization.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"ceb88387-8ab5-56a1-9906-b22ae69326d6","task_id":"3f3aa0af-f122-53ba-b2d5-514fa557a5d3","order":1,"text":"Invalid paths trigger replanning; documented recovery runs before failure.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"f9624dc2-1e56-5e4f-a209-8e58623ca4bf","task_id":"3f3aa0af-f122-53ba-b2d5-514fa557a5d3","order":2,"text":"Unreachable goals fail cleanly within the configured retry count.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"d6813f31-1633-5641-bed7-29b635a9ad67","task_id":"3f3aa0af-f122-53ba-b2d5-514fa557a5d3","order":3,"text":"Velocity requests are published only on the AG-07 autonomy command topic (mock Controls in simulation); no motor or wheel-level commands are produced.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"8b15a364-5cd8-5ebc-bf92-96df7e655dc9","task_id":"92da24a3-0466-5f74-a27a-1ef9b8ebf26d","order":0,"text":"Goals are always inside the requested zone with footprint margin and never in forbidden regions.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"f5e950c0-a976-5b7a-8042-13a3edc228eb","task_id":"92da24a3-0466-5f74-a27a-1ef9b8ebf26d","order":1,"text":"Selection is reproducible for a given scenario file.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"3ba9f36a-f02d-5138-bad7-ba240f388abf","task_id":"92da24a3-0466-5f74-a27a-1ef9b8ebf26d","order":2,"text":"Goals are recomputed when the chosen target becomes blocked.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"21a97f7a-b656-572b-86cb-179d1478cda5","task_id":"09619c19-1fd4-570a-9b85-09d2daaf5308","order":0,"text":"Arena launches from documented commands, with and without GUI.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"7068a5f8-f06e-57ac-9af1-91eec456743b","task_id":"09619c19-1fd4-570a-9b85-09d2daaf5308","order":1,"text":"At least three scenarios load deterministically from a seed.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"a8d96f6c-291f-54df-ae09-c1ffdc8a0a04","task_id":"09619c19-1fd4-570a-9b85-09d2daaf5308","order":2,"text":"Every arena dimension cites a verified source or is listed as an assumption.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"7fdf7efe-65f8-510d-84c5-d12b39e58b53","task_id":"c37c65ff-e04e-5bfa-954c-54142f9de733","order":0,"text":"Model passes check_urdf and spawns stably in Gazebo.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"95f432d0-8a0a-5ecb-9dce-74ab41a3243b","task_id":"c37c65ff-e04e-5bfa-954c-54142f9de733","order":1,"text":"All sensor frames exist once and match SF-02 names.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"1596cb40-5f3e-5144-a798-b3500c5674dd","task_id":"c37c65ff-e04e-5bfa-954c-54142f9de733","order":2,"text":"Every dimension is tagged Mechanical-verified or a labeled approximation with its source and date.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"78f052ea-cbdd-560c-9131-d2855fc0d08d","task_id":"c37c65ff-e04e-5bfa-954c-54142f9de733","order":3,"text":"The simulated drivetrain responds to the AG-07 mock command topic within joint limits.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"a5da9073-19b7-5edd-a20c-ca6423d6fc49","task_id":"a23aa979-4242-51a9-afcc-47b07572c622","order":0,"text":"Each listed fault type is reproducible from a scenario file and seed.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"380a5a3f-8b77-539e-9565-04155d3171c6","task_id":"a23aa979-4242-51a9-afcc-47b07572c622","order":1,"text":"Impact on localization and navigation is measured against a clean baseline.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"fedf879d-1b2f-5118-a478-4492079619c2","task_id":"a23aa979-4242-51a9-afcc-47b07572c622","order":2,"text":"Limitations of the physics approximation are documented.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"9462580a-d197-5480-9d7f-77a5abc36a4a","task_id":"3edf045c-1999-5599-9447-b50de03cf966","order":0,"text":"Every sensor specification is cited or explicitly marked as assumed.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"6d78fd04-6fac-5b09-97b7-2ab6e49a62ed","task_id":"3edf045c-1999-5599-9447-b50de03cf966","order":1,"text":"LiDAR-only and fused results are compared on identical simulated scenarios.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"f555f76d-1c9c-581d-9bd0-3085b81c3338","task_id":"3edf045c-1999-5599-9447-b50de03cf966","order":2,"text":"No hardware driver code is produced; requirements for Electrical are stated if radar is recommended.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"a17702b7-a5d3-50d1-977e-ce3e14b0395c","task_id":"566176c5-5c46-5f15-bd4a-4ada34f50988","order":0,"text":"The suite covers noise, wheel slip, IMU drift, delay, missing data and sensor disagreement.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"bdf8891a-9d31-56a9-bd76-6b7747aceb1e","task_id":"566176c5-5c46-5f15-bd4a-4ada34f50988","order":1,"text":"Repeated runs produce identical metrics.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"94307898-6c7f-5e40-bcb9-65e7817bf912","task_id":"566176c5-5c46-5f15-bd4a-4ada34f50988","order":2,"text":"Baseline results exist for at least two SF-01 configurations.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"2333b152-e71f-5f7e-a9e3-7818f537c763","task_id":"5a0e5477-9883-58c7-877a-ac25ced72821","order":0,"text":"Pose, covariance, freshness, status and (in simulation) drift are visible together.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"0b6d4764-f630-5dcf-bf26-a9a8eff19213","task_id":"5a0e5477-9883-58c7-877a-ac25ced72821","order":1,"text":"Ground-truth elements are labeled and disabled outside simulation.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"64c95239-2650-515d-a360-3cf94b085f5c","task_id":"5a0e5477-9883-58c7-877a-ac25ced72821","order":2,"text":"Demonstrated on an SF-06 dropout scenario.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"778e5a92-dcae-529b-a4bb-37abd94179d6","task_id":"76b564b8-3f3b-52de-83f6-b5a68a386e3b","order":0,"text":"Compared to fixed covariance on identical SF-06 scenarios.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"1b64c395-8e67-5cc5-858e-8c4f0ca6a3bd","task_id":"76b564b8-3f3b-52de-83f6-b5a68a386e3b","order":1,"text":"Covariance stays positive definite in all tests.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"961a3f88-d59c-519b-8934-679e9f0cc5ab","task_id":"76b564b8-3f3b-52de-83f6-b5a68a386e3b","order":2,"text":"Results include any cases where adaptation hurts.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"fc8cd2bb-cbdd-5d8e-913c-2aef3b45e11a","task_id":"97e7e67b-a11b-5c72-8d47-7c2817b698a3","order":0,"text":"Metrics are computed only on labeled data with the label source documented.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"cbf200ad-b2c2-56b3-9ae4-8d8315a0c0e2","task_id":"97e7e67b-a11b-5c72-8d47-7c2817b698a3","order":1,"text":"Classical and vision baselines are compared on the same scenes.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"d837e714-efb1-5d04-b0db-2ac1facbdb7e","task_id":"97e7e67b-a11b-5c72-8d47-7c2817b698a3","order":2,"text":"Detections are published in the map frame.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"7e657b89-0a0e-52ba-9e07-04599cf11045","task_id":"094cc510-dcd7-5c6f-8dca-311ca9451998","order":0,"text":"Map persists terrain outside the current view.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"b36679bf-f746-5f54-96fd-5b5da3e0094a","task_id":"094cc510-dcd7-5c6f-8dca-311ca9451998","order":1,"text":"Slope error on known simulated slopes is reported.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"13811205-b597-5b97-ae94-851f2296c47f","task_id":"094cc510-dcd7-5c6f-8dca-311ca9451998","order":2,"text":"Traversability layers are consumable by NV-04.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"200d04c0-2909-5611-a168-320a9552b201","task_id":"31122c6b-661e-5e87-8f88-aadb4ed34024","order":0,"text":"Degradation levels are parameterized and reproducible.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"22436424-8e45-5e2b-ad89-bc7a1997b2d2","task_id":"31122c6b-661e-5e87-8f88-aadb4ed34024","order":1,"text":"Impact is measured against a clean baseline per modality.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"9aaddb70-d212-5786-bb05-c8455164b962","task_id":"31122c6b-661e-5e87-8f88-aadb4ed34024","order":2,"text":"Realism limitations and fallback options are documented.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"f70eae0f-3f1e-5cd6-abe3-b03600589b95","task_id":"1f6b83bd-3a06-5e37-b97a-5c5f1f8bf4d1","order":0,"text":"Each true obstacle maps to at most one track in test scenes.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"5cdae3bd-a0e2-5695-933e-4f91062db3c5","task_id":"1f6b83bd-3a06-5e37-b97a-5c5f1f8bf4d1","order":1,"text":"Contradictory evidence lowers confidence rather than flipping state.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"5226050f-7099-59dc-95b0-82ad7a09c485","task_id":"1f6b83bd-3a06-5e37-b97a-5c5f1f8bf4d1","order":2,"text":"Works with at least two modalities.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"03f5e55e-7de2-534c-9efe-5f5b9693fd19","task_id":"83662f45-9f4c-58a7-a326-95399a8568ba","order":0,"text":"Marks obstacles in dust scenarios where LiDAR-only misses them, or the report explains why not.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"cb76e6bb-9352-5ea6-b9ad-6c9279c9637d","task_id":"83662f45-9f4c-58a7-a326-95399a8568ba","order":1,"text":"False-positive rate is measured.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"52d16997-cdd5-5254-8ac3-4cb2102897da","task_id":"83662f45-9f4c-58a7-a326-95399a8568ba","order":2,"text":"No driver code; the detection contract is agreed with Electrical.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"a4e98193-ae86-56b4-8f23-6afa47359411","task_id":"e8bd3d32-3ba4-5ab6-9096-41e34c32cb1f","order":0,"text":"Weights are derived from recorded data.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"89fac7bf-6768-5574-80d0-a14f02178615","task_id":"e8bd3d32-3ba4-5ab6-9096-41e34c32cb1f","order":1,"text":"Compared with distance-only on identical scenarios.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"a9e2f156-bda4-5b59-8c20-cad9f589f0de","task_id":"e8bd3d32-3ba4-5ab6-9096-41e34c32cb1f","order":2,"text":"No increase in collisions.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"1fcaf774-01fa-5697-b503-09e673d99c06","task_id":"60c6c8ef-b084-5ca3-b80c-5526db1c3382","order":0,"text":"At least two controllers compared on identical scenarios.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"8bf3b9ac-7931-59c3-a157-eeec13e0aac7","task_id":"60c6c8ef-b084-5ca3-b80c-5526db1c3382","order":1,"text":"Commands respect the AG-07 advertised limits; no motor-level output.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"9b7130fb-e179-5dc7-8b5c-343a07b2ca85","task_id":"60c6c8ef-b084-5ca3-b80c-5526db1c3382","order":2,"text":"Low-traction scenario included.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"e437620a-2898-5ef8-97c0-6ffd548c87af","task_id":"abb74e9b-c86b-5989-a011-066e0cf96267","order":0,"text":"All five failure types have a tested behavior.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"602e72c1-7d10-5fe1-8689-71a78a3f80a0","task_id":"abb74e9b-c86b-5989-a011-066e0cf96267","order":1,"text":"Retries are bounded and outcomes are reported to mission logic.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"01646228-e3e4-5538-9299-19fafd2388a1","task_id":"abb74e9b-c86b-5989-a011-066e0cf96267","order":2,"text":"Behaviors that worsen regolith situations are identified.","target":null,"rationale":null,"verified":false,"verified_by":null},{"id":"f1de1607-